                        [197705] = 
                        {
                            ["tags"] = "Light, Interactable",
                            ["name"] = "Telvanni Alchemy Station",
                            ["description"] = "With components inspired by a variety of cultures, this alchemy station not only helps you mix all manner of ingredients into useful potions, but also adds a touch of all things Tamriel to your home.",
