                        [197706] = 
                        {
                            ["tags"] = "Visual FX",
                            ["name"] = "Trifold Mirror of Alternatives",
                            ["description"] = "\"May your wardrobe reflect the dark sophistication of this mirror trio. It's not my style, but when I look deeply into your eyes, I think it suits you more than you may think.\"—Fairwen of Vulkhel Guard",
