                            ["quality"] = "Epic",
                        },
                        [197709] = 
                        {
                            ["tags"] = "Light",
                            ["name"] = "Tribunal Window, Stained Glass",
                            ["description"] = "Bring the light of the Tribunal into your home with this stained glass window. Featuring rich colors, this sacred art piece can serve as the focal point of your personal shrine to ALMSIVI.",
                            ["id"] = 197709,
                            ["subcategory"] = "Enchanted Lights",
                            ["category"] = "Lighting",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_anttribunalu38stainedglass001.dds",
                            ["quality"] = "Epic",
                        },
                        [197710] = 
                        {
                            ["tags"] = "Animated, Interactable",
                            ["name"] = "Mushroom Classification Book",
                            ["description"] = "Flip through the illustrated pages of this Telvanni library staple. While it may not share the deep knowledge that mycoturges possess, it can serve as an entertaining conversation starter at your next gathering.",
                            ["id"] = 197710,
                            ["subcategory"] = "Literature",
                            ["category"] = "Library",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mushroombook001.dds",
                            ["quality"] = "Epic",
                        },
                        [197711] = 
                        {
                            ["description"] = "The fine detail work on the coastlines contrasts strongly with inland portions of the map. Almost as if House Telvanni had little interest in a truly accurate depiction of the peninsula.",
                            ["name"] = "Antique Map of the Telvanni Peninsula",
                            ["category"] = "Library",
