                        },
                        [156753] = 
                        {
                            ["tags"] = "Visual FX, Interactable, Audible",
                            ["name"] = "Khenarthi's Windbells",
                            ["description"] = "These replica bells might not \"find things\" as Za'ji says, but they lend a visual reminder of Khenarthi's grace to any location. May the winds favor you and yours.",
                            ["id"] = 156753,
                            ["subcategory"] = "Instruments",
                            ["category"] = "Parlor",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_sebellstandsmall001.dds",
                            ["quality"] = "Legendary",
                        },
                        [156754] = 
                        {
                            ["description"] = "The restoration of the Dragonguard and renovation of the sanctum led to a startling discovery: ancient sarcophagi containing the order's honored dead. Fearing future conflict on the island, Sai Sahan has placed these legendary warriors in your charge.",
                            ["name"] = "Dragonguard Sarcophagus",
