                        },
                        [156756] = 
                        {
                            ["tags"] = "Audible, Interactable",
                            ["name"] = "Khenarthic Bell",
                            ["description"] = "Known for their cleansing properties, Khenarthic Bells abound in shrines and other places sacred to the Goddess of the Winds. This replica bell might not remove corruption, but its presence can remind onlookers to take a moment and breathe mindfully.",
                            ["id"] = 156756,
                            ["subcategory"] = "Instruments",
                            ["category"] = "Parlor",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_sebellstandlarge001.dds",
                            ["quality"] = "Legendary",
                        },
                        [156757] = 
                        {
                            ["tags"] = "Animated",
                            ["name"] = "New Moon Cult Banner, Large",
                            ["description"] = "Promising much to vulnerable Khajiit, the Order of the New Moon provides a place for them to go. Yet, in halls strewn with banners such as these, many find more than they expect … or want.",
