                        [182302] = 
                        {
                            ["tags"] = "Crafting Station",
                            ["name"] = "Daedric Enchanting Station",
                            ["description"] = "Who knows what vile enchantments took shape on this Daedric worktable? Perhaps you can craft something even darker. When placed in your home, this crafting station allows you to craft Enchantment items.",
                            ["id"] = 182302,
                            ["subcategory"] = "Crafting Stations",
                            ["category"] = "Services",
                            ["icon"] = "/esoui/art/icons/housing_bad_inc_dedenchantingtable001.dds",
                            ["quality"] = "Legendary",
                        },
                        [182303] = 
                        {
                            ["description"] = "Fear is a tool best used in moderation, but when you must turn to it, be ready with the appropriate accessories. This torture device, for instance—even looking at it may cause some to spill their secrets.",
                            ["name"] = "Dagon's Scalding Gibbet",
                            ["category"] = "Undercroft",
                            ["id"] = 182303,
                            ["subcategory"] = "Torture",
                            ["icon"] = "/esoui/art/icons/housing_bad_inc_dedtorturedevice001.dds",
                            ["quality"] = "Epic",
                        },
                        [182304] = 
                        {
                            ["description"] = "How this skeleton of a burned tree once grew here remains a mystery.",
                            ["name"] = "Tree, Charred Dagonic",
                            ["category"] = "Conservatory",
                            ["id"] = 182304,
                            ["subcategory"] = "Dead Wood",
                            ["icon"] = "/esoui/art/icons/housing_tre_bad_deadlandtotem004.dds",
                            ["quality"] = "Epic",
                        },
                        [182305] = 
                        {
                            ["tags"] = "Light",
                            ["name"] = "Deadlands Window, Stormglass",
                            ["description"] = "While most associate Deadlands architecture with fiery reds, the deep blues of a churning sea are no less intimidating. Let the cold light of a rising flood wash over you when standing before this Daedric window.",
                            ["id"] = 182305,
                            ["subcategory"] = "Enchanted Lights",
                            ["category"] = "Lighting",
                            ["icon"] = "/esoui/art/icons/housing_bad_duc_housingdedslwindow001.dds",
                            ["quality"] = "Legendary",
                        },
                        [182306] = 
                        {
                            ["description"] = "No place of worship dedicated to the Prince of Destruction can be called such without this altar. If you can't please Mehrunes Dagon, best make sure you don't anger him by lacking this centerpiece.",
                            ["name"] = "Daedric Altar, Mehrunes Dagon",
                            ["category"] = "Undercroft",
                            ["id"] = 182306,
                            ["subcategory"] = "Symbolic Decor",
                            ["icon"] = "/esoui/art/icons/housing_bad_exc_housingdagonaltar001.dds",
                            ["quality"] = "Superior",
                        },
                        [182307] = 
                        {
                            ["tags"] = "Interactable, Visual FX",
                            ["name"] = "Deadlands Lightning Rod, Etched",
                            ["description"] = "If you dare to live among the storms of the Sever, be sure to place plenty of lightning rods around. The fact that these might scare off cowardly mortals is a welcome perk.",
                            ["id"] = 182307,
                            ["subcategory"] = "Yard Ornaments",
                            ["category"] = "Courtyard",
                            ["icon"] = "/esoui/art/icons/housing_bad_exc_housingsllightningrod006.dds",
                            ["quality"] = "Legendary",
                        },
                        [182308] = 
                        {
                            ["tags"] = "Animated",
                            ["name"] = "Deadlands Wind Gate Pinion",
                            ["description"] = "This majestic stone structure draws the gaze even as it dominates the landscape. Perfect as a focal piece in your courtyard or bit of Oblivion.",
                            ["id"] = 182308,
                            ["subcategory"] = "Symbolic Decor",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_bad_exc_housingwindgate001.dds",
                            ["quality"] = "Epic",
                        },
                        [182309] = 
                        {
                            ["description"] = "Decorate and support your walls in Daedric style with this towering buttress. While it won't stop Dagon himself from entering your abode if he wishes, lesser beings might reconsider any plans to besiege your residence.",
                            ["name"] = "Deadlands Buttress, Large",
                            ["category"] = "Undercroft",
                            ["id"] = 182309,
                            ["subcategory"] = "Symbolic Decor",
                            ["icon"] = "/esoui/art/icons/housing_bad_str_dedbirthingmachinepart004.dds",
                            ["quality"] = "Superior",
                        },
                        [182310] = 
                        {
                            ["description"] = "For those needing added structural support for their walls, this Daedric-themed buttress serves the purpose while adding a touch of dread to your home.",
                            ["name"] = "Deadlands Buttress",
                            ["category"] = "Undercroft",
                            ["id"] = 182310,
                            ["subcategory"] = "Symbolic Decor",
                            ["icon"] = "/esoui/art/icons/housing_bad_str_dedbirthingmachinepartsmall004.dds",
                            ["quality"] = "Superior",
                        },
                        [182311] = 
                        {
                            ["description"] = "Every second-rate baron needs a platform on which to stand. But why settle for second-rate mortal sovereignty when you can go full doom and destruction with this Daedric-themed platform?",
                            ["name"] = "Deadlands Platform, Octagonal",
                            ["category"] = "Structures",
                            ["id"] = 182311,
                            ["subcategory"] = "Platforms",
                            ["icon"] = "/esoui/art/icons/housing_bad_str_dedplatform002.dds",
                            ["quality"] = "Superior",
                        },
                        [182312] = 
                        {
                            ["description"] = "This inert displacer might not whisk you off to points unknown, but it will lend any room you place it in an air of arcane mystery!",
                            ["name"] = "Deadlands Displacer, Inactive",
                            ["category"] = "Undercroft",
                            ["id"] = 182312,
                            ["subcategory"] = "Symbolic Decor",
                            ["icon"] = "/esoui/art/icons/housing_bad_str_dedteleportpadsmall001.dds",
                            ["quality"] = "Superior",
                        },
                        [182313] = 
                        {
                            ["description"] = "Though this item is a mere replica of a real portal key, the memories it unlocks for you can be priceless. Maybe a bit hair-raising, but definitely priceless.",
