                        [165990] = 
                        {
                            ["tags"] = "Visual FX",
                            ["name"] = "Mammoth Cheese, Pungent",
                            ["description"] = "Some folk diplomatically state that mammoth cheese is an acquired taste. Others argue that its smell is not only pervasive but even aggressive—to the point that you don't need to eat it to taste it.",
