                        [165991] = 
                        {
                            ["tags"] = "Light, Interactable, Visual FX",
                            ["name"] = "Statue, Vampiric Sovereign",
                            ["description"] = "The vile enchantments placed upon this statue make it a grim reminder of a vampire's power. Whether cloaked in bats, imbued with dark energies, or wreathed in flame, weak-hearted mortals will never forget the sight of it.",
