                        [151781] = 
                        {
                            ["tags"] = "Animated",
                            ["name"] = "Banner, Anequina",
                            ["description"] = "The arid northern region of Elsweyr, called Anequina, has bred hearty warriors and pragmatic thinkers, though some have learned to work the land. Show your respect for the traditions of Anequina by hanging this banner in your abode.",
                            ["id"] = 151781,
                            ["subcategory"] = "Banners",
                            ["category"] = "Parlor",
                            ["icon"] = "/esoui/art/icons/housing_els_lsb_anequinabannersmall002.dds",
                            ["quality"] = "Superior",
                        },
                        [151782] = 
                        {
                            ["description"] = "Khajiit of Anequina often build cairns of local stone to mark their dead. Perhaps you need such structures for your own land?",
                            ["name"] = "Khajiit Burial Mound",
                            ["category"] = "Undercroft",
                            ["id"] = 151782,
                            ["subcategory"] = "Grave Goods",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_burialmound001.dds",
                            ["quality"] = "Fine",
                        },
                        [151783] = 
                        {
                            ["description"] = "This replica of the Dragon Horn found in Anequina can lend a certain air of majesty to your home or landscape. You might find cats or even Alfiq making use of it as a comfy sleeping spot.",
                            ["name"] = "Replica Dragon Horn, Large",
                            ["category"] = "Gallery",
                            ["id"] = 151783,
                            ["subcategory"] = "Art",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_akavaridragonhorn001.dds",
                            ["quality"] = "Legendary",
                        },
                        [151784] = 
                        {
                            ["description"] = "Have an alcove that needs a touch of ancient charm? This small Dragon Horn replica is perfection itself for just such a space!",
                            ["name"] = "Replica Dragon Horn, Small",
                            ["category"] = "Gallery",
                            ["id"] = 151784,
                            ["subcategory"] = "Art",
