                        [193818] = 
                        {
                            ["tags"] = "Interactable",
                            ["name"] = "Shad Astula Scholar, Right",
                            ["description"] = "Graduates of Shad Astula Academy often possess fond memories of learning several schools of magic by studying the scholar statues. Alteration, Conjuration, Destruction, Illusion, and Restoration—each setting provides insight for the careful observer.",
                            ["id"] = 193818,
                            ["subcategory"] = "Statues",
                            ["category"] = "Courtyard",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_rightpriest001.dds",
                            ["quality"] = "Legendary",
                        },
                        [193817] = 
                        {
                            ["tags"] = "Interactable",
                            ["name"] = "Shad Astula Scholar, Left",
                            ["description"] = "Within a week of arriving, Shad Astula Academy students must spend a few hours studying magical energies at the feet of the paired statues. They can call upon the schools of Alteration, Conjuration, Destruction, Illusion, and Restoration as they like.",
                            ["id"] = 193817,
                            ["subcategory"] = "Statues",
                            ["category"] = "Courtyard",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_leftpriest001.dds",
                            ["quality"] = "Legendary",
                        },
                        [193815] = 
                        {
                            ["description"] = "Though it currently holds a delicate scroll that the scholars of Scrivener's Hall studied, this wooden podium from Craglorn may serve you well for other forms of written knowledge.",
                            ["name"] = "Craglorn Podium, Filled",
                            ["category"] = "Library",
                            ["id"] = 193815,
                            ["subcategory"] = "Desks",
                            ["icon"] = "/esoui/art/icons/housing_cra_fur_podium003.dds",
                            ["quality"] = "Superior",
                        },
                        [193814] = 
                        {
                            ["description"] = "Originally designed for use in Mournhold to honor Almalexia, grand archways like this one stand in other locations as well. The one in Bal Sunnar purportedly served to remind the Telvanni Dark Elves of their reverence for Mother Morrowind.",
                            ["name"] = "Dark Elf Archway, Stone",
                            ["category"] = "Structures",
