                            ["name"] = "Verkarth Senche-Lioness",
                            ["hint"] = "",
                            ["id"] = 6246,
                            ["description"] = "This sleek and light-hued mount hails from Verkarth, where some warriors drill both night and day to earn the right to train a young one as a battle mount. Now more widely available, you too can add one to your stable.",
                            ["furnitureId"] = 5900,
                            ["icon"] = "/esoui/art/icons/senchevariantd.dds",
                            ["category"] = "Felines",
                        },
                        [103] = 
                        {
                            ["name"] = "Solitude Silver Wolf",
                            ["hint"] = "Acquired by completing the \"The Vampire Scholar\" quest in Western Skyrim.",
                            ["id"] = 103,
                            ["description"] = "Common sights around Solitude, these steadfast and fierce wolves also adorn the heraldry of that city. All of them are, of course, good wolves, and befriending one brings you good fortune in the land of the Nords!",
                            ["furnitureId"] = 4188,
                            ["icon"] = "/esoui/art/icons/pet_solitudewolf.dds",
                            ["category"] = "Exotic",
                        },
                        [104] = 
                        {
                            ["name"] = "Skeletal Pony Guar",
                            ["hint"] = "",
                            ["id"] = 104,
                            ["description"] = "Shouldn't an animated skeleton always be a thing of fear and revulsion? This necromantic Pony Guar might change your mind about that!",
