                            ["icon"] = "/esoui/art/icons/pet_bergamafennecfox.dds",
                            ["category"] = "Exotic",
                        },
                        [10349] = 
                        {
                            ["name"] = "Gideon Trail Dog",
                            ["hint"] = "",
                            ["id"] = 10349,
                            ["description"] = "Trails through the thick marshlands outside Gideon change with every passing storm. Hunters in the city bred these dogs to be light enough not to get stuck in the muck and trained their noses to detect new paths of sure footing.",
                            ["furnitureId"] = 8406,
                            ["icon"] = "/esoui/art/icons/pet_gideontraildog.dds",
                            ["category"] = "Domestic",
                        },
                        [111] = 
                        {
                            ["name"] = "Fennec Fox",
                            ["hint"] = "",
                            ["id"] = 111,
                            ["description"] = "A native of Hammerfell, the Fennec Fox has been domesticated by many of its desert peoples, and makes an alert and loyal pet.",
                            ["furnitureId"] = 4193,
                            ["icon"] = "/esoui/art/icons/pet_027.dds",
                            ["category"] = "Exotic",
                        },
                        [112] = 
                        {
                            ["name"] = "Purple Daggerback",
                            ["hint"] = "",
                            ["id"] = 112,
                            ["description"] = "The glowing Purple Daggerback boar is found only in Craglorn in the vicinity of the Spellscar, from which it seems to have absorbed some sort of magical aura.",
                            ["furnitureId"] = 4194,
                            ["icon"] = "/esoui/art/icons/pet_028.dds",
                            ["category"] = "Exotic",
