                        [113] = 
                        {
                            ["name"] = "Mind-Shriven Horse",
                            ["hint"] = "",
                            ["id"] = 113,
                            ["description"] = "With its equine psyche stolen by Daedric magic, the mind-shriven horse is a docile yet terrifying mount.",
                            ["furnitureId"] = 4195,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_m.dds",
                            ["category"] = "Equines",
                        },
                        [114] = 
                        {
                            ["name"] = "Red Pit Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 114,
                            ["description"] = "The Red Pit Wolves of southern Skyrim are known for their aggression and ferocity, and you can see that even in their puppies, adorable as they are. They love to play, but that means play-fighting, so expect to get chewed on as you tussle!",
                            ["furnitureId"] = 4196,
                            ["icon"] = "/esoui/art/icons/pet_084.dds",
                            ["category"] = "Exotic",
                        },
                        [12413] = 
                        {
                            ["name"] = "Eri, Barking Banker",
                            ["hint"] = "",
                            ["id"] = 12413,
                            ["description"] = "Eri has been expertly trained by Nord beast tamers to act as a very good (such a good!) personal banker for you and your groupmates. \n\nHe doesn't venture to Cyrodiil or the Battlegrounds. Too much violence, not enough pets.",
                            ["furnitureId"] = 9825,
                            ["icon"] = "/esoui/art/icons/assistant_erithebanker.dds",
                            ["category"] = "Assistants",
                        },
                        [12414] = 
                        {
                            ["name"] = "Xyn, Planar Purveyor",
                            ["hint"] = "",
                            ["id"] = 12414,
                            ["description"] = "Xyn travels the Daedric realms looking for profitable opportunities. They'll happily take your goods (or those of your groupmates) in exchange for common mortal coinage.\n\nAncient bindings prevent them from appearing in Cyrodiil or Battlegrounds.",
                            ["furnitureId"] = 9826,
                            ["icon"] = "/esoui/art/icons/assistant_xynthemerchant.dds",
