                        [12426] = 
                        {
                            ["name"] = "Snowclaw Senche-Serval",
                            ["hint"] = "",
                            ["id"] = 12426,
                            ["description"] = "\"People say you should be wary of shadows, but what about blinding white snow? When you get disoriented in a blizzard, when you can't tell up from down anymore, that's when the snowclaws will strike! I can feel it.\"—Last journal entry of Hunter Keedru",
                            ["furnitureId"] = 9881,
                            ["icon"] = "/esoui/art/icons/mount_snowclawsencheserval.dds",
                            ["category"] = "Felines",
                        },
                        [12428] = 
                        {
                            ["name"] = "Ashur",
                            ["hint"] = "",
                            ["id"] = 12428,
                            ["description"] = "As an assassin in the Morag Tong, Ashur takes his work deathly seriously. Invite him to stay and you need never worry about uninvited visitors. After adding Ashur to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 9882,
                            ["icon"] = "/esoui/art/icons/houseguest_ashur.dds",
                            ["category"] = "Houseguests",
                        },
                        [12429] = 
                        {
                            ["name"] = "Necrom Guard Miraso",
                            ["hint"] = "",
                            ["id"] = 12429,
                            ["description"] = "After a Necrom ancestor spirit persuaded her to see more of the world, Miraso decided to accomplish this by taking on jobs in private residences across Tamriel and beyond. Will you take her on? After adding Miraso to your home, you can set her on a path.",
                            ["furnitureId"] = 9883,
                            ["icon"] = "/esoui/art/icons/houseguest_necromguard.dds",
                            ["category"] = "Houseguests",
                        },
                        [10382] = 
                        {
                            ["name"] = "Vale Sabre Cat Growler",
                            ["hint"] = "",
                            ["id"] = 10382,
                            ["description"] = "Bards in Skyrim claim these luminous sabre cats gain their glow from Kyne. Scholars in the College of Sapiarchs refute this, each with their own pet hypotheses. Everyone agrees that this growler's fur is silky soft and its rumbling purr soothing.",
                            ["furnitureId"] = 8407,
                            ["icon"] = "/esoui/art/icons/mount_valesabrecatgrowler.dds",
                            ["category"] = "Felines",
                        },
                        [143] = 
                        {
                            ["name"] = "Baby Netch",
                            ["hint"] = "",
                            ["id"] = 143,
                            ["description"] = "Once this young Netch calf imprints on a master, it will follow him or her anywhere, floating along and tootling happily.",
                            ["furnitureId"] = 4201,
                            ["icon"] = "/esoui/art/icons/pet_037.dds",
                            ["category"] = "Flying Pets",
                        },
                        [144] = 
                        {
                            ["name"] = "Ninendava Sacred Goat",
                            ["hint"] = "",
                            ["id"] = 144,
                            ["description"] = "The goats that come from the ruin of Ninendava in Cyrodiil are no mere domestic livestock. They have long been used in certain forbidden Daedric rituals—and have even been known to lead mortals through those arcane rites.",
                            ["furnitureId"] = 4202,
                            ["icon"] = "/esoui/art/icons/pet_035.dds",
                            ["category"] = "Domestic",
                        },
                        [145] = 
                        {
                            ["name"] = "Bal Foyen Nix-Hound",
                            ["hint"] = "",
                            ["id"] = 145,
                            ["description"] = "Who says a giant, aggressive, blood-sucking insect can't make a loveable pet? Not the Dark Elves of Bal Foyen, who breed them as trackers, watch-hounds, and netch-deflators.",
                            ["furnitureId"] = 4203,
                            ["icon"] = "/esoui/art/icons/pet_033.dds",
                            ["category"] = "Exotic",
                        },
                        [10386] = 
                        {
                            ["name"] = "Jouster's Charger",
                            ["hint"] = "",
                            ["id"] = 10386,
                            ["description"] = "\"Though these fellows work the tilt-yard like a dream, they're trained to the field, too. You never know when you'll need a finely barded steed to get you across those fancy sunflower fields you see around High Isle.\"—Perien Jerrick, Castle Navire",
                            ["furnitureId"] = 8409,
                            ["icon"] = "/esoui/art/icons/mount_cavalrybarding.dds",
                            ["category"] = "Equines",
                        },
                        [10387] = 
                        {
                            ["name"] = "Sadrith Mora Spore Pony",
                            ["hint"] = "",
                            ["id"] = 10387,
                            ["description"] = "Telvanni magisters use only the hardiest of the fire-hued fungi when magically coercing it into a new form. Whether one such magister crafted these pleasantly companionable spore ponies causes snippy disagreements among mages and scholars alike.",
                            ["furnitureId"] = 8410,
                            ["icon"] = "/esoui/art/icons/pet_sadrithmorasporepony.dds",
                            ["category"] = "Exotic",
                        },
                        [10388] = 
                        {
                            ["name"] = "Sadrith Mora Spore Steed",
                            ["hint"] = "",
                            ["id"] = 10388,
                            ["description"] = "Softly spoken words cut apart those who claim a mere Telvanni mage crafted this spore steed. The correction—an archmagister brought this russet and amber glory into being—gently flays the soul of the ignorant s'wit. As it should.",
                            ["furnitureId"] = 8411,
                            ["icon"] = "/esoui/art/icons/mount_sadrithmorasporesteed.dds",
                            ["category"] = "Equines",
                        },
                        [149] = 
                        {
                            ["name"] = "Stonefire Scamp",
                            ["hint"] = "A rare reward from defeating the elite Daedric forces and their master in the Darkest Depths.\n\nCan also be acquired from the Impresario during Guilds and Glory.",
                            ["id"] = 149,
                            ["description"] = "This gibbering, foul-smelling Daedric minion will follow you loyally, though it won't fight for you.",
                            ["furnitureId"] = 4204,
                            ["icon"] = "/esoui/art/icons/pet_036.dds",
                            ["category"] = "Daedric",
                        },
                        [6294] = 
                        {
                            ["name"] = "Statuette: Malacath, Orc-Father",
                            ["hint"] = "",
                            ["id"] = 6294,
                            ["description"] = "A miniature statue of the Daedric Prince Malacath, the Orc-Father.",
