                            ["icon"] = "/esoui/art/icons/housing_vrd_inc_housingstatuemalacath002.dds",
                            ["category"] = "General",
                        },
                        [151] = 
                        {
                            ["name"] = "Cave Bear",
                            ["hint"] = "",
                            ["id"] = 151,
                            ["description"] = "Found throughout Tamriel's northern mountains, the Cave Bear makes a hardy and imposing mount.",
                            ["furnitureId"] = 4206,
                            ["icon"] = "/esoui/art/icons/mounticon_bear_a.dds",
                            ["category"] = "Ursines",
                        },
                        [153] = 
                        {
                            ["name"] = "Copperback Bear-Dog",
                            ["hint"] = "",
                            ["id"] = 153,
                            ["description"] = "The Copperback variant of the Markarth Bear-Dog is renowned for its responsiveness to training, but keep an eye on it, or will get into all sorts of mischief. Especially keep an eye on its eyes, which are two different colors!",
                            ["furnitureId"] = 4207,
                            ["icon"] = "/esoui/art/icons/pet_079.dds",
                            ["category"] = "Domestic",
                        },
                        [155] = 
                        {
                            ["name"] = "Fiendroth",
                            ["hint"] = "",
                            ["id"] = 155,
                            ["description"] = "Who doesn't want to be followed around by a hulking, armored Daedric bug with steel mandibles and a venomous stinger? It eats nothing but the cries and lamentations of your enemies, so it's an easy keeper. Friendly, too—in its way.",
                            ["furnitureId"] = 4208,
                            ["icon"] = "/esoui/art/icons/pet_039.dds",
                            ["category"] = "Daedric",
                        },
                        [156] = 
                        {
                            ["name"] = "Pocket Mammoth",
                            ["hint"] = "",
                            ["id"] = 156,
                            ["description"] = "Pocket Mammoths were originally bred small in order to make them more manageable as livestock, but in Wrothgar some escaped and began breeding in the wild. However, they're easily domesticated, especially if you get one when it's young.",
                            ["furnitureId"] = 4209,
                            ["icon"] = "/esoui/art/icons/pet_052.dds",
                            ["category"] = "Exotic",
                        },
                        [157] = 
                        {
                            ["name"] = "Dragontail Goat",
                            ["hint"] = "",
                            ["id"] = 157,
                            ["description"] = "The brown Goats of the Dragontail Mountains are stronger than they look. There's a saying in Hammerfell: \"Hits as hard as a Dragontail ram!\"",
                            ["furnitureId"] = 4210,
                            ["icon"] = "/esoui/art/icons/pet_042.dds",
                            ["category"] = "Domestic",
                        },
                        [158] = 
                        {
                            ["name"] = "Sanguine's Black Goat",
                            ["hint"] = "",
                            ["id"] = 158,
                            ["description"] = "A goat bred to take part in Daedric rituals? Nonsense. It's just a goat. Isn't it? But why does it look at you like that? And did it just … whisper? No. It's just a goat!",
                            ["furnitureId"] = 4211,
                            ["icon"] = "/esoui/art/icons/pet_041.dds",
                            ["category"] = "Domestic",
                        },
                        [159] = 
                        {
                            ["name"] = "Chub Loon",
                            ["hint"] = "",
                            ["id"] = 159,
                            ["description"] = "A denizen of Tamriel's northern shores, the Chub Loon survives on the bounty of the sea, dining on small fish of all types. Though clumsy and awkward on shore, it flies gracefully and is a nimble swimmer. Best of all, they make affectionate pets.",
                            ["furnitureId"] = 4212,
                            ["icon"] = "/esoui/art/icons/pet_051.dds",
                            ["category"] = "Exotic",
                        },
                        [160] = 
                        {
                            ["name"] = "Echalette",
                            ["hint"] = "Acquired by traveling to Orsinium for the first time.",
                            ["id"] = 160,
                            ["description"] = "Full-grown echateres may be stubborn and ornery, but the baby Echalettes are playful and, frankly, just plain adorable. Once a young Echalette bonds with its master, it becomes a devoted companion.",
                            ["furnitureId"] = 4213,
                            ["icon"] = "/esoui/art/icons/pet_050.dds",
                            ["category"] = "Exotic",
                        },
                        [12449] = 
                        {
                            ["name"] = "Sepulchral Swamp Jelly",
                            ["hint"] = "",
                            ["id"] = 12449,
                            ["description"] = "\"Things that sink in the swamp never truly leave the cold embrace of the muck. Their tormented ends infuse the very land itself, haunting and changing the few living creatures that survive in that wretched place.\"—Swamp Songs: A History",
                            ["furnitureId"] = 9886,
                            ["icon"] = "/esoui/art/icons/pet_deathsheadswampjelly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [163] = 
                        {
                            ["name"] = "Necrotic Hoarvor",
                            ["hint"] = "Acquired by completing the \"Imperial City Challenger\" achievement in the Imperial City.",
                            ["id"] = 163,
                            ["description"] = "Your new best friend is a giant blood-sucking insect bloated with pustulant, lethal contagion! It's bursting with both infection and affection—for you!",
                            ["furnitureId"] = 4214,
                            ["icon"] = "/esoui/art/icons/pet_038.dds",
                            ["category"] = "Exotic",
                        },
                        [164] = 
                        {
                            ["name"] = "Skeletal Horse",
                            ["hint"] = "",
                            ["id"] = 164,
                            ["description"] = "Behold the Skeletal Horse! Mortal races are not the only creatures that can be re-animated by necromancers. The best part: no need to muck out the stable.",
                            ["furnitureId"] = 4215,
                            ["icon"] = "/esoui/art/icons/mounticon_skeletalhorse_a.dds",
                            ["category"] = "Equines",
                        },
                        [165] = 
                        {
                            ["name"] = "Skeletal Senche",
                            ["hint"] = "",
                            ["id"] = 165,
                            ["description"] = "The Skeletal Senche may be the most fearsome of all feline mounts. Expertly re-animated, even in undead form it retains all the lithe strength it possessed in life.",
                            ["furnitureId"] = 4216,
                            ["icon"] = "/esoui/art/icons/mounticon_skeletalsenche_a.dds",
                            ["category"] = "Felines",
                        },
                        [166] = 
                        {
                            ["name"] = "Skeletal Guar",
                            ["hint"] = "",
                            ["id"] = 166,
                            ["description"] = "The naked, grisly smile on the broad skull of the Skeletal Guar mount may be enough to send lesser opponents fleeing in terror when you ride into battle on its creaking, bony frame. The Worm Cult, of course, will just be jealous.",
                            ["furnitureId"] = 4217,
                            ["icon"] = "/esoui/art/icons/mounticon_skeletalguar_a.dds",
                            ["category"] = "Bipedals",
                        },
                        [10408] = 
                        {
                            ["name"] = "Rigurt the Brash",
                            ["hint"] = "",
                            ["id"] = 10408,
                            ["description"] = "The Nord diplomat Rigurt travels around Tamriel to learn about other cultures while demonstrating his own brand of Nord culture. Welcome him home! After adding Rigurt to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 8426,
