                            ["name"] = "Brahgas",
                            ["hint"] = "Acquired by completing the \"Tales of Tribute Master\" achievement.",
                            ["id"] = 10410,
                            ["description"] = "Brahgas loves playing Tales of Tribute but needs a break to shake off some bad luck. Perhaps a fellow player like you can put him up for a bit? After adding Brahgas to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 8428,
                            ["icon"] = "/esoui/art/icons/houseguest_bragas.dds",
                            ["category"] = "Houseguests",
                        },
                        [12459] = 
                        {
                            ["name"] = "Doomcrag Salamander",
                            ["hint"] = "",
                            ["id"] = 12459,
                            ["description"] = "It's rumored that these little amphibians may be as long-lived as the Ayleids themselves used to be. Found only in Rivenspire near the Erokii Ruins, they are highly prized for their unique coloration and ability to regrow their own missing limbs.",
                            ["furnitureId"] = 9889,
