                        },
                        [12460] = 
                        {
                            ["name"] = "Oliis Bay Fellrunner",
                            ["hint"] = "",
                            ["id"] = 12460,
                            ["description"] = "Native to the southeastern region of the Black Marsh, these fellrunners are adept at hunting in the marshy terrain. Though their pecks can be quite swift, they clack their beaks with joy when greeting their owners and favorite people.",
                            ["furnitureId"] = 9890,
