                        [591] = 
                        {
                            ["name"] = "Great Elk",
                            ["hint"] = "",
                            ["id"] = 591,
                            ["description"] = "Though the Reachmen of Markarth say they were the first to successfully domesticate the Great Elk of Skyrim and break them as mounts, the Nords of Haafingar say it was really all their idea.\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4298,
                            ["icon"] = "/esoui/art/icons/mount_elk_a.dds",
                            ["category"] = "Cervines",
                        },
                        [592] = 
                        {
                            ["name"] = "Dozen-Banded Vvardvark",
                            ["hint"] = "",
                            ["id"] = 592,
                            ["description"] = "This creature, unusually cute for a denizen of Vvardenfell, is a newcomer to the island whose home and origin are unknown—unless the rumors are true that it's a hybrid born from the magical laboratories of the Telvanni.",
                            ["furnitureId"] = 4299,
                            ["icon"] = "/esoui/art/icons/pet_139.dds",
