                            ["name"] = "Painting: Systres Archipelago",
                            ["hint"] = "",
                            ["id"] = 10846,
                            ["description"] = "A painting by Vaudrie Barthel, well-known for her landscapes and scenes depicting life and nature in the Systres Isles.",
                            ["furnitureId"] = 8612,
                            ["icon"] = "/esoui/art/icons/housing_sys_inc_housingkeyartpainting002.dds",
                            ["category"] = "General",
                        },
                        [607] = 
                        {
                            ["name"] = "Cobalt Sep Adder",
                            ["hint"] = "",
                            ["id"] = 607,
                            ["description"] = "The blue-scaled Cobalt Sep Adder is the rarest of the wild varieties, and almost never seen in captivity. They are particularly prized by the royalty of Hammerfell's contentious city-states, as they're said to be able to detect poison in drinks and food.",
                            ["furnitureId"] = 4300,
                            ["icon"] = "/esoui/art/icons/pet_063.dds",
                            ["category"] = "Exotic",
                        },
                        [608] = 
                        {
                            ["name"] = "Storm Atronach Wolf",
                            ["hint"] = "",
                            ["id"] = 608,
                            ["description"] = "The Storm Atronach Wolf was the favored mount of the notorious Hjeimar the Heinous, a wizard who lived in a remote tower north of Bruma, who rode his when leading his Goblin Fiends in raids on the nearby valleys.",
                            ["furnitureId"] = 4301,
                            ["icon"] = "/esoui/art/icons/mounticon_atronach_wolf_a.dds",
                            ["category"] = "Canines",
                        },
                        [609] = 
                        {
                            ["name"] = "Black Senche-Lion",
                            ["hint"] = "",
                            ["id"] = 609,
                            ["description"] = "The legendary preferred mount of Elsweyr's greatest thieves, the most famous Black Senche-Lion of all was Rajhin's mount Umbrage, which could both talk and, for brief periods, fly!",
                            ["furnitureId"] = 4302,
                            ["icon"] = "/esoui/art/icons/mount_senche_h.dds",
                            ["category"] = "Felines",
                        },
                        [10851] = 
                        {
                            ["name"] = "Blightlord's Skeever",
                            ["hint"] = "",
                            ["id"] = 10851,
                            ["description"] = "\"I'd heard that Peryite followers wake up to find their skeevers transformed by his blessing. Never really thought about it until I woke up next to one. We're fine now, but by my Prince's pustules, those first moments got my battle rage up.\"—Yamighu",
                            ["furnitureId"] = 8620,
                            ["icon"] = "/esoui/art/icons/pet_scabberskeever.dds",
                            ["category"] = "Exotic",
                        },
                        [10852] = 
                        {
                            ["name"] = "Apocryphal Bookwyrm",
                            ["hint"] = "",
                            ["id"] = 10852,
                            ["description"] = "Some claim these curious Daedric wyrms from Apocrypha devour books to vouchsafe the knowledge for their master. Others believe cultists of Hermaeus Mora use these creatures to hunt tomes long thought lost. Perhaps you know the truth?",
                            ["furnitureId"] = 8621,
                            ["icon"] = "/esoui/art/icons/pet_bookwyrm.dds",
                            ["category"] = "Exotic",
                        },
                        [4709] = 
                        {
                            ["name"] = "Fang Lair Courser",
                            ["hint"] = "Acquired in the Dragon Bones DLC Collector's Bundle.",
                            ["id"] = 4709,
                            ["description"] = "In Fang Lair, not even ancient warriors' steeds are safe from reanimation by necromancers! Though to be fair, if you're looking for \"grimly impressive,\" this is the mount for you.",
                            ["furnitureId"] = 4940,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_fanglair.dds",
                            ["category"] = "Equines",
                        },
                        [4710] = 
                        {
                            ["name"] = "Masqued \"Unicorn\" Steed",
                            ["hint"] = "",
                            ["id"] = 4710,
                            ["description"] = "Is that the famed and incredibly-rare creature of legend, the true Unicorn from Hircine's Oblivion realm of the Hunting Grounds? …Well, no, it's a horse with a horn attached to its forehead. But the effect—it's just so magical!",
                            ["furnitureId"] = 4954,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_unicorn.dds",
                            ["category"] = "Equines",
                        },
                        [10855] = 
                        {
                            ["name"] = "Trophy: Euphotic Gatekeeper",
                            ["hint"] = "Awarded for completing the Graven Deep.",
                            ["id"] = 10855,
                            ["description"] = "Trophy taken from the Euphotic Gatekeeper in honor of an Undaunted victory in Graven Deep.",
                            ["furnitureId"] = 8627,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyhadolidboss001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [4712] = 
                        {
                            ["name"] = "True Ghost Horse",
                            ["hint"] = "",
                            ["id"] = 4712,
                            ["description"] = "Not a spectre, not a zombie, not a horse of a spooky color—the True Ghost Horse is the actual shade of a deceased mount, returned from beyond the equine grave.",
                            ["furnitureId"] = 4774,
                            ["icon"] = "/esoui/art/icons/mounticon_ghosthorse_a.dds",
                            ["category"] = "Equines",
                        },
                        [4713] = 
                        {
                            ["name"] = "Manelord Nightmare Senche",
                            ["hint"] = "",
                            ["id"] = 4713,
                            ["description"] = "King of the Nightmare Pride, this night-black senche-tiger has burning paws and flames hissing from its face; rumor says Mehrunes Dagon is responsible.",
                            ["furnitureId"] = 4941,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_i.dds",
                            ["category"] = "Felines",
                        },
                        [4714] = 
                        {
                            ["name"] = "Frostbane Horse",
                            ["hint"] = "",
                            ["id"] = 4714,
                            ["description"] = "The ancient Nords who came to Skyrim with Ysgramor worshiped animal totems, and adorned their mounts with symbolic hair-knots and hide strips meant to protect their livestock from the frigid climate. These  \"Frostbane\" talismans are still in use today!",
                            ["furnitureId"] = 4944,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_scalecaller.dds",
                            ["category"] = "Equines",
                        },
                        [4720] = 
                        {
                            ["name"] = "Dragonfire Wolf",
                            ["hint"] = "",
                            ["id"] = 4720,
                            ["description"] = "Ancient legends from the time of the Dragon Wars tell of Dragon Knights riding into battle mounted on colossal flaming wolves. Were they wolf mounts mystically imbued with Dragonfire? Flame Atronachs conjured in the form of wolves? No one knows.",
                            ["furnitureId"] = 4945,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_apexscalecaller.dds",
                            ["category"] = "Canines",
                        },
                        [4721] = 
                        {
                            ["name"] = "Galvanic Storm Steed",
                            ["hint"] = "",
                            ["id"] = 4721,
                            ["description"] = "The Galvanic Storm Steed fuses the power of a Storm Atronach from Oblivion with the bloodline of the Yokudan Chargers, the famous war horses of the Redguards, to create an incomparable mount.",
                            ["furnitureId"] = 4775,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_stormsteed.dds",
                            ["category"] = "Equines",
                        },
                        [4722] = 
                        {
                            ["name"] = "Snow-Blanket Sorrel Horse",
                            ["hint"] = "",
                            ["id"] = 4722,
                            ["description"] = "This handsome breed of horse is native to the Colovian Highlands of Cyrodiil, and is a common sight from Chorrol to Bruma. The Snow-Blanket Sorrel is known for its intelligence and high spirits.",
                            ["furnitureId"] = 4770,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_snowblanketsorrel.dds",
                            ["category"] = "Equines",
                        },
                        [4723] = 
                        {
                            ["name"] = "Tattooed Shorn Camel",
                            ["hint"] = "",
                            ["id"] = 4723,
                            ["description"] = "The dervishes of Rihad shave their Hammerfell camels and tattoo them with mystic symbols sacred to the spirits of the deep desert, to placate those wayward spirits in hopes they'll refrain from leading the camels astray among the dunes.",
                            ["furnitureId"] = 4771,
                            ["icon"] = "/esoui/art/icons/mounticon_camel_tattooedshorn.dds",
                            ["category"] = "Camelids",
                        },
                        [4724] = 
                        {
                            ["name"] = "Bal Foyen Circus Guar",
                            ["hint"] = "",
                            ["id"] = 4724,
                            ["description"] = "Like other reptilian creatures, Guar can be bred for bright, even gaudy colors. The Argonians of Dhalmora offer this entertaining variant, a popular performer in Tamriel's traveling shows.",
                            ["furnitureId"] = 4772,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_balfoyencircus.dds",
                            ["category"] = "Bipedals",
                        },
                        [10869] = 
                        {
                            ["name"] = "Heartland River Crab",
                            ["hint"] = "",
                            ["id"] = 10869,
                            ["description"] = "\"Give one of these green-shelled beauties food, and they'll follow you around a bit. Keep it up, and you've a friend for life. If they were smaller, I'd let them dangle from my ears, but they settle into my pack well enough.\"—Aetis Salvitto",
                            ["furnitureId"] = 8674,
                            ["icon"] = "/esoui/art/icons/pet_nagastanihermitcrab.dds",
                            ["category"] = "Exotic",
                        },
                        [4726] = 
                        {
                            ["name"] = "Small Bone Dragon Construct",
                            ["hint"] = "",
                            ["id"] = 4726,
                            ["description"] = "This construct resembles a great and fearsome Bone Dragon, but it's actually a product of the Necromancer's art, assembled from modern bird and reptile bones and then reanimated.",
                            ["furnitureId"] = 4805,
                            ["icon"] = "/esoui/art/icons/pet_171_bonedragon.dds",
                            ["category"] = "Exotic",
                        },
                        [4727] = 
                        {
                            ["name"] = "Unholy Glow Bone Dragon",
                            ["hint"] = "",
                            ["id"] = 4727,
                            ["description"] = "This necromantic construct of reanimated bones resembles a gruesome Bone Dragon, one so charged with unholy power that it emits an uncanny blue glow.",
                            ["furnitureId"] = 4806,
                            ["icon"] = "/esoui/art/icons/pet_175_bonedragonvariant.dds",
                            ["category"] = "Exotic",
                        },
                        [4728] = 
                        {
                            ["name"] = "Madcap Jester Monkey",
                            ["hint"] = "",
                            ["id"] = 4728,
                            ["description"] = "Say, why does this little chum look at you funny? It must be your face! Ook ook! Ah, ha ha ha ha ha ha ha!",
                            ["furnitureId"] = 4800,
                            ["icon"] = "/esoui/art/icons/pet_178_jestermonkey.dds",
                            ["category"] = "Exotic",
                        },
                        [4729] = 
                        {
                            ["name"] = "Karth Winter Hound",
                            ["hint"] = "",
                            ["id"] = 4729,
                            ["description"] = "The Karth Winter Hound is the snow-white breed of the Markarth Bear Dog, snowy year-round for hunting in Skyrim's snow-capped peaks. Some Reach clans reserve the Winter Hounds solely for chieftains.",
                            ["furnitureId"] = 4791,
                            ["icon"] = "/esoui/art/icons/pet_4729.dds",
                            ["category"] = "Exotic",
                        },
                        [10874] = 
                        {
                            ["name"] = "Gonfalon Sea Cur",
                            ["hint"] = "",
                            ["id"] = 10874,
                            ["description"] = "Also called the \"Dog of the Watch,\" these dark-furred mutts work alongside sailors on their docked ships. Recently, the craze among Gonfalon Bay nobles involves sponsoring the care, feeding, and, oddly, hats for these beloved canines.",
                            ["furnitureId"] = 8677,
                            ["icon"] = "/esoui/art/icons/pet_gonfalonseacur.dds",
                            ["category"] = "Exotic",
                        },
                        [4731] = 
                        {
                            ["name"] = "Flameback Boar",
                            ["hint"] = "",
                            ["id"] = 4731,
                            ["description"] = "Like the Purple Daggerback, the breed of Flameback Boars clearly had some kind of brush with the uncanny that imbued them with magical aspects. Regular boars just don't have crimson glowing eyes and flame-colored bristle crests down their backs.",
                            ["furnitureId"] = 4810,
                            ["icon"] = "/esoui/art/icons/pet_170_daggerbackflameback.dds",
                            ["category"] = "Exotic",
                        },
                        [4732] = 
                        {
                            ["name"] = "Mournhold Packrat",
                            ["hint"] = "|cffffffPurchasing this pet increases your inventory capacity by 5 slots on all characters account wide.|r",
                            ["id"] = 4732,
                            ["description"] = "Are you the kind of adventurer who simply Must Loot Everything? Being followed around by the Mournhold Packrat, an actual cargo rodent, tells the world that you're an Acquisitionist who's not going to leave behind a single spoon!",
                            ["furnitureId"] = 4938,
                            ["icon"] = "/esoui/art/icons/pet_177_packrat.dds",
                            ["category"] = "Inventory",
                        },
                        [4733] = 
                        {
                            ["name"] = "Wrothgar Buck Goat",
                            ["hint"] = "",
                            ["id"] = 4733,
                            ["description"] = "The Orcs of Wrothgar have a hardy breed of goats well-suited to the area's rugged terrain and changeable climate. Each goatherd particularly prizes his herd's master Buck Goat; these tend to be both intelligent and pugnacious, good animal companions.",
                            ["furnitureId"] = 4807,
                            ["icon"] = "/esoui/art/icons/pet_4733.dds",
                            ["category"] = "Domestic",
                        },
                        [4734] = 
                        {
                            ["name"] = "Big-Eared Ginger Mouser",
                            ["hint"] = "",
                            ["id"] = 4734,
                            ["description"] = "The Ginger Mouser is a favorite barn cat of grain farmers all across central Tamriel, not just because it keeps the storage bins rodent-free, but also for its affectionate personality and goofy good looks.",
                            ["furnitureId"] = 4802,
                            ["icon"] = "/esoui/art/icons/pet_4734.dds",
                            ["category"] = "Domestic",
                        },
                        [4735] = 
                        {
                            ["name"] = "Karth Winter Pup",
                            ["hint"] = "",
                            ["id"] = 4735,
                            ["description"] = "When the Karth Winter Hound has puppies, it even softens the Briarhearts of the Reachmen. Who's a good barbarian pup-pup, then? Is it you? It IS you!",
                            ["furnitureId"] = 4796,
                            ["icon"] = "/esoui/art/icons/pet_4735.dds",
                            ["category"] = "Domestic",
                        },
                        [4736] = 
                        {
                            ["name"] = "Nightmare Senche Cub",
                            ["hint"] = "",
                            ["id"] = 4736,
                            ["description"] = "Despite the fact that this night-black senche-tiger cub has burning paws and flaming eyes, it's so adorable it might be a nightmare you never want to awaken from!",
                            ["furnitureId"] = 4942,
                            ["icon"] = "/esoui/art/icons/pet_4736.dds",
                            ["category"] = "Exotic",
                        },
                        [4737] = 
                        {
                            ["name"] = "Mage's Sentry Kitten",
                            ["hint"] = "",
                            ["id"] = 4737,
                            ["description"] = "When it's a kitten, the Mage's Sentry Cat is so adorable, it's said that some sorcerers enchant them to stay that age always.",
                            ["furnitureId"] = 4792,
                            ["icon"] = "/esoui/art/icons/pet_169_magessentrykitten.dds",
                            ["category"] = "Domestic",
                        },
                        [4739] = 
                        {
                            ["name"] = "Helkarn Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 4739,
                            ["description"] = "The pups of the Helkarn Wolves from Elsweyr are almost as sociable with people as dog puppies, so they get a lot of attention when young. This probably contributes to their docility as mounts when full grown.",
                            ["furnitureId"] = 4795,
                            ["icon"] = "/esoui/art/icons/pet_4739.dds",
                            ["category"] = "Exotic",
                        },
                        [4740] = 
                        {
                            ["name"] = "Bristleneck War Boar",
                            ["hint"] = "|cffffffPurchasing this pet increases your inventory capacity by 5 slots on all characters account wide.|r",
                            ["id"] = 4740,
                            ["description"] = "Originally from Solstheim, this tempestuous boar exists in two modes: hungry and hungrier! Given that it can carry gear, though, providing it with its favorite fungi is a small matter.",
                            ["furnitureId"] = 4939,
                            ["icon"] = "/esoui/art/icons/pet_179_warboar.dds",
                            ["category"] = "Inventory",
                        },
                        [4741] = 
                        {
                            ["name"] = "Magma Scamp",
                            ["hint"] = "",
                            ["id"] = 4741,
                            ["description"] = "Scamps are lesser Daedra used as servants and menials by a number of different Daedric Princes. The Magma Scamps are servants of Mehrunes Dagon, and can be summoned from his Oblivion plane of the Deadlands.",
                            ["furnitureId"] = 4804,
                            ["icon"] = "/esoui/art/icons/pet_154_flamescamp.dds",
                            ["category"] = "Daedric",
                        },
                        [4744] = 
                        {
                            ["name"] = "Frostbane Pony Guar",
                            ["hint"] = "",
                            ["id"] = 4744,
                            ["description"] = "Though the reptilian Guar are native to the warmer climates south of Skyrim, the compact Pony Guar have long been popular pets among the aristocracy of Riften. Traditional Nords like to dress them in the Frostbane garb used on more local animals.",
                            ["furnitureId"] = 4779,
                            ["icon"] = "/esoui/art/icons/pet_172_scalecallerguar.dds",
                            ["category"] = "Exotic",
                        },
                        [4745] = 
                        {
                            ["name"] = "Frostbane Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 4745,
                            ["description"] = "In \"The Tail of Ysgramor's Cat,\" the Harbinger's Sabre Cat hunting companion is described as being festooned with Atmoran Frostbane talismans, and some tradition-loving modern Nords still decorate their Sabre Cats in the same manner.",
                            ["furnitureId"] = 4780,
                            ["icon"] = "/esoui/art/icons/pet_174_scalecallersenche.dds",
                            ["category"] = "Exotic",
                        },
                        [4746] = 
                        {
                            ["name"] = "Frostbane Bear",
                            ["hint"] = "",
                            ["id"] = 4746,
                            ["description"] = "Nords who follow the tradition of hanging Frostbane totems and talismans on their beasts to protect them from Skyrim's bitter cold often do it even when the animals are still young, to get them used to the idea.",
                            ["furnitureId"] = 4781,
                            ["icon"] = "/esoui/art/icons/pet_176_scalecallerbear.dds",
                            ["category"] = "Exotic",
                        },
                        [4747] = 
                        {
                            ["name"] = "Frostbane Wolf",
                            ["hint"] = "",
                            ["id"] = 4747,
                            ["description"] = "To accustom their Frostbane Wolves to the click-clacking of dangling talismans and totems, the ancient Nords began dressing their companion wolves in Frostbane garb from an early age.",
                            ["furnitureId"] = 4782,
                            ["icon"] = "/esoui/art/icons/pet_176_scalecallerwolf.dds",
                            ["category"] = "Exotic",
                        },
                        [4748] = 
                        {
                            ["name"] = "Frostbane Pony",
                            ["hint"] = "",
                            ["id"] = 4748,
                            ["description"] = "The hardy ponies of the frozen north look even shaggier when they're decorated with Frostbane hair-knots and ancient Nord totems. Whether the talismans keep the cold away is impossible to tell, but it's certain these ponies never lose their good cheer.",
                            ["furnitureId"] = 4793,
                            ["icon"] = "/esoui/art/icons/pet_173_scalecallerhorse.dds",
                            ["category"] = "Exotic",
                        },
                        [4749] = 
                        {
                            ["name"] = "Ashen Fang Lair Courser",
                            ["hint"] = "",
                            ["id"] = 4749,
                            ["description"] = "Sometimes, when necromancers reanimate a creature, they overdo it and imbue the undead entity with an excess of dark conjuration. In the case of the Ashen Courser, this residue of mystical power manifests as a cloud of grave dust and ash.",
                            ["furnitureId"] = 4949,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_ashenfanglair.dds",
                            ["category"] = "Equines",
                        },
                        [8846] = 
                        {
                            ["name"] = "Makes-Many-Soups",
                            ["hint"] = "",
                            ["id"] = 8846,
                            ["description"] = "A chef of many soups, but perhaps only one at a time, the Argonian Makes-Many-Soups seeks to add her culinary creativity to your abode. After adding Makes-Many-Soups to your home, you can set her on a path, plus you and your visitors can speak with her.",
