                            ["category"] = "Exotic",
                        },
                        [762] = 
                        {
                            ["name"] = "Great Dark Stag",
                            ["hint"] = "",
                            ["id"] = 762,
                            ["description"] = "The Great Dark Stag is one of the five Aspects of Hircine, invoked as Uricanbeg, \"whose hooves drum the Blood Summons.\"\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4318,
                            ["icon"] = "/esoui/art/icons/mounticon_stag_01.dds",
                            ["category"] = "Cervines",
                        },
                        [763] = 
                        {
                            ["name"] = "Nightfall Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 763,
                            ["description"] = "The Reachmen of the upper Karth valley, who train them as mounts, swear that the Nightfall variant is sacred to the Daedric Prince Nocturnal.\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4319,
