                            ["category"] = "Felines",
                        },
                        [764] = 
                        {
                            ["name"] = "Sabre Cat Cub",
                            ["hint"] = "",
                            ["id"] = 764,
                            ["description"] = "Sabre Cats are mighty and majestic hunters that rule the northern plains and tundra by sheer strength and savagery—but, Daedra take it, they sure are cute when they're cubs!",
                            ["furnitureId"] = 4320,
                            ["icon"] = "/esoui/art/icons/pet_114.dds",
