                        },
                        [765] = 
                        {
                            ["name"] = "Nightfall Sabre Cat Cub",
                            ["hint"] = "",
                            ["id"] = 765,
                            ["description"] = "\"In my first months as a captive of the Reachmen, the only thing that made life bearable was my beloved pet, the Nightfall Sabre Cat Cub I was allowed as a companion.\" —Arthenice Belloq",
                            ["furnitureId"] = 4321,
                            ["icon"] = "/esoui/art/icons/pet_112.dds",
