                        [7269] = 
                        {
                            ["name"] = "Slate-Skinned Daedrat",
                            ["hint"] = "",
                            ["id"] = 7269,
                            ["description"] = "\"The cold blue glowing eyes and markings of the Slate-Skinned Daedrat stem from their diet: corpses touched by Molag Bal. Those brave enough to research or even thwart the Lord of Brutality often study these creatures for insight.\"—Phrastus of Elinhir",
                            ["furnitureId"] = 6549,
                            ["icon"] = "/esoui/art/icons/pet_slateskinneddaedrat.dds",
                            ["category"] = "Daedric",
                        },
                        [1126] = 
                        {
                            ["name"] = "Bust: Iceheart",
                            ["hint"] = "Awarded for completing Veteran Direfrost Keep.",
                            ["id"] = 1126,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Direfrost Keep.",
                            ["furnitureId"] = 4349,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteraniceatronach001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [5223] = 
                        {
                            ["name"] = "Noble Riverhold Senche-Lion Cub",
                            ["hint"] = "",
                            ["id"] = 5223,
                            ["description"] = "Even as cubs, the litter-mates of the noble Riverhold senche-lion prides exhibit the breed's hallmark attributes of courage and loyalty, bravely defending their masters against encroaching beetles and butterflies!",
                            ["furnitureId"] = 5443,
                            ["icon"] = "/esoui/art/icons/pet_201_riverholdcub.dds",
                            ["category"] = "Exotic",
                        },
                        [5224] = 
                        {
                            ["name"] = "Noble Riverhold Senche-Lion",
                            ["hint"] = "",
                            ["id"] = 5224,
                            ["description"] = "The pastoral tribes of northern Anequina need reliable mounts upon which to follow their herds of livestock, and none are more dependable than the prides of senche-lions bred near Riverhold, feline steeds so brave and loyal they're called \"Noble.\"",
                            ["furnitureId"] = 5473,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_riverholdlion.dds",
                            ["category"] = "Felines",
                        },
                        [7273] = 
                        {
                            ["name"] = "Gloomspore Guar Calf",
                            ["hint"] = "",
                            ["id"] = 7273,
                            ["description"] = "\"No better companion exists than my devoted Gloomspore Guar Calf. I used spores known for their calming properties to modify the guar's temperament. Regrettably, it makes the creature gassy, but unmatched loyalty is worth opening windows.\"—Mage Naleldil",
                            ["furnitureId"] = 6553,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporeguar.dds",
                            ["category"] = "Exotic",
                        },
                        [7274] = 
                        {
                            ["name"] = "Gloomspore Bear Cub",
                            ["hint"] = "",
                            ["id"] = 7274,
                            ["description"] = "\"Integrating research left behind by Ahzidal the Enchanter, I crafted a bear cub from spores acquired from a well-traveled merchant. This creature bumbles around a bit more than its animal counterpart, but it glows! Perfection!\"—Mage Naleldil",
                            ["furnitureId"] = 6554,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporebear.dds",
                            ["category"] = "Exotic",
                        },
                        [7275] = 
                        {
                            ["name"] = "Gloomspore Senche Cub",
                            ["hint"] = "",
                            ["id"] = 7275,
                            ["description"] = "\"To the surprise of none but the most hard-hearted, I made a tumbling ball of fungal-fur in the form of a senche cub. How could I not? And shame on any who pass this adorable bundle of spores without smiling.\"—Mage Naleldil",
                            ["furnitureId"] = 6555,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporesenche.dds",
                            ["category"] = "Exotic",
                        },
                        [7276] = 
                        {
                            ["name"] = "Gloomspore Pony",
                            ["hint"] = "",
                            ["id"] = 7276,
                            ["description"] = "\"Challenged by a colleague, I created a pony-fungus creature. The first few stood as still as statues, so I added manic morels from Dementia. That livened things up considerably. If you adopt one, I suggest keeping it out of your parlor.\"—Mage Naleldil",
                            ["furnitureId"] = 6556,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporepony.dds",
                            ["category"] = "Exotic",
                        },
                        [7277] = 
                        {
                            ["name"] = "Gloomspore Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 7277,
                            ["description"] = "\"I designed some adorable wolf pups, adding oxblood fungus spores to see if that instills fierce guardianship in them. It worked—they now guard my feet from things like boots and stockings. Consider garbing yourself out of their sight!\"—Mage Naleldil",
                            ["furnitureId"] = 6557,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporewolf.dds",
                            ["category"] = "Exotic",
                        },
                        [7278] = 
                        {
                            ["name"] = "Rimedusk Indrik",
                            ["hint"] = "",
                            ["id"] = 7278,
                            ["description"] = "The sound of wind gusting through dusklit, ice-laden trees heralds a Rimedust Indrik's birth. These indriks emanate a sense of deep calm wherever they go.",
                            ["furnitureId"] = 6558,
                            ["icon"] = "/esoui/art/icons/pet_rimeduskindrik.dds",
                            ["category"] = "Exotic",
                        },
                        [7279] = 
                        {
                            ["name"] = "Coldspring Nix-Hound",
                            ["hint"] = "",
                            ["id"] = 7279,
                            ["description"] = "Dark Elves of House Hlaalu, knowing that Vvardenfell isn't the only place with deadly flora, fauna, and folk, bred a nix-hound that can thrive in different environments. Even with its gorgeous blue-purple shading, it still possesses a menacing air.",
                            ["furnitureId"] = 6559,
                            ["icon"] = "/esoui/art/icons/pet_coldspringnixhound.dds",
                            ["category"] = "Exotic",
                        },
                        [7280] = 
                        {
                            ["name"] = "Ice-Glow Salamander",
                            ["hint"] = "",
                            ["id"] = 7280,
                            ["description"] = "While studying arcane husbandry, Mage Naleldil discovered a long-forgotten Ayleid ritual capable of granting luminescent qualities to common salamanders. Now, due to an unexpected population explosion, she gives them to those who impress her.",
                            ["furnitureId"] = 6560,
                            ["icon"] = "/esoui/art/icons/pet_iceglowsalamander.dds",
                            ["category"] = "Exotic",
                        },
                        [7281] = 
                        {
                            ["name"] = "Blue Torchbug",
                            ["hint"] = "",
                            ["id"] = 7281,
                            ["description"] = "The night before Waking Day, Iliac Bay Bretons share stories about the Terrible Torchbug of Molag Bal. While the story varies, all agree on one thing: those followed by a cobalt-hued torchbug possess a savagery in battle that haunts any who survive.",
                            ["furnitureId"] = 6561,
                            ["icon"] = "/esoui/art/icons/pet_bluetorchbug.dds",
                            ["category"] = "Flying Pets",
                        },
                        [7282] = 
                        {
                            ["name"] = "Purple Torchbug",
                            ["hint"] = "",
                            ["id"] = 7282,
                            ["description"] = "Madness follows the Purple Torchbug, or so some claim. Others believe that those who once held Sheogorath's attention attract these insects. Either way, perhaps Sheogorath's dubious blessing touched them.",
                            ["furnitureId"] = 6562,
                            ["icon"] = "/esoui/art/icons/pet_purpletorchbug.dds",
                            ["category"] = "Flying Pets",
                        },
                        [7283] = 
                        {
                            ["name"] = "White Torchbug",
                            ["hint"] = "",
                            ["id"] = 7283,
                            ["description"] = "Some believe that gaining Meridia's favor is like gripping a double-edged blade tightly with bare hands. Yet, if you perform an action she likes, she may gift you with a White Torchbug—perhaps the least worrisome of her favors!",
                            ["furnitureId"] = 6563,
                            ["icon"] = "/esoui/art/icons/pet_whitetorchbug.dds",
                            ["category"] = "Flying Pets",
                        },
                        [7284] = 
                        {
                            ["name"] = "Pink Torchbug",
                            ["hint"] = "",
                            ["id"] = 7284,
                            ["description"] = "Some followers of Stendarr claim that those who see a Pink Torchbug must perform great acts of charity and mercy by sunset the following day. If they please Stendarr, the pleasant little creature might follow them for a time.",
                            ["furnitureId"] = 6564,
                            ["icon"] = "/esoui/art/icons/pet_pinktorchbug-copy.dds",
                            ["category"] = "Flying Pets",
                        },
                        [1141] = 
                        {
                            ["name"] = "Bust: The Ilambris Twins",
                            ["hint"] = "Awarded for completing Veteran Crypt of Hearts I.",
                            ["id"] = 1141,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Crypt of Hearts I.",
                            ["furnitureId"] = 4364,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranxyvkin001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [7286] = 
                        {
                            ["name"] = "Pyre Watch Jackal",
                            ["hint"] = "",
                            ["id"] = 7286,
                            ["description"] = "Long ago, the secretive Pyre Watch bred local jackals into mounts, allowing them to move swiftly as they patrolled their cursed caverns. Now this nimble and fleet pale steed can be yours!",
                            ["furnitureId"] = 6566,
                            ["icon"] = "/esoui/art/icons/mount_pyrewatchjackal.dds",
                            ["category"] = "Canines",
                        },
                        [7287] = 
                        {
                            ["name"] = "Icereach Wicker-Steed",
                            ["hint"] = "",
                            ["id"] = 7287,
                            ["description"] = "A bloodied Daedric dagger used by a spurned lover. The tears of a victim tormented by Molag Bal. When used in a wicked Icereach coven ritual, they help shape a wicker mount that is worthy of bearing everyone's worst nightmare: you.",
                            ["furnitureId"] = 6567,
                            ["icon"] = "/esoui/art/icons/mount_icereachwickersteed.dds",
                            ["category"] = "Equines",
                        },
                        [7288] = 
                        {
                            ["name"] = "Shadowcap Cave-Senche",
                            ["hint"] = "",
                            ["id"] = 7288,
                            ["description"] = "\"Ahzidal made the shadowcap's azure glow the centerpiece of this unsettling feline mount. Prized by spelunkers, this luminescent mount can light up the darkest caverns without making a sound. \"—Halund Greycloak",
                            ["furnitureId"] = 6568,
                            ["icon"] = "/esoui/art/icons/mount_shadowcapcavesenche.dds",
                            ["category"] = "Felines",
                        },
                        [7289] = 
                        {
                            ["name"] = "Fungiflare Wolf",
                            ["hint"] = "",
                            ["id"] = 7289,
                            ["description"] = "\"One of Ahzidal's experiments involved creating an ideal wolf mount for dangerous forests and caverns. This Fungiflare Wolf has a vicious temperament by design and nature—fungiflare mushrooms are lethal.\"—Halund Greycloak",
                            ["furnitureId"] = 6569,
                            ["icon"] = "/esoui/art/icons/mount_fungiflarewolf.dds",
                            ["category"] = "Canines",
                        },
                        [7290] = 
                        {
                            ["name"] = "Embermould Warhorse",
                            ["hint"] = "",
                            ["id"] = 7290,
                            ["description"] = "\"Seeking to meld fire with fungi, Ahzidal created the first Embermould Warhorse. Formed from char morels often used in stews, this mount can light a rider's way on the darkest winter nights.\"—Halund Greycloak",
                            ["furnitureId"] = 6570,
                            ["icon"] = "/esoui/art/icons/mount_embermouldwarhorse.dds",
                            ["category"] = "Equines",
                        },
                        [7291] = 
                        {
                            ["name"] = "Nightmare Stick Horse",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["id"] = 7291,
                            ["description"] = "Ride a stick mount that symbolizes your fiery dreams of all-consuming doom. Complete with flaming mane, tail, and eyes, this thrice-cursed novelty horse makes your stick-riding experience one for the books … of burning horror!",
                            ["furnitureId"] = 6571,
                            ["icon"] = "/esoui/art/icons/mount_nightmarestickhorse.dds",
                            ["category"] = "Toys",
                        },
                        [1148] = 
                        {
                            ["name"] = "Shadowghost Senche-Panther",
                            ["hint"] = "",
                            ["id"] = 1148,
                            ["description"] = "In Elsweyr, being seen in the company of an uncanny Shadowghost Senche-Panther will put one under suspicion of being a Namiira cultist—or even a disguised dro-m'Athra.",
                            ["furnitureId"] = 4371,
                            ["icon"] = "/esoui/art/icons/pet_150.dds",
                            ["category"] = "Exotic",
                        },
                        [5245] = 
                        {
                            ["name"] = "Hollowjack Rider Horse",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5245,
                            ["description"] = "Every Witches Festival, the haunted legend of a hidden Rivenspire hollow once more comes to life—if you can call it that—and horse riders across Tamriel are cursed to gallop headless through the night on dark and frantic steeds.",
                            ["furnitureId"] = 5522,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_hollowjackv2.dds",
                            ["category"] = "Equines",
                        },
                        [5246] = 
                        {
                            ["name"] = "Hollowjack Rider Camel",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5246,
                            ["description"] = "Even in the wastes of the Alik'r, far from Rivenspire, when the sun sets on a moonless Witches Festival night riders may find themselves headless, galloping across the darkling dunes on shadowy camels and clutching glimmering Hollowjacks.",
                            ["furnitureId"] = 5523,
                            ["icon"] = "/esoui/art/icons/mounticon_camel_hollowjackv2.dds",
                            ["category"] = "Camelids",
                        },
                        [5247] = 
                        {
                            ["name"] = "Hollowjack Rider Wolf",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5247,
                            ["description"] = "Night winds whisper through the Hollow\nAnd the darknight wolf-pack prowls\nThen your wolf-mount turns to follow\nAnd you ride headless as it howls",
                            ["furnitureId"] = 5524,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_hollowjackv2.dds",
                            ["category"] = "Canines",
                        },
                        [1152] = 
                        {
                            ["name"] = "Snowy Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 1152,
                            ["description"] = "Of all Tamriel's great felines, the Snowy Sabre Cat is the hardiest when it comes to winter weather, barely noticing the Atmoran gales as they come howling in across the Sea of Ghosts. \n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4375,
                            ["icon"] = "/esoui/art/icons/mount_senche_n.dds",
                            ["category"] = "Felines",
                        },
                        [5249] = 
                        {
                            ["name"] = "Hollowjack Rider Bear",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5249,
                            ["description"] = "When the moons rise over the Witches Festival, Jaque o' the Hollow haunts the mounts of mortals, cursing their riders to gallop headless through the night. Even the doughty bear mounts of the Nords are susceptible.",
                            ["furnitureId"] = 5526,
                            ["icon"] = "/esoui/art/icons/mounticon_bear_hollowjackv2.dds",
                            ["category"] = "Ursines",
                        },
                        [5250] = 
                        {
                            ["name"] = "Hollowjack Rider Senche",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5250,
                            ["description"] = "Jaque o' the Hollow haunts Rivenspire during dark Witches Festival nights, and even those who ride senche-tiger mounts may find themselves padding headless through the moonless dark while waving a glowing gourd.",
                            ["furnitureId"] = 5527,
                            ["icon"] = "/esoui/art/icons/mounticon_sench_hollowjackv2.dds",
                            ["category"] = "Felines",
                        },
                        [1155] = 
                        {
                            ["name"] = "Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 1155,
                            ["description"] = "A loyal Dwarven Spider liberated from a Dwemer ruin, converted, using the \"Neramo Method,\" to an unlocked and autonomous state that enables it to leave its original locale.",
                            ["furnitureId"] = 4376,
                            ["icon"] = "/esoui/art/icons/pet_126.dds",
                            ["category"] = "Exotic",
                        },
                        [5252] = 
                        {
                            ["name"] = "Hollowjack Flame-Skull Senche",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5252,
                            ["description"] = "Conventional wisdom holds that these bizarre and eerie Skull mounts are just  senche-panthers imbued with a haunting illusory appearance—but some whisper that they aren't from Tamriel at all, but summoned from the Hollowjack half-world or demiplane.",
                            ["furnitureId"] = 5529,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_hollowjack_apex.dds",
                            ["category"] = "Felines",
                        },
                        [5253] = 
                        {
                            ["name"] = "Hollowjack Daedra-Skull Wolf",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5253,
                            ["description"] = "Conventional wisdom holds that these bizarre and eerie Skull mounts are just riding wolves imbued with a haunting illusory appearance—but some whisper that they aren't from Tamriel at all, but summoned from the Hollowjack half-world or demiplane.",
                            ["furnitureId"] = 5530,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_hollowjack_apex.dds",
                            ["category"] = "Canines",
                        },
                        [1159] = 
                        {
                            ["name"] = "Dwarven Horse",
                            ["hint"] = "",
                            ["id"] = 1159,
                            ["description"] = "The ancient Deep Elves made animunculi of many kinds, imitating nature with mechanical constructs. The Dwarven word for mount was \"vamidium,\" but their equine automata are more commonly known as Dwarven Horses.",
                            ["furnitureId"] = 4378,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_horse_a.dds",
                            ["category"] = "Equines",
                        },
                        [1160] = 
                        {
                            ["name"] = "Dwarven Senche",
                            ["hint"] = "",
                            ["id"] = 1160,
                            ["description"] = "Since nearly all Dwemer sites are in northeast Tamriel, where the only large feline is the sabre cat, scholars of Dwarven civilization have long wondered why they chose to make animunculi mounts that resemble the senche-tigers of the south. It's a mystery!",
                            ["furnitureId"] = 4379,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_senche_a.dds",
                            ["category"] = "Felines",
                        },
                        [1161] = 
                        {
                            ["name"] = "Dwarven Bear",
                            ["hint"] = "",
                            ["id"] = 1161,
                            ["description"] = "Scholar of the Dwemer Guylaine Marilie theorized that bear vamidiums were animunculi mounts reserved only for those Deep Elves of high rank or status. \"Imagine a noble in full armor on a Dwarven Bear Mount,\" he wrote. \"What could be more impressive?\"",
                            ["furnitureId"] = 4380,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvenbear_a.dds",
                            ["category"] = "Ursines",
                        },
                        [1162] = 
                        {
                            ["name"] = "Dwarven Guar",
                            ["hint"] = "",
                            ["id"] = 1162,
                            ["description"] = "Guar vamidiums, or Dwarven Guar Mounts, are most often associated with Dwemer sites in Morrowind—as might be expected, since that's where guar are most in use as pack and riding animals.",
                            ["furnitureId"] = 4381,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_guar_a.dds",
                            ["category"] = "Bipedals",
                        },
                        [1163] = 
                        {
                            ["name"] = "Dwarven Camel",
                            ["hint"] = "",
                            ["id"] = 1163,
                            ["description"] = "Dwarven Camels are most often found among the ruins of the desert-dwelling Rourken clan of the Dwemer, who left northeast Tamriel and traveled west to found cities in the remote back-country of Hammerfell.",
                            ["furnitureId"] = 4382,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvencamel_a.dds",
                            ["category"] = "Camelids",
                        },
                        [1164] = 
                        {
                            ["name"] = "Dwarven Wolf",
                            ["hint"] = "",
                            ["id"] = 1164,
                            ["description"] = "Dwarven Wolves, or Lupine Vamidiums, are most often seen in proximity to Dwemer ruins of northern and western Skyrim, where wolves are most common in the wild. Its loping gait is said to give the most comfortable ride of any mechanical mount.",
                            ["furnitureId"] = 4383,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_wolf_a.dds",
                            ["category"] = "Canines",
                        },
                        [11407] = 
                        {
                            ["name"] = "Maligraphic Mount",
                            ["hint"] = "Acquired by completing the \"Ichor Most Malevolent\" achievement.",
                            ["id"] = 11407,
                            ["description"] = "\"I'm not going to say that you need to ride this beast. But when the Prince of Secret Knowledge hands you the reins, are you really going to turn them down? I know I wouldn't!\"—Filer Xess",
                            ["furnitureId"] = 9035,
                            ["icon"] = "/esoui/art/icons/mount_maligraphicmount.dds",
                            ["category"] = "Equines",
                        },
                        [11408] = 
                        {
                            ["name"] = "Solstice Indrik",
                            ["hint"] = "",
                            ["id"] = 11408,
                            ["description"] = "Legend says this indrik was born of a child's toy, touched by magic on the year's longest night. Others believe a worthy rider wished it into being by pleading with the moons on a cold Frostfall night. Regardless, riders see the world for the wonder it is.",
                            ["furnitureId"] = 9036,
                            ["icon"] = "/esoui/art/icons/mount_solsticeindrik.dds",
                            ["category"] = "Cervines",
                        },
                        [11409] = 
                        {
                            ["name"] = "Harpy's Bane Durzog",
                            ["hint"] = "",
                            ["id"] = 11409,
                            ["description"] = "\"All durzog are relentless in the pursuit of prey, but this sub-species is particularly vicious, especially when following a harpy's scent. Even experienced handlers sometimes struggle to contain their ferocity on the hunt.\" —Elsweyr: A Rider's Guide",
                            ["furnitureId"] = 9037,
                            ["icon"] = "/esoui/art/icons/mount_harpybanedurzog.dds",
                            ["category"] = "Canines",
                        },
                        [1170] = 
                        {
                            ["name"] = "Seht's Dovah-Fly",
                            ["hint"] = "",
                            ["id"] = 1170,
                            ["description"] = "These are clearly fabricants, clockwork simulations of living creatures, with the distinctive appearance of the handiwork of Sotha Sil. But if so, how did they escape Clockwork City? What powers them? And why do they make such loyal pets? No one knows.",
                            ["furnitureId"] = 4385,
                            ["icon"] = "/esoui/art/icons/pet_132.dds",
                            ["category"] = "Flying Pets",
                        },
                        [1171] = 
                        {
                            ["name"] = "Vvardenfell Scale Model",
                            ["hint"] = "Acquired by finding all of the ancestral tombs of Vvardenfell and the lost Library of Andule.",
                            ["id"] = 1171,
                            ["description"] = "Librarian Bradyn presented you with this scale model of the island of Vvardenfell—a miniature version of the replica in the library in Vivec City.",
                            ["furnitureId"] = 4386,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_maptablehousing001.dds",
                            ["category"] = "General",
                        },
                        [1173] = 
                        {
                            ["name"] = "Brassilisk",
                            ["hint"] = "",
                            ["id"] = 1173,
                            ["description"] = "\"The Brassilisk is created from interconnected brass squares, its exposed copper wiring allowing for its snakelike movement. Popular as a pet, you'll often see them following the quick footsteps of young scholars.\" —Endilaril, Clockwork City Naturalist",
                            ["furnitureId"] = 4388,
                            ["icon"] = "/esoui/art/icons/pet_162.dds",
                            ["category"] = "Exotic",
                        },
                        [1174] = 
                        {
                            ["name"] = "Ebon Dwarven Wolf",
                            ["hint"] = "Acquired by digging up its various parts via the Antiquities system.",
                            ["id"] = 1174,
                            ["description"] = "\"There is no evidence that the Dwemer kept dogs, or pets of any other kind, for that matter, but like their neighbors the Nords they did seem to have some affection for the Wolves of northern Tamriel. One sees this in their mounts.\" —Thelwe Ghelein",
                            ["furnitureId"] = 4389,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_ebon_wolf.dds",
                            ["category"] = "Canines",
                        },
                        [9367] = 
                        {
                            ["name"] = "Nightmare Great Dane",
                            ["hint"] = "",
                            ["id"] = 9367,
                            ["description"] = "Template Description",
                            ["furnitureId"] = 7644,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Domestic",
                        },
                        [9368] = 
                        {
                            ["name"] = "Starchaser Senche",
                            ["hint"] = "",
                            ["id"] = 9368,
                            ["description"] = "\"Celestial senches prowl over jagged rocks on surprisingly soft paws for creatures made of Spellscar-like stone. Yes, the Steed constellation is a horse, but how the Warrior didn't ride a starry senche into battle is beyond me.\"—Madadi, Celestial Scholar",
                            ["furnitureId"] = 7645,
                            ["icon"] = "/esoui/art/icons/mount_starchasersenche.dds",
                            ["category"] = "Felines",
                        },
                        [9370] = 
                        {
                            ["name"] = "Nebulous Star-Born Steed",
                            ["hint"] = "",
                            ["id"] = 9370,
                            ["description"] = "\"The glow emanating from this celestial horse soothes and energizes me at the same time. Odd, given its origins in Spellscar. Sitting astride this mystical mount can make even the most wretched pauper feel like a master mage.\"—Madadi, Celestial Scholar",
                            ["furnitureId"] = 7647,
                            ["icon"] = "/esoui/art/icons/mount_radcelestialhorse.dds",
                            ["category"] = "Equines",
                        },
                        [7323] = 
                        {
                            ["name"] = "Khajiit of the Moons Replica",
                            ["hint"] = "Awarded for bringing all twelve pieces of Khajiit of the Moons, an ancient Khajiiti tapestry, to the Senchal Palace.",
                            ["id"] = 7323,
                            ["description"] = "A perfect replica of the priceless tapestry called Khajiit of the Moons.",
                            ["furnitureId"] = 6629,
                            ["icon"] = "/esoui/art/icons/housing_els_inc_housingsetapestryframemural001.dds",
                            ["category"] = "General",
                        },
                        [9373] = 
                        {
                            ["name"] = "White Butterfly",
                            ["hint"] = "",
                            ["id"] = 9373,
                            ["description"] = "Template Description",
                            ["furnitureId"] = 7650,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Flying Pets",
                        },
                        [11422] = 
                        {
                            ["name"] = "Order of the Lamp Destrier",
                            ["hint"] = "",
                            ["id"] = 11422,
                            ["description"] = "Selectively bred for generations by the Mages Guild and the Order of the Lamp, these steeds possess remarkable stamina and agility. No expense is spared in their training, and they are equipped with armor rivaling that of the finest knights in Tamriel.",
                            ["furnitureId"] = 9113,
                            ["icon"] = "/esoui/art/icons/mount_orderofthelamp.dds",
                            ["category"] = "Equines",
                        },
                        [11423] = 
                        {
                            ["name"] = "Order of the Lamp Jackal",
                            ["hint"] = "",
                            ["id"] = 11423,
                            ["description"] = "Cunning and fast, this jackal has a laughing bark that echoes for miles. While they can be somewhat wild even to their riders, the jackal's preternatural ability to find shortcuts and quick exits has made it a preferred mount for many Lamp Knights.",
                            ["furnitureId"] = 9114,
                            ["icon"] = "/esoui/art/icons/mount_orderofthelampjackal.dds",
                            ["category"] = "Canines",
                        },
                        [1184] = 
                        {
                            ["name"] = "Gorne Striped Wolf",
                            ["hint"] = "",
                            ["id"] = 1184,
                            ["description"] = "The Isle of Gorne off the east coast of Morrowind is home to many strange creatures found nowhere else in Tamriel. One of these is the giant Striped Wolf, packs of which terrorized the island's settlers till they were suppressed in the Troubled House Hunt.",
                            ["furnitureId"] = 4390,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_e.dds",
                            ["category"] = "Canines",
                        },
                        [9377] = 
                        {
                            ["name"] = "Cropsford Hen",
                            ["hint"] = "",
                            ["id"] = 9377,
                            ["description"] = "The Cropsford Hen is a beloved staple of many Cyrodilic farmsteads since just one hen will staunchly protect the entire coop against foxes. Children in Cropsford say the hens herd them into the coop whenever a hawk is circling.",
                            ["furnitureId"] = 7651,
                            ["icon"] = "/esoui/art/icons/pet_cropsfordhen.dds",
                            ["category"] = "Domestic",
                        },
                        [9378] = 
                        {
                            ["name"] = "Mzark Jade-Cap Shroom Shalk",
                            ["hint"] = "",
                            ["id"] = 9378,
                            ["description"] = "\"My Wick and I have built many nests, felled sickened trees, and cleaned the roots of our Hist. Dryskins think shalks of her color are lucky, but Wick dirties her pinchers in rotting bark for our fortune.\"—Vunsu, Arborealist",
                            ["furnitureId"] = 7652,
                            ["icon"] = "/esoui/art/icons/pet_greenshroomshalk.dds",
                            ["category"] = "Exotic",
                        },
                        [9379] = 
                        {
                            ["name"] = "Sunback Bear Cub",
                            ["hint"] = "",
                            ["id"] = 9379,
                            ["description"] = "Wardens of Morthal ride large, hulking Sunback Bears into battle. While the full-sized bears tend to scare villagers, cubs are more easily accepted. Plus, the cubs' tiny ears can get the staunchest of merchants to lower their prices.",
                            ["furnitureId"] = 7653,
                            ["icon"] = "/esoui/art/icons/pet_sunbackbearcub.dds",
                            ["category"] = "Exotic",
                        },
                        [9380] = 
                        {
                            ["name"] = "Green Feathered Sep Adder",
                            ["hint"] = "",
                            ["id"] = 9380,
                            ["description"] = "Template Description",
                            ["furnitureId"] = 7654,
                            ["icon"] = "/esoui/art/icons/pet_greenfeathersepadder.dds",
                            ["category"] = "Exotic",
                        },
                        [9381] = 
                        {
                            ["name"] = "Yellow Feathered Sep Adder",
                            ["hint"] = "",
                            ["id"] = 9381,
                            ["description"] = "Template Description",
                            ["furnitureId"] = 7655,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Exotic",
                        },
                        [9382] = 
                        {
                            ["name"] = "Mind-Shriven Cat",
                            ["hint"] = "",
                            ["id"] = 9382,
                            ["description"] = "\"The Mind-Shriven usually have no concept of the self, but this feline appears to be as content with its nature as always. It seems that Molag Bal himself cannot enslave a cat.\"—Warlock Aldaale",
                            ["furnitureId"] = 7656,
                            ["icon"] = "/esoui/art/icons/pet_mindshrivencat.dds",
                            ["category"] = "Exotic",
                        },
                        [9383] = 
                        {
                            ["name"] = "Infernal Trickster Death Hound",
                            ["hint"] = "",
                            ["id"] = 9383,
                            ["description"] = "This hound's attire may suggest that it was once a fun-loving companion; there is nothing playful about it now. This resurrected creature is not for the faint of heart, but it will show loyalty in not setting you ablaze with its fiery muzzle.",
                            ["furnitureId"] = 7657,
                            ["icon"] = "/esoui/art/icons/mount_infernaltrickster.dds",
                            ["category"] = "Canines",
                        },
                        [9384] = 
                        {
                            ["name"] = "Dark Delirium Senche",
                            ["hint"] = "",
                            ["id"] = 9384,
                            ["description"] = "\"There is madness in all of us, and senches don't commit to anything half-heartedly. I came across one such mad senche and still bear the scars of its wild attacks. To take one on an adventure, you'd have to be mad as Sheogorath himself!\"—Vi Aspblade",
                            ["furnitureId"] = 7658,
                            ["icon"] = "/esoui/art/icons/mount_darkdeliriumsenche.dds",
                            ["category"] = "Felines",
                        },
                        [9385] = 
                        {
                            ["name"] = "Ram of Dark Delights",
                            ["hint"] = "",
                            ["id"] = 9385,
                            ["description"] = "The shadowy shapes of inky goats lead revelers through the streets to Sanguine's latest celebration. Often, the animals are fitted with the symbols of the party: sweet drinks and heady rose perfumes. Take a ram like this into your care at your own peril.",
                            ["furnitureId"] = 7659,
                            ["icon"] = "/esoui/art/icons/mount_ramofdarkdelights.dds",
                            ["category"] = "Cervines",
                        },
                        [1194] = 
                        {
                            ["name"] = "Tuxedo Vvardvark",
                            ["hint"] = "",
                            ["id"] = 1194,
                            ["description"] = "The most popular conjecture about the origin of the Vvardvark is that it's a magical hybrid created by a rogue Telvanni wizard. The coloration of the Tuxedo Vvardvark, according to this theory, was intended to enable it to hide in a flock of chub loons.",
                            ["furnitureId"] = 4399,
                            ["icon"] = "/esoui/art/icons/pet_138.dds",
                            ["category"] = "Exotic",
                        },
                        [9387] = 
                        {
                            ["name"] = "Dunecoat Senche-Serval",
                            ["hint"] = "",
                            ["id"] = 9387,
                            ["description"] = "Originally found in the arid canyons of Northern Elsweyr, these striped beauties rarely submit to training, making cats that do extremely desirable. Just make sure to have plenty of toys on hand or you'll find your leather boots gnawed to pieces.",
                            ["furnitureId"] = 7661,
                            ["icon"] = "/esoui/art/icons/mount_dunecoatsencheserval.dds",
                            ["category"] = "Felines",
                        },
                        [9388] = 
                        {
                            ["name"] = "Wamasu Hatchling",
                            ["hint"] = "",
                            ["id"] = 9388,
                            ["description"] = "A crackle of lightning accompanies this hatchling wherever it goes, providing a foreshadowing of what it will become in its adulthood. Before that point, though, it makes an excellent if imposing adventuring buddy!",
                            ["furnitureId"] = 7662,
                            ["icon"] = "/esoui/art/icons/pet_wamasuhatchling.dds",
                            ["category"] = "Exotic",
                        },
                        [9389] = 
                        {
                            ["name"] = "Witch-Tamed Bear-Dog",
                            ["hint"] = "",
                            ["id"] = 9389,
                            ["description"] = "Few Reach witches make the effort to invest eldritch magic into unborn pups, train them to draw attention without fear, and decorate them with eerie skeletal bone markings. All it takes is one look to either fear this canine or love it beyond reason.",
                            ["furnitureId"] = 7663,
                            ["icon"] = "/esoui/art/icons/pet_halloweendog.dds",
                            ["category"] = "Domestic",
                        },
                        [9390] = 
                        {
                            ["name"] = "Ironclad Senche-Serval Kitten",
                            ["hint"] = "",
                            ["id"] = 9390,
                            ["description"] = "Known for their prowess at sweeping an area clean of shalks, these armored kittens possess a keen sense of group tactics at an early age. So, not only do you gain an affectionate furball as a friend, but you also have fewer pests distracting you.",
                            ["furnitureId"] = 7664,
                            ["icon"] = "/esoui/art/icons/pet_ironcladsencheserval.dds",
                            ["category"] = "Exotic",
                        },
                        [11439] = 
                        {
                            ["name"] = "Skingrad Guard Mastiff",
                            ["hint"] = "",
                            ["id"] = 11439,
                            ["description"] = "\"The training of one's canine is tantamount to the importance of military maneuvers. Neglecting a Legion canine weakens the entire unit. Like watering grapes in the field, proper care yields the fruit of loyalty.\"—Legion Recruit Training Manual",
                            ["furnitureId"] = 9150,
                            ["icon"] = "/esoui/art/icons/pet_skingrad-guard-mastiff.dds",
                            ["category"] = "Domestic",
                        },
                        [11440] = 
                        {
                            ["name"] = "Molag Bal Illusion Imp",
                            ["hint"] = "",
                            ["id"] = 11440,
                            ["description"] = "Why would a mage train an imp to cast a seeming of the God of Schemes? Who knows? But this tiny Dark Father, this diminutive Prince of Pain, this undersized Lord of Lies is almost cute. Almost.",
                            ["furnitureId"] = 9151,
                            ["icon"] = "/esoui/art/icons/pet_molagbalimp.dds",
                            ["category"] = "Daedric",
                        },
                        [7345] = 
                        {
                            ["name"] = "Behold Khunzar-ri's Ambition",
                            ["hint"] = "Awarded for completing the \"The Dragonguard\" quest in Southern Elsweyr.",
                            ["id"] = 7345,
                            ["description"] = "Place on the Altar of Ambition in the Hall of the Lunar Champion to unlock a portal to Khunzar-ri's childhood home.",
                            ["furnitureId"] = 6600,
                            ["icon"] = "/esoui/art/icons/housing_els_duc_tablet002.dds",
                            ["category"] = "General",
                        },
                        [11443] = 
                        {
                            ["name"] = "West Weald Tharriker",
                            ["hint"] = "",
                            ["id"] = 11443,
                            ["description"] = "\"We subdued this one and trained it a bit. Poor beast, fresh from the Recollection grow pits. Doesn't know what it is or where it came from. Maybe it will take to you. Just mind the tail, now.\"—Fausta Arius, Legion member",
                            ["furnitureId"] = 9158,
                            ["icon"] = "/esoui/art/icons/mount_boichecalled.dds",
                            ["category"] = "Heavyweights",
                        },
                        [11444] = 
                        {
                            ["name"] = "Welkyndstone Ruins Wolf",
                            ["hint"] = "",
                            ["id"] = 11444,
                            ["description"] = "\"The Dawnwood's new, but the forest's roots reach deep. The Ayleids were here before us, and they left their own mark on the land. We tamed this beast through the Green, but Y'ffre knows how long it's been out here.\" —Nothelas, Bosmer priest",
                            ["furnitureId"] = 9159,
                            ["icon"] = "/esoui/art/icons/mount_wenayawend_wolf.dds",
                            ["category"] = "Canines",
                        },
                        [9399] = 
                        {
                            ["name"] = "Evergloam Indrik",
                            ["hint"] = "",
                            ["id"] = 9399,
                            ["description"] = "Woven carefully from shadow wisps of Nocturnal's realm, these noble indriks shy from the light of day until trained by a patient rider to tolerate it. Forever after, they move under Magnus's fierce glow as if to defy it.",
                            ["furnitureId"] = 7666,
                            ["icon"] = "/esoui/art/icons/mount_evergloamindrik.dds",
                            ["category"] = "Cervines",
                        },
                        [9400] = 
                        {
                            ["name"] = "Black Drake Howler",
                            ["hint"] = "",
                            ["id"] = 9400,
                            ["description"] = "These wolves were among the first creatures to storm Evermore when the Reachmen's attack broke through the city's walls. Each wolf's unique markings display their lineage with some incorporating designs from Durcorach's beloved howler herself.",
                            ["furnitureId"] = 7667,
                            ["icon"] = "/esoui/art/icons/mount_blackdrakehowler.dds",
                            ["category"] = "Canines",
                        },
                        [9401] = 
                        {
                            ["name"] = "Gloam Gryphon Fledgling",
                            ["hint"] = "",
                            ["id"] = 9401,
                            ["description"] = "Contrary to popular belief, this cute-yet-terrifying Evergloam creature does not eat shadows to grow larger. But they definitely do win at games that involve hiding in murky places—a gift from Nocturnal herself, perhaps?",
                            ["furnitureId"] = 7668,
                            ["icon"] = "/esoui/art/icons/pet_gloamgryphon.dds",
                            ["category"] = "Exotic",
                        },
                        [11450] = 
                        {
                            ["name"] = "Bright Moons Dragon Imp",
                            ["hint"] = "",
                            ["id"] = 11450,
                            ["description"] = "\"A very talented Imp, no? It cannot be denied Jone and Jode have blessed this creature with their light. Some even speak of having to hide their moon sugar from it!\" —Adept Lakjo",
                            ["furnitureId"] = 9176,
                            ["icon"] = "/esoui/art/icons/pet_bright-moons-dragon-imp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [11451] = 
                        {
                            ["name"] = "Mystical Quasigriff",
                            ["hint"] = "",
                            ["id"] = 11451,
                            ["description"] = "This beast has been touched by the deep magic, connecting to the power between the worlds. It carried a draught of creatia back with it to Nirn, glimmering with potential in every feather and bone.",
                            ["furnitureId"] = 9189,
                            ["icon"] = "/esoui/art/icons/mount_mysticalquasigriff.dds",
                            ["category"] = "Heavyweights",
                        },
                        [1214] = 
                        {
                            ["name"] = "Karthwolf Shepherd",
                            ["hint"] = "",
                            ["id"] = 1214,
                            ["description"] = "The Reachmen of Western Skyrim use their domesticated ice wolves to protect their clans' livestock. They also keep the herds healthy, as the Karthwolves themselves will cull out the weaklings.",
                            ["furnitureId"] = 4400,
                            ["icon"] = "/esoui/art/icons/pet_142.dds",
                            ["category"] = "Exotic",
                        },
                        [11455] = 
                        {
                            ["name"] = "Sunset Welwa",
                            ["hint"] = "",
                            ["id"] = 11455,
                            ["description"] = "\"Reptilian welwa are particularly prized among the Argonians. This could be due to their perceived connection to the Hist, or simply the fact that their scales allow them to wallow in the marsh alongside their masters.\"—Black Marsh Rider's Guide",
                            ["furnitureId"] = 9191,
                            ["icon"] = "/esoui/art/icons/mount_sunsetwelwa.dds",
                            ["category"] = "Heavyweights",
                        },
                        [7360] = 
                        {
                            ["name"] = "Aeonstone Formation",
                            ["hint"] = "Awarded for completing the \"Fall of the Dark Aeon\" achievement in Southern Elsweyr.",
                            ["id"] = 7360,
                            ["description"] = "The unusual properties of the crystal known as aeonstone continue to confound alchemists and arcane researchers. This particular formation resonates with nearby inactive deposits, causing them to emit a soft glow.",
                            ["furnitureId"] = 6628,
                            ["icon"] = "/esoui/art/icons/housing_rok_els_darkempyreanvariant011.dds",
                            ["category"] = "General",
                        },
                        [9409] = 
                        {
                            ["name"] = "Scorion Pyreling",
                            ["hint"] = "Awarded by earning the \"Waking Flame Explorer\" achievement.",
                            ["id"] = 9409,
                            ["description"] = "\"Though I agree these pyrelings are fiery and intimidating, I can't believe they acted like ticks on Dragons, as one scholar who shall remain nameless stated in my presence. No, instead I think they are variants native to the Deadlands.\"—Vi Aspblade",
                            ["furnitureId"] = 7671,
                            ["icon"] = "/esoui/art/icons/pet_daedriccollector.dds",
                            ["category"] = "Daedric",
                        },
                        [11458] = 
                        {
                            ["name"] = "Master-Wizard's Ram",
                            ["hint"] = "",
                            ["id"] = 11458,
                            ["description"] = "\"Most mages prefer not to ride onto the front line of a battle. But if they must, they go prepared. The Mages Guild chooses their steeds with care, only training the most surefooted rams to carry their magisters into battle.\"—Magus Vacia Sidonia",
                            ["furnitureId"] = 9221,
                            ["icon"] = "/esoui/art/icons/mount_magisterstravelram.dds",
                            ["category"] = "Cervines",
                        },
                        [11459] = 
                        {
                            ["name"] = "Maligraphic Skeever",
                            ["hint"] = "Acquired by completing the \"Scheming Skeevers\" achievement.",
                            ["id"] = 11459,
                            ["description"] = "Leave it to a skeever to somehow wriggle free of the Infinite Archive. This Maligraphy probably poses minimal threat to the world at large. Let's just hope none of its bigger brethren learn the same trick.",
                            ["furnitureId"] = 9227,
                            ["icon"] = "/esoui/art/icons/pet_gallinkapocryphaskeever.dds",
                            ["category"] = "Exotic",
                        },
                        [11460] = 
                        {
                            ["name"] = "Stainedwing Butterfly",
                            ["hint"] = "",
                            ["id"] = 11460,
                            ["description"] = "Despite their magnificent and fragile appearance, these butterflies are quite resilient. They've been known to cling to their chosen master through thick and thin, even in the midst of battle.",
                            ["furnitureId"] = 9228,
                            ["icon"] = "/esoui/art/icons/pet_chromaticbutterfly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [11461] = 
                        {
                            ["name"] = "Blueblood Frog Hound Pup",
                            ["hint"] = "",
                            ["id"] = 11461,
                            ["description"] = "\"Don't let the eyes fool you. This pup is a master manipulator. It'll have you believing it's never eaten a day in its life while there's still a frog leg hanging from its mouth. By Julianos, it's hard to resist though.\"—Scholar Vilia Ceno",
                            ["furnitureId"] = 9229,
                            ["icon"] = "/esoui/art/icons/pet_bluebloodfroghound.dds",
                            ["category"] = "Domestic",
                        },
                        [11464] = 
                        {
                            ["name"] = "Saarthal Shepherd",
                            ["hint"] = "",
                            ["id"] = 11464,
                            ["description"] = "\"Any Nord can be proud with a canine like this at their side. Our ancestors tamed them ages ago. Ever since, they've been helping us watch our flocks, scare predators away, and keep unruly children from getting underfoot.\"—Farmer Eoeilif",
                            ["furnitureId"] = 9230,
                            ["icon"] = "/esoui/art/icons/pet_saarthalshepherd.dds",
                            ["category"] = "Domestic",
                        },
                        [11465] = 
                        {
                            ["name"] = "Meridia-Touched Asp",
                            ["hint"] = "",
                            ["id"] = 11465,
                            ["description"] = "The way it shimmers in the sunlight makes it obvious this is not an average snake. The serpent glows with an iridescent magic, which it uses to hypnotize its prey when it rears up. Even men and mer struggle to resist its mesmerizing scales.",
                            ["furnitureId"] = 9231,
                            ["icon"] = "/esoui/art/icons/pet_meridiatouchedasp.dds",
                            ["category"] = "Exotic",
                        },
                        [1232] = 
                        {
                            ["name"] = "Dwarven Theodolite",
                            ["hint"] = "Acquired by finding its seven parts in Nchuleftingth, and combining them.",
                            ["id"] = 1232,
                            ["description"] = "This construct was a sort of automated measuring device designed to explore and survey subterranean areas, according to scholars of the lost Deep Elves—except for Narsis Dren, who insists it was an object of pursuit in Dwemeri team sports.",
                            ["furnitureId"] = 4401,
                            ["icon"] = "/esoui/art/icons/pet_140.dds",
                            ["category"] = "Exotic",
                        },
                        [11473] = 
                        {
                            ["name"] = "Statuette: Vivec's Triumph",
                            ["hint"] = "",
                            ["id"] = 11473,
                            ["description"] = "A miniature version of the \"Thirty-Fourth Sermon\" statue, carved by the people of Necrom.",
                            ["furnitureId"] = 9233,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu40vivecstatuette001.dds",
                            ["category"] = "General",
                        },
                        [11474] = 
                        {
                            ["name"] = "Painting: Sanity's Edge",
                            ["hint"] = "",
                            ["id"] = 11474,
                            ["description"] = "\"As you can see by my attached references, I am one of the foremost experts in vicinage wards, forfending spells, and the art of research. If anyone can deal with the Dreamstone's ire, it is me. I hope you come to the same conclusion.\"—Warlock Vanton",
                            ["furnitureId"] = 9234,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingsanitysedgepainting001.dds",
                            ["category"] = "General",
                        },
                        [1237] = 
                        {
                            ["name"] = "Bust: Assembly General",
                            ["hint"] = "Awarded for completing Veteran Halls of Fabrication.",
                            ["id"] = 1237,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in the Halls of Fabrication.",
                            ["furnitureId"] = 4402,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialdwarvencolossus001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [9431] = 
                        {
                            ["name"] = "Pellucid Swamp Jelly",
                            ["hint"] = "Acquired from the Gates of Oblivion Grab Bag.",
                            ["id"] = 9431,
                            ["description"] = "A favorite of veterinarians and beast masters across Tamriel, these netches are prized for their clear gelatinous outer membranes that allow students to view its organs from a distance.",
                            ["furnitureId"] = 7673,
                            ["icon"] = "/esoui/art/icons/pet_pellucidswampjelly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [1241] = 
                        {
                            ["name"] = "Vvardvark",
                            ["hint"] = "",
                            ["id"] = 1241,
                            ["description"] = "The Common, or Demotic Vvardvark has become, in just a few years, an everyday sight on the island of Vvardenfell. But where did they come FROM? Popular opinion points the finger at the wizards of House Telvanni—but they get blamed for everything.",
                            ["furnitureId"] = 4403,
                            ["icon"] = "/esoui/art/icons/pet_137.dds",
                            ["category"] = "Exotic",
                        },
                        [13271] = 
                        {
                            ["name"] = "Za'ji",
                            ["hint"] = "",
                            ["id"] = 13271,
                            ["description"] = "Captain Za'ji of the Perfect Pounce sails the seas from Elsweyr to High Isle. Now, though, he hopes to bunk with you while his ship is being refit. After adding Za'ji to your home, you can set him on a path, plus you and your visitors can speak with him.×",
                            ["furnitureId"] = 10489,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Houseguests",
                        },
                        [9437] = 
                        {
                            ["name"] = "Soulfire Dragon Illusion",
                            ["hint"] = "",
                            ["id"] = 9437,
                            ["description"] = "\"After much knowledge-seeking, I learned to summon an illusion of a small, fiery Dragon to follow me. While it's not the same as the real thing, that endears me to it more. Who wants a real Dragon around, after all?\"—Ninaleon Sightbinder the First",
                            ["furnitureId"] = 7675,
                            ["icon"] = "/esoui/art/icons/pet_goldillusiondragon.dds",
                            ["category"] = "Flying Pets",
                        },
                        [13091] = 
                        {
                            ["name"] = "Painting: Lucent Citadel",
                            ["hint"] = "",
                            ["id"] = 13091,
                            ["description"] = "Shrouded in mystery, the Lucent Citadel gleams in the sand of Fargrave's wastelands.",
                            ["furnitureId"] = 10382,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu44lucentcitadelpainting001.dds",
                            ["category"] = "General",
                        },
                        [9439] = 
                        {
                            ["name"] = "Dremnaken Runt",
                            ["hint"] = "Acquired by completing the quest \"Hope Springs Eternal.\"",
                            ["id"] = 9439,
                            ["description"] = "This Dremnaken may be the runt of its pack, but it is still prepared to follow its leader into danger. It uses its armor to show other Dremnaken that it is every bit as fierce as they are, despite its diminutive size.",
                            ["furnitureId"] = 7676,
                            ["icon"] = "/esoui/art/icons/pet_redwelwa.dds",
                            ["category"] = "Daedric",
                        },
                        [9440] = 
                        {
                            ["name"] = "Bastian Hallix",
                            ["hint"] = "Obtained by completing quest \"Family Secrets.\"",
                            ["id"] = 9440,
                            ["description"] = "Diligent and steadfast heroes like Bastian Hallix still need time to unwind. His chivalrous charm is sure to brighten up any room. After adding Bastian to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 7823,
                            ["icon"] = "/esoui/art/icons/houseguest_bastian.dds",
                            ["category"] = "Houseguests",
                        },
                        [9441] = 
                        {
                            ["name"] = "Mirri Elendis",
                            ["hint"] = "Obtained by completing quest \"Dead Weight.\"",
                            ["id"] = 9441,
                            ["description"] = "The intrepid explorer, Mirri Elendis, needs a break from her irksome family. With thrilling tales and a sailor's mouth, she's sure to impress! After adding Mirri to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 7824,
                            ["icon"] = "/esoui/art/icons/houseguest_mirri.dds",
                            ["category"] = "Houseguests",
                        },
                        [1250] = 
                        {
                            ["name"] = "Ebon Dwarven Horse",
                            ["hint"] = "",
                            ["id"] = 1250,
                            ["description"] = "Though most ancient Dwemer automata are constructed primarily of the so-called Dwarven Metal, some rare and special animunculus mounts use a preponderance of Ebony. Creations like the Ebon Dwarven Horse are especially durable.",
                            ["furnitureId"] = 4404,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_ebon_horse.dds",
                            ["category"] = "Equines",
                        },
                        [1251] = 
                        {
                            ["name"] = "Vitrine Dwarven Horse",
                            ["hint"] = "",
                            ["id"] = 1251,
                            ["description"] = "\"A horse-shaped Dwarven mount constructed of Ebony, Adamant, Dwarven Metal, and Glass? Sure, why not? The Dwemer could build almost anything, and seemed determined to prove it.\" —Herebane, Nord \"Scholar of the Vanished\"",
                            ["furnitureId"] = 4405,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_vitrine_horse.dds",
                            ["category"] = "Equines",
                        },
                        [1252] = 
                        {
                            ["name"] = "Ebon Dwarven Senche",
                            ["hint"] = "",
                            ["id"] = 1252,
                            ["description"] = "Certain rare Dwarven senche vamidiums are constructed with key mechanical components forged, not of the usual Dwarven metal, but of ebony and ebony-steel alloys.",
                            ["furnitureId"] = 4406,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_senche_b.dds",
                            ["category"] = "Felines",
                        },
                        [1253] = 
                        {
                            ["name"] = "Vitrine Dwarven Senche",
                            ["hint"] = "",
                            ["id"] = 1253,
                            ["description"] = "\"When considering the Dwarven automaton mounts, the so-called vamidiums, one gets the sense that the Deep Elves were not attempting to replicate nature, but to improve upon it. Case in point: the Vitrine Senche.\" —Thelwe Ghelein, Scholar of the Dwemer",
                            ["furnitureId"] = 4407,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_vitrine_senche.dds",
                            ["category"] = "Felines",
                        },
                        [1254] = 
                        {
                            ["name"] = "Vitrine Dwarven Wolf",
                            ["hint"] = "",
                            ["id"] = 1254,
                            ["description"] = "Of all known Dwarven mounts, or vamidiums, one of the rarest is the Wolf animunculus with critical components made, not of Dwarven Metal, but of some sort of Dwemeri Glass.",
                            ["furnitureId"] = 4408,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_wolf_c.dds",
                            ["category"] = "Canines",
                        },
                        [13090] = 
                        {
                            ["name"] = "Statuette: High Elf Mage",
                            ["hint"] = "",
                            ["id"] = 13090,
                            ["description"] = "\"Some claim to know the provenance of this sleek piece of art, but they know nothing. Especially when it comes to how impressive your home would be with a replica in it!\" —Zaidrashi, Merchant",
                            ["furnitureId"] = 10381,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_altmagestatuette001.dds",
                            ["category"] = "General",
                        },
                        [9448] = 
                        {
                            ["name"] = "Alcaire Blue Cockeral",
                            ["hint"] = "",
                            ["id"] = 9448,
                            ["description"] = "The cockerels of Alcaire Castle uphold their noble duty and make as much noise during daybreak as possible. Their screeching continues well into the morning, waking any lucky enough to miss out on their earliest morning calls.",
                            ["furnitureId"] = 7843,
                            ["icon"] = "/esoui/art/icons/pet_bluegoldrooster.dds",
                            ["category"] = "Domestic",
                        },
                        [9449] = 
                        {
                            ["name"] = "Rustbite Ringtail",
                            ["hint"] = "",
                            ["id"] = 9449,
                            ["description"] = "Creating a perfect diversion any time it walks behind you, a Rustbite Ringtail's adorably wide eyes never fail to draw a crowd of enamored onlookers. What you do with a crowd of happily distracted townsfolk is your business.",
                            ["furnitureId"] = 7844,
                            ["icon"] = "/esoui/art/icons/pet_siennaringtail.dds",
                            ["category"] = "Exotic",
                        },
