                        [10577] = 
                        {
                            ["name"] = "Trophy: Tideborn Taleria",
                            ["hint"] = "Awarded for completing Dreadsail Reef.",
                            ["id"] = 10577,
                            ["description"] = "Trophy taken from Tideborn Taleria in honor of an Undaunted victory in Dreadsail Reef.",
