                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophycoralatronach001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [10576] = 
                        {
                            ["name"] = "Icerage Bear",
                            ["hint"] = "",
                            ["id"] = 10576,
                            ["description"] = "Scrolls from Direfrost Keep indicate that the ice witches first invoked these creatures as vessels to contain their rage and hunt those who had wronged them. Presumably they wanted loyal familiars, but found the bears also make formidable mounts.",
                            ["furnitureId"] = 8542,
                            ["icon"] = "/esoui/art/icons/mount_iceragebear.dds",
                            ["category"] = "Ursines",
                        },
                        [10510] = 
                        {
                            ["name"] = "Tales of Tribute Decks, Display",
                            ["hint"] = "Acquired by completing the Deck Builder Achievement.",
                            ["id"] = 10510,
                            ["description"] = "A perfect display case for your perfect decks! What more can you ask for other than victory?",
                            ["furnitureId"] = 8537,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_totdisplaycase001.dds",
                            ["category"] = "General",
                        },
                        [10509] = 
                        {
                            ["name"] = "Tales of Tribute Table, Display",
                            ["hint"] = "Acquired by reaching Master Rank in Tales of Tribute.",
                            ["id"] = 10509,
                            ["description"] = "Set up your home's gaming room properly with this exquisite Tales of Tribute table.\n\n|cFFFFFFThis table does not allow you to play Tales of Tribute matches.|r",
                            ["furnitureId"] = 8536,
                            ["icon"] = "/esoui/art/icons/housing_uni_fur_housingtottable001.dds",
                            ["category"] = "General",
                        },
                        [5765] = 
                        {
                            ["name"] = "Blue Shock Nixad",
                            ["hint"] = "",
                            ["id"] = 5765,
                            ["description"] = "The rare and colorful Shock Nixad looks rather like a tiny, winged Storm Atronach, though without the whirling electric rocks. They make loyal companions—though they may also make your hair stand on end!",
                            ["furnitureId"] = 5583,
                            ["icon"] = "/esoui/art/icons/pet_228_stormnixad.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10429] = 
                        {
                            ["name"] = "Crow Court Pony Guar",
                            ["hint"] = "",
                            ["id"] = 10429,
                            ["description"] = "\"You wouldn't think a guar would get along with a murder of crows, but this fine fellow does! Maybe it's the exquisite purple hue? In any case, it's started leaving gemstones for the little menaces. Most peculiar.\"—Irastimil Direnni, Creature Creator",
                            ["furnitureId"] = 8434,
                            ["icon"] = "/esoui/art/icons/pet_purpleguar.dds",
                            ["category"] = "Exotic",
                        },
                        [10427] = 
                        {
                            ["name"] = "Lady Garick's Sacred Shield",
                            ["hint"] = "Awarded for completing the quest, \"Race for Honor\" in High Isle.",
                            ["id"] = 10427,
                            ["description"] = "Lady Joslin Garick brought her crew home safely until the last time—or so the legends state. Now that you have proven worthy of her heritage, you can hang this famous All Flags Navy captain's shield on your wall.",
                            ["furnitureId"] = 8433,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_sacredshield001.dds",
                            ["category"] = "General",
                        },
                        [10418] = 
                        {
                            ["name"] = "Harrowforged Durzog",
                            ["hint"] = "",
                            ["id"] = 10418,
                            ["description"] = "\"Harrowforged Durzog: Ready your quickest poisons and most potent spells. Your target defeated horrors possibly beyond your ken to earn this glorious crimson steed.\"—Recent notation in a chapbook for Dark Brotherhood Initiates",
                            ["furnitureId"] = 8431,
                            ["icon"] = "/esoui/art/icons/mount_harrowforgeddurzog.dds",
                            ["category"] = "Canines",
                        },
                        [10399] = 
                        {
                            ["name"] = "Companion's Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 10399,
                            ["description"] = "The ancestry of this rambunctious dark-furred pup goes all the way back to the Five Hundred Companions of Ysgramor. That doesn't stop it from acting like a mischievous little furball, though!",
                            ["furnitureId"] = 8416,
                            ["icon"] = "/esoui/art/icons/pet_goldcollaredwolfpup.dds",
                            ["category"] = "Exotic",
                        },
                        [10398] = 
                        {
                            ["name"] = "Scarlet War Pangrit",
                            ["hint"] = "",
                            ["id"] = 10398,
                            ["description"] = "\"These hard-headed creatures might seem empty-minded. Yet, somehow, they keep you alive when you've angered the ornaugs. Such is the nature of a loyal mount.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 8415,
                            ["icon"] = "/esoui/art/icons/mount_xitahranagonizer.dds",
                            ["category"] = "Bipedals",
                        },
                        [10397] = 
                        {
                            ["name"] = "Cipher's Eye Pocket Watcher",
                            ["hint"] = "",
                            ["id"] = 10397,
                            ["description"] = "\"What have you learned, Watcher? Mortals on Nirn keep small companions. Oh, is that so? Names you say? As my small companion, you wish one? Very well, I shall call you Ocula. You have indeed earned it.\"—Morian Zenas",
                            ["furnitureId"] = 8414,
                            ["icon"] = "/esoui/art/icons/pet_doomtruthpocketwatcher.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10396] = 
                        {
                            ["name"] = "Crusader's Coin Chicken",
                            ["hint"] = "",
                            ["id"] = 10396,
                            ["description"] = "Easily identifiable by their flaming red feathers, this aggressive barnyard fowl has been used as an alternative to a guard dog by knights on crusade. Their loud crowing is nearly impossible to sleep through.",
                            ["furnitureId"] = 8413,
                            ["icon"] = "/esoui/art/icons/pet_goldenglowchicken.dds",
                            ["category"] = "Domestic",
                        },
                        [10389] = 
                        {
                            ["name"] = "Black Heights Camel",
                            ["hint"] = "",
                            ["id"] = 10389,
                            ["description"] = "\"You'd not think to see camels around this one's home of Black Heights, but you'd be wrong! We love to brighten these fragrant beasts with pigments and a touch of sleekening oil so that they provide both beauty and transport!\"—Hurzarr, Artist",
                            ["furnitureId"] = 8412,
                            ["icon"] = "/esoui/art/icons/mount_blackheightscamel.dds",
                            ["category"] = "Camelids",
                        },
                        [10384] = 
                        {
                            ["name"] = "Skingrad Pillion Courser",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["id"] = 10384,
                            ["description"] = "\"The first pillion mount in Skingrad came about when two of Rislav's siblings wished to ride with fewer guards about. 'Two guards per horse,' they were told. Thus they created the first battle-hardened pillion mount.\"—Richon Charchere, Stablemaster",
                            ["furnitureId"] = 8408,
                            ["icon"] = "/esoui/art/icons/mount_skingradpillioncourser.dds",
                            ["category"] = "Multi-Rider",
                        },
                        [10332] = 
                        {
                            ["name"] = "Ragebound Durzog",
                            ["hint"] = "",
                            ["id"] = 10332,
                            ["description"] = "\"This beast lives a life of controlled fury that only its rider keeps in check. Unfortunately for us, these durzogs usually pick riders who let loose their own wrath with great frequency.\"—Medresi Guvron of Markarth",
                            ["furnitureId"] = 8392,
                            ["icon"] = "/esoui/art/icons/mount_ragebounddurzog.dds",
                            ["category"] = "Canines",
                        },
                        [10331] = 
                        {
                            ["name"] = "Ragebound Kagouti",
                            ["hint"] = "",
                            ["id"] = 10331,
                            ["description"] = "\"You're not hearing me. These were nothing like normal kagouti. Fury, froth, and carnage. And their riders, eyes wide with harnessed rage. That's what drew me in. That's why I joined them.\"—Medresi Guvron of Markarth",
                            ["furnitureId"] = 8391,
                            ["icon"] = "/esoui/art/icons/mount_rageboundkagouti.dds",
                            ["category"] = "Bipedals",
                        },
                        [10330] = 
                        {
                            ["name"] = "Ragebound Bear",
                            ["hint"] = "",
                            ["id"] = 10330,
                            ["description"] = "\"Each pelt and bone on this monster of a bear reminds its rider of past battles. Rage turned to an end. Victory ripped from the rider's enemies. You know the feeling, I think. It's in your eyes. Rage. Barely controlled.\"—Arparnagh of Markarth",
                            ["furnitureId"] = 8390,
                            ["icon"] = "/esoui/art/icons/mount_rageboundbear.dds",
                            ["category"] = "Ursines",
                        },
                        [9874] = 
                        {
                            ["name"] = "Rubyflare Torchnix",
                            ["hint"] = "",
                            ["id"] = 9874,
                            ["description"] = "\"Legends claim the Erabenimsun tamed these luminous creatures after Ashu-Ammu rode the first nix-ox into battle. While it's strange to choose a steed whose glow gives away your position, some warriors delight in added danger before battle.\"—Murdyn Athren",
                            ["furnitureId"] = 8063,
                            ["icon"] = "/esoui/art/icons/mount_rubyfiretorchnix.dds",
                            ["category"] = "Arthropods",
                        },
                        [9875] = 
                        {
                            ["name"] = "Hel Ra Camel of Kingship",
                            ["hint"] = "",
                            ["id"] = 9875,
                            ["description"] = "\"At first, Baezati was angry. They give him a camel? Baezati rides nothing less than a charger. But this one must confess he enjoyed the ride. It was smooth. Fast. Surefooted. Even the rocks around Hel Ra gave the beast no issues.\"—Baezati's Travelogues",
                            ["furnitureId"] = 8064,
                            ["icon"] = "/esoui/art/icons/mount_darkflamecamel.dds",
                            ["category"] = "Camelids",
                        },
                        [9876] = 
                        {
                            ["name"] = "Graniteclaw Durzog",
                            ["hint"] = "",
                            ["id"] = 9876,
                            ["description"] = "\"Graniteclaw Durzogs gorge themselves on the array of sea life swimming around the Systres Archipelago. Their markings help them blend in with the reefs and their feathers keep water from dripping into their eyes.\"—Excerpt from Physiology of Amphibians",
                            ["furnitureId"] = 8065,
                            ["icon"] = "/esoui/art/icons/mount_graniteclawdurzog.dds",
                            ["category"] = "Canines",
                        },
                        [11925] = 
                        {
                            ["name"] = "Kor",
                            ["hint"] = "",
                            ["id"] = 11925,
                            ["description"] = "Hunter, Dark Brotherhood assassin, big brother—Kor is all this and more. Invite him into your abode, and he'll share observations about his life. After adding Kor to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 9601,
                            ["icon"] = "/esoui/art/icons/houseguest_kor.dds",
                            ["category"] = "Houseguests",
                        },
                        [11926] = 
                        {
                            ["name"] = "Hildegard",
                            ["hint"] = "",
                            ["id"] = 11926,
                            ["description"] = "When this fledgling Dark Brotherhood assassin isn't using her werewolf abilities to complete contracts, she reflects on her dual nature. After adding Hildegard to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 9602,
                            ["icon"] = "/esoui/art/icons/houseguest_hildegard.dds",
                            ["category"] = "Houseguests",
                        },
                        [10326] = 
                        {
                            ["name"] = "Galen Wisp",
                            ["hint"] = "",
                            ["id"] = 10326,
                            ["description"] = "Wisps are sent from Y'ffre to herald the storms of Rain's Hand. To see one is to see the promise of new growth, new life, and a new chapter in nature's cycle.",
                            ["furnitureId"] = 8386,
                            ["icon"] = "/esoui/art/icons/pet_stonelorewisp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10318] = 
                        {
                            ["name"] = "Saturalia Ice Steed",
                            ["hint"] = "",
                            ["id"] = 10318,
                            ["description"] = "Tales tell of a mercenary abandoned by her lord during a storm. Her frozen lips begged for help. Sanguine heard her pleas, forming the ice into a steed. Come Saturalia morn, the crimson blood of that lord drenched the snow and evergreen boughs.",
                            ["furnitureId"] = 8369,
                            ["icon"] = "/esoui/art/icons/mount_eveningstarice.dds",
                            ["category"] = "Equines",
                        },
                        [10317] = 
                        {
                            ["name"] = "Moss Spine Daedrat",
                            ["hint"] = "",
                            ["id"] = 10317,
                            ["description"] = "\"We found daedrats eating our ceremonial supplies in the cellar last Midyear. Now the damned things have gone green, and the Archdruid says they're a bridge from Galen to Oblivion? Draigh!\"—Callice Marence, formerly of Daggerfall",
                            ["furnitureId"] = 8368,
                            ["icon"] = "/esoui/art/icons/pet_verdurousdaedrat.dds",
                            ["category"] = "Daedric",
                        },
                        [10303] = 
                        {
                            ["name"] = "Bust: Nazaray",
                            ["hint"] = "Awarded for completing Veteran Shipwright's Regret.",
                            ["id"] = 10303,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Shipwright's Regret.",
                            ["furnitureId"] = 8348,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranspriggan001.dds",
