                        [10300] = 
                        {
                            ["name"] = "Trophy: Kargaeda",
                            ["hint"] = "Awarded for completing Coral Aerie.",
                            ["id"] = 10300,
                            ["description"] = "Trophy taken from Varallion in honor of an Undaunted victory in Coral Aerie.",
                            ["furnitureId"] = 8345,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophycoralgryphon001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [10290] = 
                        {
                            ["name"] = "New Moon Fox",
                            ["hint"] = "",
                            ["id"] = 10290,
                            ["description"] = "\"Do not underestimate the foxes trained by the Cult of the New Moon. Their glowing crimson eyes should be enough to warn you away. If you are foolish enough to attempt to steal an adult, say farewell to Nirn.\"—Jonnet of the Sunwalkers",
                            ["furnitureId"] = 8304,
                            ["icon"] = "/esoui/art/icons/mount_newmoonfox.dds",
                            ["category"] = "Canines",
                        },
                        [10277] = 
                        {
                            ["name"] = "Lemondot Netch",
                            ["hint"] = "",
                            ["id"] = 10277,
                            ["description"] = "\"Do colors seem louder? Does music taste different? Does Tirdas have a personality? You're probably experiencing the synesthesic venom of the rare lemondot netch. Relax. It's harmless. A little new perspective never killed anybody.\"—Alinon the Alchemist",
                            ["furnitureId"] = 8300,
                            ["icon"] = "/esoui/art/icons/pet_lemondotnetch.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10244] = 
                        {
                            ["name"] = "Speckled Welwa",
                            ["hint"] = "",
                            ["id"] = 10244,
                            ["description"] = "This savage welwa so interested members of the College of Sapiarchs that they brought several to Sil-Var-Woad for study. To help endear them to the public, an enterprising conservator trained them to saddle and \"lent\" them out into the wild.",
                            ["furnitureId"] = 8286,
                            ["icon"] = "/esoui/art/icons/mount_speckledwelwa.dds",
                            ["category"] = "Heavyweights",
                        },
                        [10243] = 
                        {
                            ["name"] = "Anchorborn Pony",
                            ["hint"] = "",
                            ["id"] = 10243,
                            ["description"] = "\"Now, I says to my friend, look at all this dark anchor debris. No one's using it. No one owns it. And I look at his pony, this sickly little thing, and I say, why not make ourselves something nice?\"—\"Innovator\" Delan",
                            ["furnitureId"] = 8285,
                            ["icon"] = "/esoui/art/icons/pet_planemeldpony.dds",
                            ["category"] = "Exotic",
                        },
                        [10242] = 
                        {
                            ["name"] = "Stormsurge Howler",
                            ["hint"] = "Awarded by earning the \"Swashbuckler Supreme\" achievement.",
                            ["id"] = 10242,
                            ["description"] = "Covered in coral and barnacles, this unusual sea creature moves like rushing water, creating a smooth traveling experience for its riders. Some speculate that Kyne crafted them from a sea storm and sent them to land to find those who revere her.",
                            ["furnitureId"] = 8280,
                            ["icon"] = "/esoui/art/icons/mount_stormsurgehowler.dds",
                            ["category"] = "Canines",
                        },
                        [10240] = 
                        {
                            ["name"] = "Rustpelt Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 10240,
                            ["description"] = "\"Where'd I get the cat? Cards. Poor thing was used in place of coin by some pet-smuggling lowlife. I'm teaching her how to count cards and fetch me a pint.\"—Privateer Mahk",
                            ["furnitureId"] = 8277,
                            ["icon"] = "/esoui/art/icons/pet_rustpeltsabrecat.dds",
                            ["category"] = "Exotic",
                        },
                        [10239] = 
                        {
                            ["name"] = "Mulberry Hermit Crab",
                            ["hint"] = "Awarded by earning the \"Lost Depths Explorer\" achievement.",
                            ["id"] = 10239,
                            ["description"] = "Before the druids, before the coin-barons, before even the noble houses, the hermit crab held dominion over the Systres. Hauling its belongings wherever it travels, its beady eyes give you a look that seems to say, \"We're not so different, you and I.\"",
                            ["furnitureId"] = 8276,
                            ["icon"] = "/esoui/art/icons/pet_damsonhermitcrab.dds",
                            ["category"] = "Exotic",
                        },
                        [10238] = 
                        {
                            ["name"] = "Morthal Bear-Dog",
                            ["hint"] = "",
                            ["id"] = 10238,
                            ["description"] = "It's the prestige of the mastiffs of Morthal that give the city's resident breed of bear-dog license to be a bit more … silly. Whether watching over children or facing intruders, someone's bound to get a licking.",
                            ["furnitureId"] = 8275,
                            ["icon"] = "/esoui/art/icons/pet_spottedbeardog.dds",
                            ["category"] = "Domestic",
                        },
                        [10237] = 
                        {
                            ["name"] = "Warmaiden's Wolf",
                            ["hint"] = "",
                            ["id"] = 10237,
                            ["description"] = "While Nords claim this lightning-limned wolf seeks out Kyne's champions to serve, the Stonelore Druids believe differently. Only an imbalance in nature would cause such a creature to coalesce. Its purpose? To find a rider who can restore the balance.",
                            ["furnitureId"] = 8274,
                            ["icon"] = "/esoui/art/icons/mount_handmaidensstormwolf.dds",
                            ["category"] = "Canines",
                        },
                        [7110] = 
                        {
                            ["name"] = "Emberthroat Durzog",
                            ["hint"] = "",
                            ["id"] = 7110,
                            ["description"] = "Bred for their wicked intelligence, the Emberthroat Durzog might just outwit the Netch Gouger Goblins that raised them. Only those with nimbler minds keep their loyalty—and that might just be you!",
                            ["furnitureId"] = 6541,
                            ["icon"] = "/esoui/art/icons/pet_durzogemberthroat.dds",
                            ["category"] = "Exotic",
                        },
                        [7272] = 
                        {
                            ["name"] = "Wickerfright Banekin",
                            ["hint"] = "",
                            ["id"] = 7272,
                            ["description"] = "\"Witches refused to share the grisly secrets of the Wickerfright summoning ritual … until now. Upon appearing, its wooden countenance twists into an eerie smile—a frightful expression, indeed!\"—Warlock Aldaale",
                            ["furnitureId"] = 6552,
                            ["icon"] = "/esoui/art/icons/pet_wickerfrightbanekin.dds",
                            ["category"] = "Daedric",
                        },
                        [7506] = 
                        {
                            ["name"] = "Statuette: Auri-El, Aldmer King",
                            ["hint"] = "",
                            ["id"] = 7506,
                            ["description"] = "A miniature statue of Auri-El, chief deity of the Aldmeri pantheon, with an eagle.",
                            ["furnitureId"] = 6638,
                            ["icon"] = "/esoui/art/icons/housing_ayl_run_dbhstatuegarlasmalatarsmall001.dds",
                            ["category"] = "General",
                        },
                        [6406] = 
                        {
                            ["name"] = "New Moon Senche",
                            ["hint"] = "",
                            ["id"] = 6406,
                            ["description"] = "\"Senche steeds are already quiet. This one? It  moves as if it is the avatar of silence.\"—Jonnet of the Sunwalkers",
                            ["furnitureId"] = 5978,
                            ["icon"] = "/esoui/art/icons/mount_newmoonsenche.dds",
                            ["category"] = "Felines",
                        },
                        [6404] = 
                        {
                            ["name"] = "New Moon Camel",
                            ["hint"] = "",
                            ["id"] = 6404,
                            ["description"] = "\"Those seeking their way on dark sands should consider the New Moon Camel. Some say it feeds off the night itself. I say maybe so.\"—Jonnet of the Sunwalkers",
                            ["furnitureId"] = 5976,
                            ["icon"] = "/esoui/art/icons/mount_newmooncamel.dds",
                            ["category"] = "Camelids",
                        },
                        [102] = 
                        {
                            ["name"] = "Doom Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 102,
                            ["description"] = "When a Doom Wolf Pup looks at you with its big red eyes, you may just melt inside—but as soon as you turn your back, that little rascal will be shredding your embroidered Arenthian pillows and digging up your herbal garden.",
                            ["furnitureId"] = 4187,
                            ["icon"] = "/esoui/art/icons/pet_082.dds",
                            ["category"] = "Exotic",
                        },
                        [618] = 
                        {
                            ["name"] = "Pact Lizard Battle Crest",
                            ["hint"] = "",
                            ["id"] = 618,
                            ["description"] = "Going to war may mean donning a helm, but beneath it an Argonian Pact warrior is entitled to wear this official Alliance Battle Crest, which keeps spines under control while still looking superb.",
                            ["furnitureId"] = 4303,
                            ["icon"] = "/esoui/art/icons/hair_unisex_argonian_ebonheartflavor_01.dds",
                            ["category"] = "Hair Styles",
                        },
                        [4671] = 
                        {
                            ["name"] = "Frostbane Bear",
                            ["hint"] = "",
                            ["id"] = 4671,
                            ["description"] = "The Bear was also one of the ancient Atmoran animal tokens, associated later with the Nord god Tsun, so the Frostbane Bear has historically been one of the most prestigious mounts a tradition-loving Nord could ride.",
                            ["furnitureId"] = 4768,
                            ["icon"] = "/esoui/art/icons/mounticon_bear_scalecaller.dds",
                            ["category"] = "Ursines",
                        },
                        [8457] = 
                        {
                            ["name"] = "Nenalata Ayleid Guar",
                            ["hint"] = "",
                            ["id"] = 8457,
                            ["description"] = "\"While resting during their evacuation from Nenalata, guar mounts would voluntarily form a circle around the young and infirm, protecting them from danger. Their leader, Mafrelatta, set her calves amid them to share warmth.\"—Beredalmo the Signifier",
                            ["furnitureId"] = 7267,
                            ["icon"] = "/esoui/art/icons/mount_ayleidguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [484] = 
                        {
                            ["name"] = "Dwarven War Dog",
                            ["hint"] = "",
                            ["id"] = 484,
                            ["description"] = "This loyal beast has been trained for warfare, and will stick with you through every kind of conflict. As a bonus, it comes outfitted in ancient Dwarven dog armor, canine barding as durable today as it was when it was first made many centuries in the past.",
                            ["furnitureId"] = 4295,
                            ["icon"] = "/esoui/art/icons/pet_127.dds",
                            ["category"] = "Exotic",
                        },
                        [483] = 
                        {
                            ["name"] = "Dark Moons Lynx",
                            ["hint"] = "",
                            ["id"] = 483,
                            ["description"] = "The Khajiit of Corinthe believe the all-black Dark Moons Lynx is the worldly incarnation of Southpaw, the feline companion to Rajhin the Footpad, god of thieves. It's said Southpaw keeps watch while Rajhin is breaking and entering.",
                            ["furnitureId"] = 4294,
                            ["icon"] = "/esoui/art/icons/pet_074.dds",
                            ["category"] = "Exotic",
                        },
                        [478] = 
                        {
                            ["name"] = "Infernal Sep Adder",
                            ["hint"] = "",
                            ["id"] = 478,
                            ["description"] = "Though it may look like it just crawled from the depths of the Deadlands, the Infernal Sep Adder is actually native to the higher altitudes of Hammerfell. As pets, they are … not affectionate. Great conversation starters, though.",
                            ["furnitureId"] = 4293,
                            ["icon"] = "/esoui/art/icons/pet_077.dds",
                            ["category"] = "Exotic",
                        },
                        [10209] = 
                        {
                            ["name"] = "Mottled Sheep",
                            ["hint"] = "",
                            ["id"] = 10209,
                            ["description"] = "\"Her calm presence keeps our patients at ease. Sometimes I ask them about the patterns and shapes they see in her coat, and their answers give me insight into their state of mind.\"—Mender Teliel",
                            ["furnitureId"] = 8259,
                            ["icon"] = "/esoui/art/icons/pet_mottledsheep.dds",
                            ["category"] = "Domestic",
                        },
                        [10208] = 
                        {
                            ["name"] = "Glimmertarn Ursauk",
                            ["hint"] = "",
                            ["id"] = 10208,
                            ["description"] = "\"We choose some of our guardians based on their overwhelming presence, like this ursauk. While riding it, I swear that the marrow in my bones resonates with her growls.\"—Rolmanoril of Glimmertarn",
                            ["furnitureId"] = 8258,
                            ["icon"] = "/esoui/art/icons/mount_glistergloambear.dds",
                            ["category"] = "Heavyweights",
                        },
                        [10207] = 
                        {
                            ["name"] = "Harvestleaf Lynx",
                            ["hint"] = "",
                            ["id"] = 10207,
                            ["description"] = "\"When trees shrug off their colorful mantles, druids gather around a lynx summoned by Y'ffre. While they sing chants, the God of Song and Forest transforms the feline into a steed. Only a Hearthfire champion may claim such a mount.\"—Book of the Leaves",
                            ["furnitureId"] = 8257,
                            ["icon"] = "/esoui/art/icons/mount_hearthfirelynx.dds",
                            ["category"] = "Felines",
                        },
                        [10206] = 
                        {
                            ["name"] = "Oldefire Elk",
                            ["hint"] = "",
                            ["id"] = 10206,
                            ["description"] = "\"On the first night of Hearthfire, folks all over the Systres burn blessed oldefire logs. The smoke mingles with the soughing of leaves, giving form to spirits unseen the rest of the year. They take the form of loyal elk steeds.\"—Book of the Leaves",
                            ["furnitureId"] = 8256,
                            ["icon"] = "/esoui/art/icons/mount_fireleafelk.dds",
                            ["category"] = "Cervines",
                        },
                        [11959] = 
                        {
                            ["name"] = "Dark Brotherhood Crew Steed",
                            ["hint"] = "",
                            ["id"] = 11959,
                            ["description"] = "The steeds of the Dark Brotherhood are conditioned to run blindly ahead in the darkness, fully trusting their riders. When the situation demands it, the horses will even run with multiple riders clinging to them on all sides, never flinching or faltering.",
                            ["furnitureId"] = 9616,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodtandemsteed.dds",
                            ["category"] = "Multi-Rider",
                        },
                        [11960] = 
                        {
                            ["name"] = "Dark Brotherhood Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 11960,
                            ["description"] = "Few creatures are more apt mounts for the Dark Brotherhood than sabre cats. Light on their feet, agile, and with a hunting instinct to match their rider's, many Dark Brotherhood members believe a sabre cat mount is a gift from Sithis himself.",
                            ["furnitureId"] = 9617,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodsabrecat.dds",
                            ["category"] = "Felines",
                        },
                        [11961] = 
                        {
                            ["name"] = "Dark Brotherhood Kagouti",
                            ["hint"] = "",
                            ["id"] = 11961,
                            ["description"] = "\"Sithis teaches silence, yes, but stealth is not always the most important thing when you have enough speed and power on your side. That's why I choose to ride a kagouti. I find their ferocity more than makes up for the noise.\"—Dark Brother Bols Uveleth",
                            ["furnitureId"] = 9618,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodkagouti.dds",
                            ["category"] = "Bipedals",
                        },
                        [11962] = 
                        {
                            ["name"] = "Dark Brotherhood Durzog",
                            ["hint"] = "",
                            ["id"] = 11962,
                            ["description"] = "Unlike other durzogs, which can become vocal when they sense their prey is near, those trained by the Dark Brotherhood have been bred for speed and silence.",
                            ["furnitureId"] = 9619,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhooddurzog.dds",
                            ["category"] = "Canines",
                        },
                        [10201] = 
                        {
                            ["name"] = "Stonelore Bear",
                            ["hint"] = "",
                            ["id"] = 10201,
                            ["description"] = "Each of the druid circles keeps a different ursine companion. The Stonelore bear was originally bred to help with ambitious construction projects. While druids shaped heavy stone slabs, their bears supported the more fragile components of the structures.",
                            ["furnitureId"] = 8251,
                            ["icon"] = "/esoui/art/icons/mount_stonelorebear.dds",
                            ["category"] = "Ursines",
                        },
                        [10199] = 
                        {
                            ["name"] = "Druid-Bound Ursauk",
                            ["hint"] = "",
                            ["id"] = 10199,
                            ["description"] = "\"I prefer the company of animals over people. Communing with the Evergrowth provides a calming respite from the need to speak. This ursauk, for example, has proven most personable. And now, it needs a rider.\"—Druid Dolvasie",
                            ["furnitureId"] = 8249,
                            ["icon"] = "/esoui/art/icons/mount_monsterousbear.dds",
                            ["category"] = "Heavyweights",
                        },
                        [1392] = 
                        {
                            ["name"] = "Flame Atronach Camel",
                            ["hint"] = "",
                            ["id"] = 1392,
                            ["description"] = "When Peregrine Direnni passed her Master Conjurer test by summoning the first-ever Flame Atronach Camel, her mentor Corvus gave her high marks but was heard to comment, \"Now you're just showing off.\"",
                            ["furnitureId"] = 4474,
                            ["icon"] = "/esoui/art/icons/mounticon_atronachcamel_a.dds",
                            ["category"] = "Camelids",
                        },
                        [1387] = 
                        {
                            ["name"] = "Shadowghost Pack Wolf",
                            ["hint"] = "",
                            ["id"] = 1387,
                            ["description"] = "Unlike their lone cousins, the great Shadowghost Wolf Mounts, the smaller Shadowghost Pack Wolves hunt on the darkest nights in howling groups. Separated from their packs, they make loyal companions.",
                            ["furnitureId"] = 4473,
                            ["icon"] = "/esoui/art/icons/pet_151.dds",
                            ["category"] = "Exotic",
                        },
                        [1380] = 
                        {
                            ["name"] = "Clockwork Skeevaton",
                            ["hint"] = "",
                            ["id"] = 1380,
                            ["description"] = "Originally designed for probing tiny, inaccessible areas of the Clockwork City, the mechanical Skeevaton can be set to recognize and follow an individual mortal, replicating pet behavior on the surface of Nirn.",
                            ["furnitureId"] = 4471,
                            ["icon"] = "/esoui/art/icons/pat_153.dds",
                            ["category"] = "Exotic",
                        },
                        [10182] = 
                        {
                            ["name"] = "Statuette: Mehrunes Dagon",
                            ["hint"] = "",
                            ["id"] = 10182,
                            ["description"] = "A miniature statue of Mehrunes Dagon, Daedric Prince of Destruction and Ambition.",
                            ["furnitureId"] = 8197,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedagon001.dds",
                            ["category"] = "General",
                        },
                        [10181] = 
                        {
                            ["name"] = "Statuette: Kaladas of Leyawiin",
                            ["hint"] = "",
                            ["id"] = 10181,
                            ["description"] = "A miniature statue of Saint Kaladas, builder of the Great Chapel of Zenithar in Leyawiin.",
                            ["furnitureId"] = 8196,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettestkaladas001.dds",
                            ["category"] = "General",
                        },
                        [10065] = 
                        {
                            ["name"] = "Aurulun Fledgling Gryphon",
                            ["hint"] = "",
                            ["id"] = 10065,
                            ["description"] = "Spring blossoms nod their heads as if recognizing kin in this Elf-pampered companion. Some caretakers claim these gryphons provide a sense of ease to those who care for them—and pain for those who seek their demise.",
                            ["furnitureId"] = 8195,
                            ["icon"] = "/esoui/art/icons/pet_aurulungryphon.dds",
                            ["category"] = "Exotic",
                        },
                        [1147] = 
                        {
                            ["name"] = "Milady's Cloud Cat",
                            ["hint"] = "",
                            ["id"] = 1147,
                            ["description"] = "White cats are sacred to Dibella, the Lady of Love, and all white cats are said to be her representatives in the animal kingdom. A House of Dibella will typically have three or four milk-white cats within its walls.",
                            ["furnitureId"] = 4370,
                            ["icon"] = "/esoui/art/icons/pet_110.dds",
                            ["category"] = "Domestic",
                        },
                        [10061] = 
                        {
                            ["name"] = "Azuredoom Wrathsteed",
                            ["hint"] = "",
                            ["id"] = 10061,
                            ["description"] = "\"The sight of this welwa's claws sparks something in my imagination, showing me different scenarios where those icy talons end my life. It's beautiful. In a horrible, gruesome way. I wonder if it can be tamed?\"—Pyn Bossard, Welwa Researcher (Deceased)",
                            ["furnitureId"] = 8192,
                            ["icon"] = "/esoui/art/icons/mount_icefirewrathsteed.dds",
                            ["category"] = "Heavyweights",
                        },
                        [1145] = 
                        {
                            ["name"] = "Dwarven War Horse",
                            ["hint"] = "",
                            ["id"] = 1145,
                            ["description"] = "This loyal horse has been trained for warfare, and will stick with you through every kind of conflict. As a bonus, it comes outfitted in ancient Dwarven horse armor.\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4368,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_p.dds",
                            ["category"] = "Equines",
                        },
                        [1144] = 
                        {
                            ["name"] = "Molag Amur Cliff Strider",
                            ["hint"] = "",
                            ["id"] = 1144,
                            ["description"] = "The Molag Amur Cliff Strider is prized by reptilian connoisseurs because its coloration, though somber, is lightened by its subtle golden tones. And if startled, its squawk will cause passersby to jump and horses to bolt.",
                            ["furnitureId"] = 4367,
                            ["icon"] = "/esoui/art/icons/pet_131.dds",
                            ["category"] = "Exotic",
                        },
                        [1143] = 
                        {
                            ["name"] = "Bust: Selene",
                            ["hint"] = "Awarded for completing Veteran Selene's Web.",
                            ["id"] = 1143,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Selene's Web.",
                            ["furnitureId"] = 4366,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranselenwebspider001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [1142] = 
                        {
                            ["name"] = "Bust: Grothdarr",
                            ["hint"] = "Awarded for completing Veteran Vaults of Madness.",
                            ["id"] = 1142,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Vaults of Madness.",
                            ["furnitureId"] = 4365,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranfleshatronach001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [5236] = 
                        {
                            ["name"] = "Silver Dawn Argent Charger",
                            ["hint"] = "",
                            ["id"] = 5236,
                            ["description"] = "Werewolf hunting is a dirty and largely thankless business, but when a Silver Dawn member mounts their resplendent Argent Charger, they feel like the hero they really are. Sure, it's showy, but as a defender of society against the vicious, you deserve it.",
                            ["furnitureId"] = 5439,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_silverdawn.dds",
                            ["category"] = "Equines",
                        },
                        [1139] = 
                        {
                            ["name"] = "Bust: Possessed Mantikora",
                            ["hint"] = "Awarded for completing Veteran Sanctum Ophidia.",
                            ["id"] = 1139,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Sanctum Ophidia.",
                            ["furnitureId"] = 4362,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialmantikora001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [9578] = 
                        {
                            ["name"] = "Great Dark Ram",
                            ["hint"] = "",
                            ["id"] = 9578,
                            ["description"] = "\"The mythic texts of discredited scholars are right, the Great Dark Ram lives! Hircine appears in this form only during Rain's Hand in the Great Forest. Soon, there will be the trials of virility. I hope my strength endures.\"—Lost Journal of Bekelva",
                            ["furnitureId"] = 7911,
                            ["icon"] = "/esoui/art/icons/mount_greatdarkram.dds",
                            ["category"] = "Cervines",
                        },
                        [9632] = 
                        {
                            ["name"] = "Trophy: Magma Incarnate",
                            ["hint"] = "Awarded for completing The Dread Cellar.",
                            ["id"] = 9632,
                            ["description"] = "Trophy taken from the Magma Incarnate in honor of an Undaunted victory in the Dread Cellar.",
                            ["furnitureId"] = 8026,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyearthincarnate001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [9633] = 
                        {
                            ["name"] = "Bust: Prior Thierric Sarazen",
                            ["hint"] = "Awarded for completing Veteran Red Petal Bastion.",
                            ["id"] = 9633,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Red Petal Bastion.",
                            ["furnitureId"] = 8023,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranartifactmaster001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [9684] = 
                        {
                            ["name"] = "Wailing Shackler Wolf",
                            ["hint"] = "",
                            ["id"] = 9684,
                            ["description"] = "\"In my defense, those heroes just left pieces of that Dark Anchor lying there. All of that auxiliary magic? What if some evil cult got it? Oh, and I wanted to make a Senche … but one of the runes got smudged.\"—Interview with Frugal Jedd, Mage",
                            ["furnitureId"] = 7928,
                            ["icon"] = "/esoui/art/icons/mount_wailingshacklerwolf.dds",
                            ["category"] = "Canines",
                        },
                        [9685] = 
                        {
                            ["name"] = "Luminous Meridian Charger",
                            ["hint"] = "",
                            ["id"] = 9685,
                            ["description"] = "\"Meridia's charger manifests wherever vile darkness gathers. In 298 1E, it blazed out of the sunrise and into Cath Bedraud where the righteous flames of the Sunfire reduced a nest of bloodfiends to ashes.\"—Terendra Vocula, Priest of Inner Luminance",
                            ["furnitureId"] = 7929,
                            ["icon"] = "/esoui/art/icons/mount_luminousmeridiancharger.dds",
                            ["category"] = "Equines",
                        },
                        [9786] = 
                        {
                            ["name"] = "Screaming Midyear Nixad",
                            ["hint"] = "",
                            ["id"] = 9786,
                            ["description"] = "\"Why. Can't. They. Keep. Quiet? Arkay blesses them with their own cycle, but every few years they claw their way back into Greenshade. And what do they do once they get here? Scream. Constantly.\"—Hasinel, Lament of the Midyear Screech",
                            ["furnitureId"] = 7954,
                            ["icon"] = "/esoui/art/icons/pet_screamingnixad.dds",
                            ["category"] = "Flying Pets",
                        },
                        [9794] = 
                        {
                            ["name"] = "Flint-Pelt Fox",
                            ["hint"] = "",
                            ["id"] = 9794,
                            ["description"] = "Legend tells of a Breton hunter who freed a Flint-Pelt Fox from a hagraven's snare. Now these creatures seek out any warrior who calls hagravens \"foe,\" often lingering around areas terrorized by their hated enemies.",
                            ["furnitureId"] = 8027,
                            ["icon"] = "/esoui/art/icons/mount_grayfox.dds",
                            ["category"] = "Canines",
                        },
                        [9795] = 
                        {
                            ["name"] = "Hay-Crown Chub Loon",
                            ["hint"] = "",
                            ["id"] = 9795,
                            ["description"] = "Hay-Crown Chub Loons were revered as omens of good harvests until one winter in Rivenspire, when desperate farmers discovered that these creatures were delectable. Druids took the dim-witted, delicious birds with them when they fled to High Isle.",
                            ["furnitureId"] = 8028,
                            ["icon"] = "/esoui/art/icons/pet_haycrownchubloon.dds",
                            ["category"] = "Exotic",
                        },
                        [9805] = 
                        {
                            ["name"] = "Falkreath Riding-Lynx",
                            ["hint"] = "",
                            ["id"] = 9805,
                            ["description"] = "The people of Falkreath call these lynxes \"blizzard bringers.\" The cats are as powerful as the buffeting winds that scour the slopes of the Shriekwind Bastion. There are even rumors that the lynx's growl causes avalanches high up in the mountains.",
                            ["furnitureId"] = 8055,
                            ["icon"] = "/esoui/art/icons/mount_snowfalllynx.dds",
                            ["category"] = "Felines",
                        },
                        [9819] = 
                        {
                            ["name"] = "Arox the Mutilator",
                            ["hint"] = "",
                            ["id"] = 9819,
                            ["description"] = "Kneel before the mighty Arox and he might just offer to crush your enemies for you! But, as a daedrat. Not his former much bigger self. After adding Arox to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 8058,
                            ["icon"] = "/esoui/art/icons/houseguest_arox.dds",
                            ["category"] = "Houseguests",
                        },
                        [9979] = 
                        {
                            ["name"] = "Midnight Cantor Senche-Raht",
                            ["hint"] = "",
                            ["id"] = 9979,
                            ["description"] = "After spending years expelling dro-m'Athra from Nirn, M'aar decided to follow a new path. Now they hope to explore as much of the Mundus as possible before venturing to the Gates of the Crossing.",
                            ["furnitureId"] = 8069,
                            ["icon"] = "/esoui/art/icons/mount_stygiansencheraht.dds",
                            ["category"] = "Heavyweights",
                        },
                        [5846] = 
                        {
                            ["name"] = "Hot Pepper Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5846,
                            ["description"] = "The Hot Pepper Bantam Guar breed is native to the \"spice island\" of Esroniet, the source of much of Tamriel's nutmeg, cloves, mace, and hot peppers. And the Pepper Guar has a spicy little personality to go with its name!",
                            ["furnitureId"] = 5590,
                            ["icon"] = "/esoui/art/icons/pet_236_hotpepperbantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5847] = 
                        {
                            ["name"] = "Eerie Violet Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5847,
                            ["description"] = "\"The recesses of our nightmares contain horrors that we often cannot look at. Yet we must, lest these pockets of terror fester and grow. To light your path, I present this bantam guar. Please do not squeal.\" — Overheard in a dark alley",
                            ["furnitureId"] = 5591,
                            ["icon"] = "/esoui/art/icons/pet_255_twitchbantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5848] = 
                        {
                            ["name"] = "Hot-Blooded Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5848,
                            ["description"] = "When asked about the rumor that the Hot-Blooded Bantam Guar had been bred as a vampiric sub-species by the disgraced mage Darvasen before he was exiled from Shad Astula, Arch-Mage Valeyn replied, \"What nonsense! They just like to eat tomatoes. Trust me.\"",
                            ["furnitureId"] = 5592,
                            ["icon"] = "/esoui/art/icons/pet_250_bloodbuddybantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5849] = 
                        {
                            ["name"] = "Coldharbour Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5849,
                            ["description"] = "Start with a dollop of wiggly cuteness, add a dash of the Coldharbour glow, and you get a bantam guar that causes \"oohs!\" and \"ahhhs!\" wherever you go, plus helps you avoid stubbing your toe at night when you leave your bed. Genius!",
                            ["furnitureId"] = 5593,
                            ["icon"] = "/esoui/art/icons/pet_251_coldharbourbantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5850] = 
                        {
                            ["name"] = "Atmoran Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5850,
                            ["description"] = "\"A fur-less, cold-blooded reptile with icy blue eyes that comes from the frozen, far-north, and in-all-likelihood legendary continent of Atmora? Bah. I refuse to believe it.\" —Phrastus of Elinhir",
                            ["furnitureId"] = 5594,
                            ["icon"] = "/esoui/art/icons/pet_237_atmoranbantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5851] = 
                        {
                            ["name"] = "Deadlands Bantam Guar",
                            ["hint"] = "",
                            ["id"] = 5851,
                            ["description"] = "It may look cute, but this volcanic little pest comes from Mehrunes Dagon's Oblivion plane of the Deadlands: it's got lava in its blood and fire in its eyes, so keep it away from the curtains.",
                            ["furnitureId"] = 5595,
                            ["icon"] = "/esoui/art/icons/pet_247_deadlandbantam.dds",
                            ["category"] = "Exotic",
                        },
                        [5852] = 
                        {
                            ["name"] = "Explorer's Pack Donkey",
                            ["hint"] = "|cffffffPurchasing this pet increases your inventory capacity by 5 slots on all characters account wide.|r",
                            ["id"] = 5852,
                            ["description"] = "A donkey might not be the most glamorous pack animal, but it's certainly the hardiest and most sure-footed, toting heavy loads through desert, mountains, and tundra without complaint … though it will give you a dirty look, and might nip if you turn away!",
                            ["furnitureId"] = 5596,
                            ["icon"] = "/esoui/art/icons/pet_253_donkey.dds",
                            ["category"] = "Inventory",
                        },
                        [5853] = 
                        {
                            ["name"] = "Atmoran Chub Loon",
                            ["hint"] = "",
                            ["id"] = 5853,
                            ["description"] = "According to Nord legend, in its native land of Atmora this Chub Loon is much larger, as tall as two warriors and with a squawk that starts avalanches. It took mighty Ysgramor a day and a night to wrestle one down from Shivering Glacier. What, you doubt?",
                            ["furnitureId"] = 5597,
                            ["icon"] = "/esoui/art/icons/pet_240_atmoranchubloon.dds",
                            ["category"] = "Exotic",
                        },
                        [5854] = 
                        {
                            ["name"] = "Treasure Hunter's Horse",
                            ["hint"] = "",
                            ["id"] = 5854,
                            ["description"] = "Stolid, careful, sturdy, and long-suffering, the Treasure Hunter's Horse is resigned to a life of being ridden into crumbling ruins by a reckless master who's searching for wealth but often finds only danger.",
                            ["furnitureId"] = 5598,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_treasurehunter.dds",
                            ["category"] = "Equines",
                        },
                        [5855] = 
                        {
                            ["name"] = "Winterhold Wolfhound",
                            ["hint"] = "",
                            ["id"] = 5855,
                            ["description"] = "North of Windhelm in Skyrim, where the snow on the heights never melts, the Nords' great Wolfhounds have lighter and fluffier fur coats. In addition to barking, they even howl a bit like the wolves they pursue.",
                            ["furnitureId"] = 5599,
                            ["icon"] = "/esoui/art/icons/pet_254_winterholdwolfhound.dds",
                            ["category"] = "Domestic",
                        },
                        [5856] = 
                        {
                            ["name"] = "Icebound Dwarven Spider",
                            ["hint"] = "Awarded for completing the \"Frostvault Conqueror\" Achievement.",
                            ["id"] = 5856,
                            ["description"] = "One might think that being frozen in a glacier for several thousand years would damage a delicate mechanism like a Dwarven Spider, but in the case of the Icebound units it seems instead to have preserved them in perfect working order.",
                            ["furnitureId"] = 5600,
                            ["icon"] = "/esoui/art/icons/pet_257_dwarvenice.dds",
                            ["category"] = "Exotic",
                        },
                        [5857] = 
                        {
                            ["name"] = "Lustrated Daedrat",
                            ["hint"] = "",
                            ["id"] = 5857,
                            ["description"] = "\"The forces of Nocturnal's attempted invasion of the Colored Rooms were inadvertently accompanied by some Evergloam Daedrats, which afterward were rounded up, Lustrated for purification, and then banished to Nirn.\" —Sapiarch Galaadil",
                            ["furnitureId"] = 5601,
                            ["icon"] = "/esoui/art/icons/pet_239_purifieddaedrat.dds",
                            ["category"] = "Daedric",
                        },
                        [5858] = 
                        {
                            ["name"] = "Dragonscale Frost Senche",
                            ["hint"] = "",
                            ["id"] = 5858,
                            ["description"] = "According to the notebooks of Corvus Direnni, the frost senche-panther may actually be a form of atronach summoned from a plane known as the Fourth Sinus of Takubar. Why it remains in Tamriel where it willingly submits to the orders of mortals is unknown.",
                            ["furnitureId"] = 5602,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexsenche.dds",
                            ["category"] = "Felines",
                        },
                        [5859] = 
                        {
                            ["name"] = "Dragonscale Solar Horse",
                            ["hint"] = "",
                            ["id"] = 5859,
                            ["description"] = "\"I have been fortunate enough to have personally glimpsed a Solar Horse on an Anequine morning, and I say with conviction that it must be a creature of Magrus, the Cat's Eye, and no other.\" —Moon-Bishop Hunal",
                            ["furnitureId"] = 5603,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexhorse.dds",
                            ["category"] = "Equines",
                        },
                        [9837] = 
                        {
                            ["name"] = "Salamandrine Guar",
                            ["hint"] = "",
                            ["id"] = 9837,
                            ["description"] = "\"Boredom. Boredom and that accursed holiday in Stonefalls. That's why I used my considerable skills to merge a salamander and a guar. Hmm. The colors are striking. It was just a whim, but I'm pleased with the results.\"—Irastimil Direnni, Creature Creator",
                            ["furnitureId"] = 8062,
                            ["icon"] = "/esoui/art/icons/mount_salamandrineguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [5861] = 
                        {
                            ["name"] = "Meridian Sabre Cub",
                            ["hint"] = "",
                            ["id"] = 5861,
                            ["description"] = "\"Our Lady of the Infinite Energies, Strict but Fair Arbiter of Inner Luminance, grant unto thy most devoted worshiper a sign of thy radiant favor, mayhap a loveable, glowing Sabre Cat cub.\" —Sayings of Valasha",
                            ["furnitureId"] = 5605,
                            ["icon"] = "/esoui/art/icons/pet_244_purifiedsenchecub.dds",
                            ["category"] = "Exotic",
                        },
                        [5862] = 
                        {
                            ["name"] = "Pebble Pal",
                            ["hint"] = "|cff0000This pet cannot path when placed as a furnishing.|r",
                            ["id"] = 5862,
                            ["description"] = "Tired of pets that follow you everywhere? Fed up with feeding them? Step up to Pebble Pal, the pet that's a … rock.",
                            ["furnitureId"] = 5606,
                            ["icon"] = "/esoui/art/icons/pet_258_pebblepal.dds",
                            ["category"] = "Exotic",
                        },
                        [5863] = 
                        {
                            ["name"] = "Pink Pearl Pig",
                            ["hint"] = "",
                            ["id"] = 5863,
                            ["description"] = "Pining for a perfect pet? Perhaps you're a person who'd prefer a pleasantly playful piglet, pearly-white, pretty, and partial to paladins and protectors!",
                            ["furnitureId"] = 5607,
                            ["icon"] = "/esoui/art/icons/pet_238_pinkpig.dds",
                            ["category"] = "Domestic",
                        },
                        [5864] = 
                        {
                            ["name"] = "Carnelian Theodolite",
                            ["hint"] = "",
                            ["id"] = 5864,
                            ["description"] = "The Dwarven Theodolite was a sort of automated measuring device designed to explore and survey subterranean areas; this version is notable for its distinctive red \"eye.\"",
                            ["furnitureId"] = 5608,
                            ["icon"] = "/esoui/art/icons/pet_248_redtheodolite.dds",
                            ["category"] = "Exotic",
                        },
                        [5865] = 
                        {
                            ["name"] = "Dragonscale Storm Wolf",
                            ["hint"] = "",
                            ["id"] = 5865,
                            ["description"] = "\"I would speculate that the Storm Wolf is the result of an experiment by a powerful Destruction mage in which a wild canine was subjected to prolonged exposure to a Meip Glyph of Shock.\" —Gabrielle Benele, Wizard",
                            ["furnitureId"] = 5609,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexwolf.dds",
                            ["category"] = "Canines",
                        },
                        [5866] = 
                        {
                            ["name"] = "Sweetroll Grizzly",
                            ["hint"] = "",
                            ["id"] = 5866,
                            ["description"] = "The rare Sweetroll Grizzly Bears prowl the golden forests of the Rift on the northern slopes of the Jerall Mountains. They're big strong cuddly hug machines—except when they're angry.",
                            ["furnitureId"] = 5610,
                            ["icon"] = "/esoui/art/icons/mounticon_bear_sweetroll.dds",
                            ["category"] = "Ursines",
                        },
                        [5867] = 
                        {
                            ["name"] = "Tenmar Senche-Tiger",
                            ["hint"] = "",
                            ["id"] = 5867,
                            ["description"] = "Deep in the shadows of the Tenmar Forest, hidden by its camouflaged coat and stealthy stalking, the Senche-Tiger is a nearly invisible jungle predator. Even as a mount, it retains something of the air of mystery it wears in the wild.",
                            ["furnitureId"] = 5611,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_tenmartiger.dds",
                            ["category"] = "Felines",
                        },
                        [5868] = 
                        {
                            ["name"] = "Glenumbra Border Wolf",
                            ["hint"] = "",
                            ["id"] = 5868,
                            ["description"] = "Though in coloration the Glenumbra Border Wolf resembles certain Breton dog breeds, this sturdy and stoic mount is no dog, and will carry a High Rock courier for leagues through dark night and heavy weather.",
                            ["furnitureId"] = 5612,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_glennumbra.dds",
                            ["category"] = "Canines",
                        },
                        [5869] = 
                        {
                            ["name"] = "Meridian Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 5869,
                            ["description"] = "\"Some accounts of Meridia's plane of the Colored Rooms describe a menagerie of light-imbued spectral beasts elevated from Nirn and 'purified' by the Lady's holy light.\" —Sayings of Valasha",
                            ["furnitureId"] = 5613,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_purified.dds",
                            ["category"] = "Felines",
                        },
                        [5870] = 
                        {
                            ["name"] = "Novelty Stick Horse",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["id"] = 5870,
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Horses are popular in the Daggerfall Covenant.",
                            ["furnitureId"] = 5614,
                            ["icon"] = "/esoui/art/icons/mounticon_stick_horse.dds",
                            ["category"] = "Toys",
                        },
                        [5871] = 
                        {
                            ["name"] = "Verdant Tattoo Shorn Camel",
                            ["hint"] = "",
                            ["id"] = 5871,
                            ["description"] = "Shorn Camels are desert mounts with elaborate Tattoos on their hide where once there were wiry bristles. The \"Verdant,\" with its repeating floral designs, may be the most beautiful of them all.",
                            ["furnitureId"] = 5615,
                            ["icon"] = "/esoui/art/icons/mounticon_camel_verdantshorn.dds",
                            ["category"] = "Camelids",
                        },
                        [5872] = 
                        {
                            ["name"] = "Dragonscale Barded Camel",
                            ["hint"] = "",
                            ["id"] = 5872,
                            ["description"] = "Frankly, compared to war horses, bear mounts, and even saddle guars, it's hard for Camels to look magnificent—until you dress them in Dragonscale Bard. Then look out!",
                            ["furnitureId"] = 5616,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_camel.dds",
                            ["category"] = "Camelids",
                        },
                        [5873] = 
                        {
                            ["name"] = "Dragonscale Barded Guar",
                            ["hint"] = "",
                            ["id"] = 5873,
                            ["description"] = "\"This one doesn't sell many Guars here at the Riverhold Stables because Khajiit are folk who value their natural dignity and prefer not to ride so silly a beast. But a Guar in Dragonscale Bard is a thing of beauty!\" — Master Groom Zarbi'dahuz",
                            ["furnitureId"] = 5617,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_guar.dds",
                            ["category"] = "Bipedals",
                        },
                        [5874] = 
                        {
                            ["name"] = "Dragonscale Barded Senche",
                            ["hint"] = "",
                            ["id"] = 5874,
                            ["description"] = "\"Our distant cousins, the senche-mounts, look so majestic in Dragonscale Bard, like creatures who've just stepped out of an ancient wall-frieze in Dune. Perhaps these pesky Dragons have a use after all, yes?\" — Master Groom Zarbi'dahuz",
                            ["furnitureId"] = 5618,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_senche.dds",
                            ["category"] = "Felines",
                        },
                        [5875] = 
                        {
                            ["name"] = "Dragonscale Barded Wolf",
                            ["hint"] = "",
                            ["id"] = 5875,
                            ["description"] = "\"I had always thought the Helkarn Wolf to be Elsweyr's finest Wolf mount, but that was before I saw a cavalry Wolf in Dragonscale Bard. Could a mount look any more martial?\" — Master Groom Zarbi'dahuz",
                            ["furnitureId"] = 5619,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_wolf.dds",
                            ["category"] = "Canines",
                        },
                        [5876] = 
                        {
                            ["name"] = "Dragonscale Barded Bear",
                            ["hint"] = "",
                            ["id"] = 5876,
                            ["description"] = "Dragonscale bard is just about the heaviest armor one can put on a mount, but bears bred as mounts are so strong they scarcely seem to notice it.",
                            ["furnitureId"] = 5620,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_bear.dds",
                            ["category"] = "Ursines",
                        },
                        [5877] = 
                        {
                            ["name"] = "Dragonscale Barded War-Horse",
                            ["hint"] = "",
                            ["id"] = 5877,
                            ["description"] = "\"Dragons are a pain in the tailbones, yes? But their scales make such superb steed armor! The Dragonscale Barded War-Horse may be the sharpest mount this one has ever seen!\" — Master Groom Zarbi'dahuz",
                            ["furnitureId"] = 5621,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_horse.dds",
                            ["category"] = "Equines",
                        },
                        [5878] = 
                        {
                            ["name"] = "Daggerfall Dapple Horse",
                            ["hint"] = "",
                            ["id"] = 5878,
                            ["description"] = "The Daggerfall Dapple is a hardy horse breed that comes from the Farwatch region of Glenumbra between Daggerfall and Camlorn. Known for its endurance, it's a favorite of long-distance riders.",
                            ["furnitureId"] = 5622,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_speckled.dds",
                            ["category"] = "Equines",
                        },
                        [5879] = 
                        {
                            ["name"] = "Novelty Stick Guar",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["id"] = 5879,
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Guars are popular in the Aldmeri Dominion.",
                            ["furnitureId"] = 5623,
                            ["icon"] = "/esoui/art/icons/mounticon_stick_guar.dds",
                            ["category"] = "Toys",
                        },
                        [5880] = 
                        {
                            ["name"] = "Novelty Stick Dragon",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["id"] = 5880,
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Dragons are popular in the Ebonheart Pact.",
                            ["furnitureId"] = 5624,
                            ["icon"] = "/esoui/art/icons/mounticon_stick_dragon.dds",
                            ["category"] = "Toys",
                        },
                        [9977] = 
                        {
                            ["name"] = "Aurora Firepot Spider",
                            ["hint"] = "",
                            ["id"] = 9977,
                            ["description"] = "Feeling festive? Let this little firepot spider follow you around! With its adorable alchemical light show, you're bound to brighten up anyone's day—including your own!",
                            ["furnitureId"] = 8067,
                            ["icon"] = "/esoui/art/icons/pet_aurorafirepotspider.dds",
                            ["category"] = "Exotic",
                        },
                        [9978] = 
                        {
                            ["name"] = "Salamandrine Pony Guar",
                            ["hint"] = "",
                            ["id"] = 9978,
                            ["description"] = "\"To my chagrin, thieves stole my current batch of pony guars! I'd hoped to gift some to my cousin, who adored my salamandrine guar and whose love of pony guars knows no bounds. Those thieves had better watch out.\"—Irastimil Direnni, Creature Creator",
                            ["furnitureId"] = 8068,
                            ["icon"] = "/esoui/art/icons/pet_salamanderponyguar.dds",
                            ["category"] = "Exotic",
                        },
                        [7931] = 
                        {
                            ["name"] = "Biro-dar",
                            ["hint"] = "",
                            ["id"] = 7931,
                            ["description"] = "Don't let Biro-dar's appearance deceive you! He's not your average scholar. In fact, he makes for an entertaining and trouble-prone guest. After adding Biro-dar to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 6742,
                            ["icon"] = "/esoui/art/icons/assistant_birodar.dds",
                            ["category"] = "Houseguests",
                        },
                        [9980] = 
                        {
                            ["name"] = "Tortoiseshell Echatere",
                            ["hint"] = "",
                            ["id"] = 9980,
                            ["description"] = "While they often disagree on theology, the Orsinium Orcs are unified by their love of this echatere's coat. Some call it a blessing from Trinimac. Others call it an outcast's brand from Malacath. Either way, this beast is a bundle of skittering joy.",
                            ["furnitureId"] = 8070,
                            ["icon"] = "/esoui/art/icons/pet_spottedechalette.dds",
                            ["category"] = "Exotic",
                        },
                        [9981] = 
                        {
                            ["name"] = "Spellscar Kagouti",
                            ["hint"] = "",
                            ["id"] = 9981,
                            ["description"] = "Driven to madness by the erratic magic around the Spellscar, these kagouti make surprisingly excellent pets. In comparison to their lucid and more aggressive kin, an insane kagouti is docile and picks up commands with ease.",
                            ["furnitureId"] = 8071,
                            ["icon"] = "/esoui/art/icons/mount_spellscarkagouti.dds",
                            ["category"] = "Bipedals",
                        },
                        [9982] = 
                        {
                            ["name"] = "Wraithtide Senche",
                            ["hint"] = "",
                            ["id"] = 9982,
                            ["description"] = "\"Some believe these skeletal senche respond to the call of a lost soul seeking safe passage. I firmly believe Y'ffre's hand is involved, and I pray I can prove it one day.\"—Druid Phillic",
                            ["furnitureId"] = 8072,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntsenche.dds",
                            ["category"] = "Felines",
                        },
                        [9983] = 
                        {
                            ["name"] = "Wraithtide Horse",
                            ["hint"] = "",
                            ["id"] = 9983,
                            ["description"] = "\"The day a Stonelore druid thundered in on this frightful sea-birthed horse, well … let's just say I'm glad I recognized Druid Dolvasie on top. Her ferocious expression will haunt my nightmares—as will this steed.\"—Squire Hareld, Oaken Order",
                            ["furnitureId"] = 8073,
                            ["icon"] = "/esoui/art/icons/mount_wraithhaunthorse.dds",
                            ["category"] = "Equines",
                        },
                        [9984] = 
                        {
                            ["name"] = "Wraithtide Guar",
                            ["hint"] = "",
                            ["id"] = 9984,
                            ["description"] = "\"The ghost of Ol' Brineburr herds glowing guar down trade roads, seeking buyers. Don't be put off by their appearance. Or, hmmm, maybe seeing your steed's skeleton is a bonus to you? Regardless, get one.\"—Initiate Rogeric",
                            ["furnitureId"] = 8074,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [9985] = 
                        {
                            ["name"] = "Wraithtide Bear",
                            ["hint"] = "",
                            ["id"] = 9985,
                            ["description"] = "\"Where mages born from water gather, they enact ancient rites. Together they bind the essence of bear and sea and death, forming it into a mount one of their number may ride. Or so the tales go.\"—Druid Sandire",
                            ["furnitureId"] = 8075,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntbear.dds",
                            ["category"] = "Ursines",
                        },
                        [9986] = 
                        {
                            ["name"] = "Wraithtide Wolf",
                            ["hint"] = "",
                            ["id"] = 9986,
                            ["description"] = "\"Communing with the Evergrowth is sometimes confusing. I saw the waters birth an unusual wolf pack, flowing like the angry waves that gave them life. Experience proves they possess the same loyalty other wolves have toward their riders.\"—Druid Anotille",
                            ["furnitureId"] = 8076,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntwolf.dds",
                            ["category"] = "Canines",
                        },
                        [9683] = 
                        {
                            ["name"] = "Wealdspirit Bear",
                            ["hint"] = "",
                            ["id"] = 9683,
                            ["description"] = "\"A whole bear? You grew a whole bear? Well? What are you doing with it still? Get out there! Burn a fort to the ground! Make it hit some rocks with its paws! Bask in bear-y devastation!\"—Glooredel, Vinedusk Ranger",
                            ["furnitureId"] = 7927,
                            ["icon"] = "/esoui/art/icons/mount_vineduskbear.dds",
                            ["category"] = "Ursines",
                        },
                        [9678] = 
                        {
                            ["name"] = "Soulrazer Guar",
                            ["hint"] = "",
                            ["id"] = 9678,
                            ["description"] = "The crypts of High Isle are littered with walking suits of armor. Those who survive say that the armor protects treasures of old. But I suspect they haunt the black hallways, waiting for the dead to wake.\"—Grod, Castle Navire Crypt Keeper",
                            ["furnitureId"] = 7924,
                            ["icon"] = "/esoui/art/icons/mount_soulrazerguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [9677] = 
                        {
                            ["name"] = "Soulrazer Bear",
                            ["hint"] = "",
                            ["id"] = 9677,
                            ["description"] = "\"We know that a crazed necromancer forged these creatures with his dying breath. They are unrelenting, and never stop even when the Ritemaster commands them. Inexplicably, some of the bears sit calmly at the feet of the apprentices.\"—Yrssin, Psijic Order",
                            ["furnitureId"] = 7923,
                            ["icon"] = "/esoui/art/icons/mount_soulrazerbear.dds",
                            ["category"] = "Ursines",
                        },
                        [9676] = 
                        {
                            ["name"] = "Soulrazer Senche",
                            ["hint"] = "",
                            ["id"] = 9676,
                            ["description"] = "Plates of armor hover around the nonexistent fur of a blue senche. It makes no noise—does not growl or roar with the thrill of the chase. It creeps across the ground slowly, knowing that no prey can escape once the hunt has begun.",
                            ["furnitureId"] = 7922,
                            ["icon"] = "/esoui/art/icons/mount_soulrazersenche.dds",
                            ["category"] = "Felines",
                        },
                        [9645] = 
                        {
                            ["name"] = "Meadowglass Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 9645,
                            ["description"] = "Cey-Tarn Keep dog-handlers made armor training wolf pups a priority after older members of the pack gnawed their plate-harnesses to pieces. The practice lives on in this pup who proudly displays his Elven panoply as he trots beside his owner.",
                            ["furnitureId"] = 7918,
                            ["icon"] = "/esoui/art/icons/pet_glassworkwolfcub.dds",
                            ["category"] = "Exotic",
                        },
                        [9643] = 
                        {
                            ["name"] = "Balfiera Senche Cub",
                            ["hint"] = "",
                            ["id"] = 9643,
                            ["description"] = "Bred for their lithe frame and large eyes, these senches excel at tracking prey through the dark underbrush of Balfiera. The Direnni Hegemony fell, but their senches prowl on, hunting during the night and sharpening their claws during the day.",
                            ["furnitureId"] = 7917,
                            ["icon"] = "/esoui/art/icons/pet_balfierasenchecub.dds",
                            ["category"] = "Exotic",
                        },
                        [9640] = 
                        {
                            ["name"] = "Infernium",
                            ["hint"] = "",
                            ["id"] = 9640,
                            ["description"] = "Template Description",
                            ["furnitureId"] = 7916,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Exotic",
                        },
                        [9639] = 
                        {
                            ["name"] = "Voideater Durzog",
                            ["hint"] = "",
                            ["id"] = 9639,
                            ["description"] = "No one knows how these beasts found their way into Blackreach, but it didn't take long for them to heed the Dark Heart's call. Drenched in the void's corruption, this mount will chill your enemies to the bone.",
                            ["furnitureId"] = 7915,
                            ["icon"] = "/esoui/art/icons/mount_voideaterdurzog.dds",
                            ["category"] = "Canines",
                        },
                        [9636] = 
                        {
                            ["name"] = "Harrowstorm Bear",
                            ["hint"] = "",
                            ["id"] = 9636,
                            ["description"] = "Tainted by proximity to active harrowstorms, these bears have become hexed abominations—perfect for warriors with cold blood and dark intentions.",
                            ["furnitureId"] = 7913,
                            ["icon"] = "/esoui/art/icons/mount_stormspawnseeker.dds",
                            ["category"] = "Ursines",
                        },
                        [9635] = 
                        {
                            ["name"] = "Meadowglass Wolf",
                            ["hint"] = "",
                            ["id"] = 9635,
                            ["description"] = "Alchemists in Cey-Tarn Keep fashion mount armor out of specially treated Culanda stones. No alchemist will say exactly what properties the resulting meadowglass has, but scouts riding meadowglass armored wolves have yet to be captured.",
                            ["furnitureId"] = 7912,
                            ["icon"] = "/esoui/art/icons/mount_glassworkwolf.dds",
                            ["category"] = "Canines",
                        },
                        [9997] = 
                        {
                            ["name"] = "Glimmergreen Dovah-Fly",
                            ["hint"] = "",
                            ["id"] = 9997,
                            ["description"] = "\"Respect the dovah-fly. They are the spirits of the ancestors given new life. They brighten the quiet tranquility of ponds and streams. What better afterlife is there?\"—Druid Henneque Blakeley",
                            ["furnitureId"] = 8077,
                            ["icon"] = "/esoui/art/icons/pet_glimmergreendovafly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [9998] = 
                        {
                            ["name"] = "Yoltoor Dovah-Fly",
                            ["hint"] = "",
                            ["id"] = 9998,
                            ["description"] = "Shimmering like fire, these dovah-flies dart around port cities, eating many of the nuisance insects that pester transported livestock. Recently, merchants started training and selling them to help others with insect issues.",
                            ["furnitureId"] = 8078,
                            ["icon"] = "/esoui/art/icons/pet_yoltoordovafly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [9999] = 
                        {
                            ["name"] = "Armory Station",
                            ["hint"] = "",
                            ["id"] = 9999,
                            ["description"] = "You can place this station in multiple homes, where it allows you and your guests to save and equip Armory builds.",
                            ["furnitureId"] = 8079,
                            ["icon"] = "/esoui/art/icons/housing_gen_crf_armorycraftingbase001.dds",
                            ["category"] = "General",
                        },
                        [9577] = 
                        {
                            ["name"] = "Catwell",
                            ["hint"] = "",
                            ["id"] = 9577,
                            ["description"] = "The cat's eyes seem to speak, saying, \"Jolly good to see you! We appear to have a small blight of rodents. Dreadful crawling things. Scuttling everywhere. Hmm, skittering blights. I knew a good joke about that. What? Oh, yes. Lovely day for a hunt!\"",
                            ["furnitureId"] = 7910,
                            ["icon"] = "/esoui/art/icons/pet_catwell.dds",
                            ["category"] = "Domestic",
                        },
                        [9576] = 
                        {
                            ["name"] = "Grand Pillion Draft Horse",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["id"] = 9576,
                            ["description"] = "Ride in style with a close friend or partner on this sturdy Skyrim-bred draft horse! With its pillion saddle crafted from genuine horker leather, this horse possesses strength to take two riders without breaking a sweat.",
                            ["furnitureId"] = 7909,
                            ["icon"] = "/esoui/art/icons/mount_pillionhorse.dds",
                            ["category"] = "Multi-Rider",
                        },
                        [9575] = 
                        {
                            ["name"] = "Coral Crawler Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 9575,
                            ["description"] = "\"Do these coral spiders simply mimic Dwarven spiders or did coral grow over a discarded animunculus? I haven't pried one open to find out—they really don't like that, so don't even try.\"—Wheezing Wilren",
                            ["furnitureId"] = 7908,
                            ["icon"] = "/esoui/art/icons/mount_coralcrawler.dds",
                            ["category"] = "Constructs",
                        },
                        [9574] = 
                        {
                            ["name"] = "Cat O' War Senche Lion",
                            ["hint"] = "",
                            ["id"] = 9574,
                            ["description"] = "\"Like Spriggans roam the glades on land, so does this creature prowl around the tidepools. Its gnarled wooden bones sprout with aquatic life. If it sees me, I'm sure it'll tear my throat out.\"—Scrap from the lost journal of Teldh",
                            ["furnitureId"] = 7907,
                            ["icon"] = "/esoui/art/icons/mount_seaorchardsenche.dds",
                            ["category"] = "Felines",
                        },
                        [9573] = 
                        {
                            ["name"] = "Surfglow Courser",
                            ["hint"] = "",
                            ["id"] = 9573,
                            ["description"] = "As swift as the waves at high tide, this steed's gallop is unmatched. With its glowing mane and shining tail, night riding on this Surfglow Courser is the most sublime experiences known to equestrians.",
                            ["furnitureId"] = 7906,
                            ["icon"] = "/esoui/art/icons/mount_surfglowcourser.dds",
                            ["category"] = "Equines",
                        },
                        [9572] = 
                        {
                            ["name"] = "Amenos Ornaug",
                            ["hint"] = "",
                            ["id"] = 9572,
                            ["description"] = "Though still feared by those traveling to and from Amenos, the ornaug packs native to local waters can serve as loyal steeds if tamed and trained. Or so say the prisoners dreaming of freedom on that prison isle.",
                            ["furnitureId"] = 7905,
                            ["icon"] = "/esoui/art/icons/mount_amenosseabeast.dds",
                            ["category"] = "Serpentes",
                        },
