                        [9465] = 
                        {
                            ["name"] = "Trophy: Xalvakka",
                            ["hint"] = "Awarded for completing Rockgrove.",
                            ["id"] = 9465,
                            ["description"] = "Trophy taken from Xalvakka in honor of an Undaunted victory in Rockgrove.",
                            ["furnitureId"] = 7854,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyrockgrove001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [9464] = 
                        {
                            ["name"] = "Reefborn Guar",
                            ["hint"] = "",
                            ["id"] = 9464,
                            ["description"] = "\"You'll find few wild guars wandering Abecean shores, but these coral beasts dance in the shallows nonetheless. Wherever they came from, they still exhibit the tamed guars' playful disposition.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 7853,
                            ["icon"] = "/esoui/art/icons/mount_coraldriftguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [9463] = 
                        {
                            ["name"] = "Reefborn Bear",
                            ["hint"] = "",
                            ["id"] = 9463,
                            ["description"] = "\"If you visit Abecean islands, you need to be ready to handle reefborn creatures. The bears, for example, do bear things. Mostly. But watch them near saltwater—they'll roll in it whether you're on them or not.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 7852,
                            ["icon"] = "/esoui/art/icons/mount_coraldriftbear.dds",
                            ["category"] = "Ursines",
                        },
                        [9462] = 
                        {
                            ["name"] = "Nightmare Bear",
                            ["hint"] = "",
                            ["id"] = 9462,
                            ["description"] = "Foolhardy warriors travel into the charred Deadlands forests to face off against the ursine horrors that reside there. Lucky adventurers return to their homelands alive, but forever haunted by the sound of red-hot claws digging into ashen dirt.",
                            ["furnitureId"] = 7851,
                            ["icon"] = "/esoui/art/icons/mount_nightmarebear.dds",
                            ["category"] = "Ursines",
                        },
                        [9461] = 
                        {
                            ["name"] = "Reefborn Senche-Lion",
                            ["hint"] = "",
                            ["id"] = 9461,
                            ["description"] = "\"Mages Guild scholars think someone creates these types of senches. With what magic, I don't know. Maybe some sea-loving druid? Regardless, they're as fierce as you'd expect for a senche mount.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 7850,
                            ["icon"] = "/esoui/art/icons/mount_coraldriftsenche.dds",
                            ["category"] = "Felines",
                        },
                        [9460] = 
                        {
                            ["name"] = "Reefborn Wolf",
                            ["hint"] = "",
                            ["id"] = 9460,
                            ["description"] = "\"Those who love wolves may find this breed boosts their prestige in some Abecean coastal areas, especially among the druid folk. While you need stern discipline to train this one to saddle, you gain a lifelong adventuring partner.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 7849,
                            ["icon"] = "/esoui/art/icons/mount_coraldriftwolf.dds",
                            ["category"] = "Canines",
                        },
                        [9459] = 
                        {
                            ["name"] = "Reefborn Charger",
                            ["hint"] = "",
                            ["id"] = 9459,
                            ["description"] = "\"The hues on these reefborn steeds—wondrous, yes? Instead of flowing manes on these so-called equines, colorful coral grew. Just don't try to feed them apples. They prefer to feed on algal blooms.\"—Saissula, Stablemaster",
                            ["furnitureId"] = 7848,
                            ["icon"] = "/esoui/art/icons/mount_coraldrifthorse.dds",
                            ["category"] = "Equines",
                        },
                        [1140] = 
                        {
