                        [5930] = 
                        {
                            ["name"] = "Replica of the Xinchei-Konu",
                            ["hint"] = "Awarded for bringing all twelve tablets of the Xinchei-Konu to Jekka-Wass Vozei at the Xinchei-Konu Monument northeast of Lilmoth.",
                            ["id"] = 5930,
                            ["description"] = "This meticulous reproduction of the ancient Argonian calendar may not have the storied history of the original, but is a masterpiece of stonework in its own right.",
                            ["furnitureId"] = 5801,
                            ["icon"] = "/esoui/art/icons/housing_arg_run_floorcalendar001.dds",
                            ["category"] = "General",
                        },
                        [9451] = 
                        {
                            ["name"] = "Mustardseed Moth",
                            ["hint"] = "",
                            ["id"] = 9451,
                            ["description"] = "Known for its brilliant yellow hues, this moth flits through the deciduous fall forests of Cyrodiil almost unseen. Each year, some fly beyond the Heartland's borders in all directions, as if trying to escape the war-torn province.",
                            ["furnitureId"] = 7846,
                            ["icon"] = "/esoui/art/icons/pet_sungoldmoth.dds",
                            ["category"] = "Flying Pets",
                        },
                        [9450] = 
                        {
                            ["name"] = "Mossy Vvardvark",
                            ["hint"] = "",
                            ["id"] = 9450,
                            ["description"] = "\"Now, surely the presence of this creature is enough to dissuade those pompous academics from believing magic created the first Vvardvark. Who would create a creature so listless that moss grows on it?\"—Atmore, Vvardenfell Zoological Field Commission",
                            ["furnitureId"] = 7845,
                            ["icon"] = "/esoui/art/icons/pet_mossyvvardvark.dds",
                            ["category"] = "Exotic",
                        },
                        [5172] = 
                        {
                            ["name"] = "Atmoran Snow Bear Cub",
                            ["hint"] = "",
                            ["id"] = 5172,
                            ["description"] = "When a cub, the young Atmoran Snow Bear is a lap-clambering cuddle bug, a friendly fuzzball whose demeanor is completely at odds with the fierce reputation of adult Snow Bears. Enjoy them while they're still small!",
                            ["furnitureId"] = 5447,
                            ["icon"] = "/esoui/art/icons/pet_189_atmoranbearcub.dds",
                            ["category"] = "Exotic",
                        },
                        [5173] = 
                        {
                            ["name"] = "Atmoran Snow Bear",
                            ["hint"] = "",
                            ["id"] = 5173,
                            ["description"] = "These fiercely noble Snow Bears are said to have been brought from the legendary frozen continent of Atmora by mighty Ysgramor himself, who deemed them the only worthy avatars of the ancient Nord Bear totem.",
                            ["furnitureId"] = 5556,
                            ["icon"] = "/esoui/art/icons/mounticon_bear_atmoransnow.dds",
                            ["category"] = "Ursines",
                        },
                        [5179] = 
                        {
                            ["name"] = "Ebon Steel Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 5179,
                            ["description"] = "Though Dwarven Metal was usually employed in building Spider constructs, for reasons unknown some rare variants were built with a darker Ebon Steel alloy. When found in working order, these automata are prized by collectors.",
                            ["furnitureId"] = 5519,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_spider_ebonyyellow.dds",
                            ["category"] = "Constructs",
                        },
                        [5180] = 
                        {
                            ["name"] = "Solar Arc Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 5180,
                            ["description"] = "This extremely rare Dwarven Spider model is surmounted with a double golden crescent, interpreted by scholars of the Dwemer as a \"Solar Arc,\" or tribute to the sun—an iconography otherwise completely unknown among the handiworks of the Deep Elves.",
                            ["furnitureId"] = 5509,
                            ["icon"] = "/esoui/art/icons/pet_200_dwarven-ebonyyellow.dds",
                            ["category"] = "Exotic",
                        },
                        [9446] = 
                        {
                            ["name"] = "Summer's Herald Torchnix",
                            ["hint"] = "",
                            ["id"] = 9446,
                            ["description"] = "Several theories circulate on the nature of the torchnix's light. Some scholars suggest the luminescence is a mating display, while others argue that it's a form of communication. Children in Ahemmusa tell each other the glow is bad food in the nix's gut.",
                            ["furnitureId"] = 7842,
                            ["icon"] = "/esoui/art/icons/mount_greentorchnix.dds",
                            ["category"] = "Arthropods",
                        },
                        [9445] = 
                        {
                            ["name"] = "Keptu Bear",
                            ["hint"] = "",
                            ["id"] = 9445,
                            ["description"] = "\"Long ago, during the annual Ket Keptu hunt, Tula the Skullcleaver and their bear Falk rose above the others in the amount of prey they killed for the shared larder. In celebration, Falk received these markings of Hircine's favor.\"—Fori, Keptu Scholar",
                            ["furnitureId"] = 7841,
                            ["icon"] = "/esoui/art/icons/mount_keptubear.dds",
                            ["category"] = "Ursines",
                        },
                        [9442] = 
                        {
                            ["name"] = "Larry, Duke of the Dance",
                            ["hint"] = "",
                            ["id"] = 9442,
                            ["description"] = "Granted to the winner of the 2020 Tamriel Together Sweepstakes. After adding Larry, Duke of the Dance to your home, you can set him on a path.",
                            ["furnitureId"] = 7840,
                            ["icon"] = "/esoui/art/icons/assistent_larry.dds",
