                        },
                        [10055] = 
                        {
                            ["name"] = "Ossified Rime Wolf",
                            ["hint"] = "",
                            ["id"] = 10055,
                            ["description"] = "\"Tears of rage and hatred don't go wasted in Skyrim. These rare droplets fall upon the snow, calling a spirit of bone and rime from Aetherius. Within seconds, a frost-spiked wolf forms, snarling and bridled with grim purpose.\"—Hef, Tale Collector",
                            ["furnitureId"] = 8186,
                            ["icon"] = "/esoui/art/icons/mount_icebonewolf.dds",
                            ["category"] = "Canines",
                        },
                        [10056] = 
                        {
                            ["name"] = "Reefstrider Ornaug",
                            ["hint"] = "",
                            ["id"] = 10056,
                            ["description"] = "Scales the color of High Isle's sky speckle this beast, making it highly sought after by nobles. When domesticated, the Reefstrider joyfully takes its rider across tidepools and shallows, but avoids the deeps—especially in northern climes.",
                            ["furnitureId"] = 8187,
                            ["icon"] = "/esoui/art/icons/mount_luminousseabeast.dds",
                            ["category"] = "Serpentes",
                        },
                        [10057] = 
                        {
                            ["name"] = "Forge Master's Charger",
                            ["hint"] = "",
                            ["id"] = 10057,
                            ["description"] = "Though some claim these fiery steeds first sprang from the Earth Forge, others make a case for the fires of Morkuldin's Descent taking that honor. None can quench the blaze of this incandescent horse!",
                            ["furnitureId"] = 8188,
                            ["icon"] = "/esoui/art/icons/mount_firebrandcharger.dds",
                            ["category"] = "Equines",
                        },
                        [10058] = 
                        {
                            ["name"] = "Ruby Fledgling Terror Bird",
                            ["hint"] = "",
                            ["id"] = 10058,
                            ["description"] = "With plumage as vibrant as the setting sun, these terror birds are often trained to parade around the halls of Rimmen. Nobles delight in the strangeness of their movements and the brilliance of their feathers.",
                            ["furnitureId"] = 8189,
                            ["icon"] = "/esoui/art/icons/pet_raspfirefledglingterrorbird.dds",
                            ["category"] = "Exotic",
                        },
                        [10059] = 
                        {
                            ["name"] = "Volkihar Death Hound",
                            ["hint"] = "",
                            ["id"] = 10059,
                            ["description"] = "Rarely do these inky black death hounds venture beyond Castle Volkihar—most serve their master's purpose at home better than abroad. The ones wandering after folk are probably some form of spy for the Volkihar vampires.—Nalana, Advisor to House Tamrith",
                            ["furnitureId"] = 8190,
                            ["icon"] = "/esoui/art/icons/pet_gloomfeardeathhound.dds",
                            ["category"] = "Exotic",
                        },
                        [10060] = 
                        {
                            ["name"] = "Heartland Butcher's Dog",
                            ["hint"] = "",
                            ["id"] = 10060,
                            ["description"] = "Families along the Niben River bred Butcher's dogs to protect their homesteads. The dogs earned their name generations later when the farmers realized they were more likely to watch the ribs and roasts than the front door.",
                            ["furnitureId"] = 8191,
                            ["icon"] = "/esoui/art/icons/pet_heartlandcartdog.dds",
                            ["category"] = "Domestic",
                        },
                        [8013] = 
                        {
                            ["name"] = "Sereyne",
                            ["hint"] = "",
                            ["id"] = 8013,
                            ["description"] = "An outlaw with a talent for magic but a thirst for alcohol, Sereyne wants a cozy place to drink her troubles away. Perhaps you can provide? After adding Sereyne to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 6773,
                            ["icon"] = "/esoui/art/icons/assistant_sereyne.dds",
                            ["category"] = "Houseguests",
                        },
                        [10062] = 
                        {
                            ["name"] = "Baysong Quasigriff",
                            ["hint"] = "",
                            ["id"] = 10062,
                            ["description"] = "Unlike their mainland cousins, the quasigriffs of the Systres Archipelago have vibrant, sea-tinted feathers. Admittedly, Irastimil Direnni never intended to create such colorful creatures. Noble Bretons adore them and travel about High Isle on their backs.",
                            ["furnitureId"] = 8193,
                            ["icon"] = "/esoui/art/icons/mount_seagloamquasigriff.dds",
                            ["category"] = "Heavyweights",
                        },
                        [5244] = 
                        {
                            ["name"] = "Goldenback Spider Lackey",
                            ["hint"] = "",
                            ["id"] = 5244,
                            ["description"] = "For most people, giant spiders are just loathsome monsters to be destroyed by fire and steel, but Mephala Cultists know that they're highly intelligent (for, you know, arthropods) and surprisingly trainable. The Goldenbacks are by far the friendliest.",
                            ["furnitureId"] = 5437,
                            ["icon"] = "/esoui/art/icons/pet_196_giantspider-goldenback.dds",
                            ["category"] = "Exotic",
                        },
                        [8016] = 
                        {
                            ["name"] = "Lambent Shadowmane Courser",
                            ["hint"] = "",
                            ["id"] = 8016,
                            ["description"] = "\"Imbued with the spirits of those turned away from Sovngarde, this dark courser emanates tendrils and spines of those lost souls. Dare you walk with it along its path of shadows and regret, taking on some of its burden?\"—Clever Woman Moritra",
                            ["furnitureId"] = 6774,
                            ["icon"] = "/esoui/art/icons/mount_radiantsovngardehorse.dds",
                            ["category"] = "Equines",
                        },
                        [8017] = 
                        {
                            ["name"] = "Auric Sabre Cat Duskstalker",
                            ["hint"] = "",
                            ["id"] = 8017,
                            ["description"] = "\"Duskstalkers hunt and gather tormented battlefield ghosts, providing these lost souls a safe haven until they willingly leave. They can be seen as wisps, whose colorful auras emanate around both the sabre cat and its rider.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6775,
                            ["icon"] = "/esoui/art/icons/mount_radgoldensteedsenche.dds",
                            ["category"] = "Felines",
                        },
                        [5248] = 
                        {
                            ["name"] = "Hollowjack Rider Guar",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5248,
                            ["description"] = "The legend of Jaque o' the Hollow has spread even to the misty realms of eastern Tamriel where the Guar roam the woods and marshes, and during the dark nights of the Witches Festival reptile-riders may also find themselves haunted and headless!",
                            ["furnitureId"] = 5525,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_hollowjackv2.dds",
                            ["category"] = "Bipedals",
                        },
                        [5251] = 
                        {
                            ["name"] = "Hollowjack Wraith-Lantern Steed",
                            ["hint"] = "|cFFFFFFHead removal not supported for companions or players with a Polymorph applied.|r",
                            ["id"] = 5251,
                            ["description"] = "Conventional wisdom holds that these bizarre and eerie Skull mounts are just horses imbued with a haunting illusory appearance—but some whisper that they aren't from Tamriel at all, but summoned from the Hollowjack half-world or demiplane.",
                            ["furnitureId"] = 5528,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_hollowjack_apex.dds",
                            ["category"] = "Equines",
                        },
                        [9386] = 
                        {
                            ["name"] = "Mnemoflare Kagouti Fabricant",
                            ["hint"] = "",
                            ["id"] = 9386,
                            ["description"] = "\"Clockwork fabricants possess keen intelligence, but their characters remain blank slates. Rumor has it that the Astronomer can import a dissected beast's memories directly into a fabricant's animo core, making for an enlightened mount.\"—Uleni Silarys",
                            ["furnitureId"] = 7660,
                            ["icon"] = "/esoui/art/icons/mount_mnemoflarekagout.dds",
                            ["category"] = "Bipedals",
                        },
                        [150] = 
                        {
                            ["name"] = "Imperial War Mastiff",
                            ["hint"] = "",
                            ["id"] = 150,
                            ["description"] = "Mastiffs are the most common breed used by the Imperial Legions as battle dogs. The Imperial War Mastiff in particular is the mascot and symbol of the storied Second Legion, headquartered in peacetime in the vicinity of Bruma.",
                            ["furnitureId"] = 4205,
                            ["icon"] = "/esoui/art/icons/pet_130.dds",
                            ["category"] = "Domestic",
                        },
                        [1185] = 
                        {
                            ["name"] = "Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 1185,
                            ["description"] = "Of all the Dwemer animunculi, the Dwarven Spider is perhaps the most familiar and iconic. This versatile construct comes in several variations, and it should come as no surprise that one of them is a vamidium, or mechanical mount. Clankin'!",
                            ["furnitureId"] = 4391,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvenspider_a.dds",
                            ["category"] = "Constructs",
                        },
                        [1186] = 
                        {
                            ["name"] = "Chroma-Blue Dwarven Spider",
                            ["hint"] = "",
                            ["id"] = 1186,
                            ["description"] = "Rarest of all Dwarven Spider vamidiums are those powered by gems that emit a cold blue light, said to reflect the frigid stolen soul of the Dwemer engineer trapped within it.",
                            ["furnitureId"] = 4392,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvenspider_b.dds",
                            ["category"] = "Constructs",
                        },
                        [8024] = 
                        {
                            ["name"] = "Silver Nimbus Wolf",
                            ["hint"] = "",
                            ["id"] = 8024,
                            ["description"] = "\"Those who give up hope, dying from heartbreak or other such ailments of the spirit, find a kind companion in this wolf. Until they gain peace, these beings sheathe both wolf and rider in colorful mists and jagged spikes.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6776,
                            ["icon"] = "/esoui/art/icons/mount_radgoldensteedwolf.dds",
                            ["category"] = "Canines",
                        },
                        [8025] = 
                        {
                            ["name"] = "Khefrem Senche-Serval",
                            ["hint"] = "",
                            ["id"] = 8025,
                            ["description"] = "To those living in Hew's Bane, seeing a spotted senche-serval is an omen of good luck. Some, hoping to gain a constant supply of good fortune, captured and trained several cubs. Now they serve as mounts—good luck indeed to those so blessed with one!",
                            ["furnitureId"] = 6777,
                            ["icon"] = "/esoui/art/icons/catlargemount_servalvariant.dds",
                            ["category"] = "Felines",
                        },
                        [8026] = 
                        {
                            ["name"] = "Whiterun Mountain Charger",
                            ["hint"] = "",
                            ["id"] = 8026,
                            ["description"] = "With barding featuring Whiterun's heraldry, this indomitable horse remains sure-footed in the snowy mountains of Skyrim and beyond. Majestic!",
                            ["furnitureId"] = 6778,
                            ["icon"] = "/esoui/art/icons/mount_whiterunclydesdale.dds",
                            ["category"] = "Equines",
                        },
                        [8027] = 
                        {
                            ["name"] = "Auroran Penumbra Wolf",
                            ["hint"] = "",
                            ["id"] = 8027,
                            ["description"] = "This wolf of light was born out of fierce devotion, and it tirelessly seeks a rider whose soul burns brightly for Meridia, the Lady of Infinite Energies. Will it be drawn to your inner light?",
                            ["furnitureId"] = 6779,
                            ["icon"] = "/esoui/art/icons/mount_blackauroranwolf.dds",
                            ["category"] = "Canines",
                        },
                        [8028] = 
                        {
                            ["name"] = "Frostborn Durzog Mangler",
                            ["hint"] = "",
                            ["id"] = 8028,
                            ["description"] = "The magic of the Icereach Coven shapes these striped durzogs in the womb, and handlers train the pups to the saddle. To transfer loyalty to a new rider, that rider should sleep with the saddle for a few days before attempting to mount the durzog.",
                            ["furnitureId"] = 6780,
                            ["icon"] = "/esoui/art/icons/mount_durzog.dds",
                            ["category"] = "Canines",
                        },
                        [8029] = 
                        {
                            ["name"] = "Energetic Dwarven Shock-Spider",
                            ["hint"] = "Acquired by earning the \"Stonethorn Explorer\" achievement.",
                            ["id"] = 8029,
                            ["description"] = "Sparks fly with this dwarven spider! Light up your life by taking this automaton for a lively jaunt around town. It'll follow over any terrain, happily zapping away!",
                            ["furnitureId"] = 6781,
                            ["icon"] = "/esoui/art/icons/pet_alchemistdwarvenspider.dds",
                            ["category"] = "Exotic",
                        },
                        [8030] = 
                        {
                            ["name"] = "Firepoint Fledgling Gryphon",
                            ["hint"] = "",
                            ["id"] = 8030,
                            ["description"] = "Dramatic coloration marks this gryphon as one originally bred by Khajiit in Elsweyr. Due to some \"incidents,\" the unfortunate breeders sold their stock, making them available to fine folk such as you!",
                            ["furnitureId"] = 6782,
                            ["icon"] = "/esoui/art/icons/pet_autumngryphon.dds",
                            ["category"] = "Exotic",
                        },
                        [8031] = 
                        {
                            ["name"] = "Nightmare Firestalker Cub",
                            ["hint"] = "",
                            ["id"] = 8031,
                            ["description"] = "Some may find the fiery cuteness of this horned cub unbearable, but you can handle it! Just watch out for those adorable little paws—they're hot as coals.",
                            ["furnitureId"] = 6783,
                            ["icon"] = "/esoui/art/icons/pet_daemoncat3.dds",
                            ["category"] = "Exotic",
                        },
                        [8032] = 
                        {
                            ["name"] = "Frostshriek Imp",
                            ["hint"] = "",
                            ["id"] = 8032,
                            ["description"] = "\"This devious little creature will drop the ambient temperature considerably when summoned. And mind your fingers—the little monster likes nothing better than to freeze them, break them off, and pop them into its mouth!\"—Divayth Fyr",
                            ["furnitureId"] = 6784,
                            ["icon"] = "/esoui/art/icons/pet_frozenimp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [8033] = 
                        {
                            ["name"] = "Springlight Moth",
                            ["hint"] = "",
                            ["id"] = 8033,
                            ["description"] = "Originally from the Tenmar Jungle, these green moths spread via caravans and carry the scent of fresh spring rains with every flap of their wings.",
                            ["furnitureId"] = 6785,
                            ["icon"] = "/esoui/art/icons/pet_lunarmothvar1.dds",
                            ["category"] = "Flying Pets",
                        },
                        [8034] = 
                        {
                            ["name"] = "Graywinter Sabre Cat Cub",
                            ["hint"] = "",
                            ["id"] = 8034,
                            ["description"] = "Though adorable, even as cubs these sabre cats seek out trolls in the White River region, hoping to nip at their flesh and bring them down by sheer force of numbers. Luckily for you, you're not a troll! Also, we mentioned they're adorable, yes?",
                            ["furnitureId"] = 6786,
                            ["icon"] = "/esoui/art/icons/pet_skyrimsabercat.dds",
                            ["category"] = "Exotic",
                        },
                        [8035] = 
                        {
                            ["name"] = "Sovngarde Bear Cub",
                            ["hint"] = "",
                            ["id"] = 8035,
                            ["description"] = "\"Potential. Bear cubs from Sovngarde sense it and follow those who have it—all the way back to Sovngarde. While here, they make for sometimes silly companions.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6787,
                            ["icon"] = "/esoui/art/icons/pet_sovngardebearcub.dds",
                            ["category"] = "Exotic",
                        },
                        [8036] = 
                        {
                            ["name"] = "Sovngarde Pony Guar",
                            ["hint"] = "",
                            ["id"] = 8036,
                            ["description"] = "\"You may laugh at the idea of a pony guar from Sovngarde, but they exist. In fact, one showed up around here, but it chose to follow a worthy traveler. Or perhaps one freer with cuddles than I am.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6788,
                            ["icon"] = "/esoui/art/icons/pet_sovngardeguarcalf.dds",
                            ["category"] = "Exotic",
                        },
                        [8037] = 
                        {
                            ["name"] = "Sovngarde Pony",
                            ["hint"] = "",
                            ["id"] = 8037,
                            ["description"] = "\"Noble ponies trot forth from Sovngarde, seeking those who have made oaths, knowingly or not. Curiosity prompts them to follow an oathmaker to see how they fulfill their promise. If one follows you, give it an apple. They love them.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6789,
                            ["icon"] = "/esoui/art/icons/pet_sovngardepony.dds",
                            ["category"] = "Exotic",
                        },
                        [8038] = 
                        {
                            ["name"] = "Sovngarde Sabre Cat Cub",
                            ["hint"] = "",
                            ["id"] = 8038,
                            ["description"] = "\"Sabre cat cubs from Sovngarde might play with string, but it's not visiting us for such trifles. Instead, they serve as the eyes and ears of Sovngarde, allowing them watch our world—while sometimes getting tangled in yarn.\"—Clever Woman Moritra",
                            ["furnitureId"] = 6790,
                            ["icon"] = "/esoui/art/icons/pet_sovngardesabercatcub.dds",
                            ["category"] = "Exotic",
                        },
                        [8039] = 
                        {
                            ["name"] = "Sovngarde Wolf Pup",
                            ["hint"] = "",
                            ["id"] = 8039,
                            ["description"] = "\"Wolf cubs from the Hall of Valor tumble into our world, ready to help catalogue knowledge for their masters. They particularly love to howl along to skalds and bards, but they'll join up with anyone who travels widely. \"—Clever Woman Moritra",
                            ["furnitureId"] = 6791,
                            ["icon"] = "/esoui/art/icons/pet_sovngardewolfpup.dds",
                            ["category"] = "Exotic",
                        },
                        [8040] = 
                        {
                            ["name"] = "Amaranthine Pocket Watcher",
                            ["hint"] = "",
                            ["id"] = 8040,
                            ["description"] = "\"My notes indicate these vibrantly hued watchers once inhabited the ruins of Zaintiraris until an unfortunate explorer set them free. Given their color and origin, I suspect Sheogorath holds some sway over them. Also unfortunate.\"—Warlock Aldaale",
                            ["furnitureId"] = 6792,
                            ["icon"] = "/esoui/art/icons/pet_watchervariant.dds",
                            ["category"] = "Flying Pets",
                        },
                        [8041] = 
                        {
                            ["name"] = "Snowsnarl Durzog",
                            ["hint"] = "",
                            ["id"] = 8041,
                            ["description"] = "Born with a snarl, these striped durzogs tend to bite the hand that feeds them—but only gently after they get to know you.",
                            ["furnitureId"] = 6793,
                            ["icon"] = "/esoui/art/icons/pet_wrothgardurzog.dds",
                            ["category"] = "Exotic",
                        },
                        [1187] = 
                        {
                            ["name"] = "Kagouti Fabricant",
                            ["hint"] = "",
                            ["id"] = 1187,
                            ["description"] = "Wheeled constructs and fabricants do just fine in most regions of the Clockwork City, but for traversing rough synthetic terrain, Seht's Apostles prefer the tough and capable Kagouti Fabricant mount.",
                            ["furnitureId"] = 4393,
                            ["icon"] = "/esoui/art/icons/mounticon_khagoutifabricant_a.dds",
                            ["category"] = "Bipedals",
                        },
                        [1188] = 
                        {
                            ["name"] = "Pellitine Mustang",
                            ["hint"] = "",
                            ["id"] = 1188,
                            ["description"] = "The small equines of the subtropical Pellitine forests have subtle vertical stripes for camouflage under the canopy. They've been crossed with the larger Anequine Mustang to create a striking striped mount, the favorite of the First Corinthe Hussars.",
                            ["furnitureId"] = 4394,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_q.dds",
                            ["category"] = "Equines",
                        },
                        [1189] = 
                        {
                            ["name"] = "Adamant Dwarven Horse",
                            ["hint"] = "",
                            ["id"] = 1189,
                            ["description"] = "Though Dwemer constructs are made mostly of so-called Dwarven Metal, some rare animunculi have parts forged from a super-hard whitish alloy known to blacksmiths as Dwarven Adamant. It's one of the rarest materials on Nirn.",
                            ["furnitureId"] = 4395,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_horse_d.dds",
                            ["category"] = "Equines",
                        },
                        [1190] = 
                        {
                            ["name"] = "Adamant Dwarven Senche",
                            ["hint"] = "",
                            ["id"] = 1190,
                            ["description"] = "There have long been unconfirmed reports of Dwarven Senche vamidiums with key parts made of the extremely rare and super-hard Dwarven Adamant metal. At long last, these reports have been substantiated.",
                            ["furnitureId"] = 4396,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_adament_senche.dds",
                            ["category"] = "Felines",
                        },
                        [1191] = 
                        {
                            ["name"] = "Adamant Dwarven Wolf",
                            ["hint"] = "",
                            ["id"] = 1191,
                            ["description"] = "The shining metal known as Dwarven Adamant is an alloy melding ores of unknown origin into the most durable material ever made. Though found in parts of the ultra-rare Adamant Dwarven Wolf, the secret of its forging seems as lost as the Dwemer themselves.",
                            ["furnitureId"] = 4397,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_adament_wolf.dds",
                            ["category"] = "Canines",
                        },
                        [191] = 
                        {
                            ["name"] = "Cave Bear Cub",
                            ["hint"] = "",
                            ["id"] = 191,
                            ["description"] = "The Cave Bear Cub may miss its mountain home, but that just makes it twice as loyal to its mortal companion.",
                            ["furnitureId"] = 4223,
                            ["icon"] = "/esoui/art/icons/pet_045.dds",
                            ["category"] = "Exotic",
                        },
                        [1127] = 
                        {
                            ["name"] = "Bust: Sellistrix the Lamia Queen",
                            ["hint"] = "Awarded for completing Veteran Arx Corinium.",
                            ["id"] = 1127,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Arx Corinium.",
                            ["furnitureId"] = 4350,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranlamia001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [1128] = 
                        {
                            ["name"] = "Bust: Infernal Guardian",
                            ["hint"] = "Awarded for completing Veteran City of Ash I.",
                            ["id"] = 1128,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in City of Ash I.",
                            ["furnitureId"] = 4351,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranlurcher001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [1129] = 
                        {
                            ["name"] = "Bust: Molag Kena",
                            ["hint"] = "Awarded for completing Veteran White-Gold Tower.",
                            ["id"] = 1129,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in White-Gold Tower.",
                            ["furnitureId"] = 4352,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranmolagkena001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [232] = 
                        {
                            ["name"] = "Moonlight Senche-Tiger",
                            ["hint"] = "",
                            ["id"] = 232,
                            ["description"] = "The Moonlight Senche-Tigers have been the sleek and silvery guardians of the Khajiiti temples of the moons ever since the revelation of the Riddle'Thar.",
                            ["furnitureId"] = 4230,
                            ["icon"] = "/esoui/art/icons/pet_049.dds",
                            ["category"] = "Exotic",
                        },
                        [234] = 
                        {
                            ["name"] = "Zeht's Cloud Camel",
                            ["hint"] = "",
                            ["id"] = 234,
                            ["description"] = "The white camel is said to be sacred to Zeht, the Redguard god of food and farming. The devout folk of Hammerfell bow when a Cloud Camel rides past.",
                            ["furnitureId"] = 4232,
                            ["icon"] = "/esoui/art/icons/mounticon_camel_b.dds",
                            ["category"] = "Camelids",
                        },
                        [266] = 
                        {
                            ["name"] = "Skeletal Camel",
                            ["hint"] = "",
                            ["id"] = 266,
                            ["description"] = "The Redguard hatred of necromancy means undead creatures are rare in Hammerfell—which will make you all the more special when you clatter into the oasis on the back of a terrifying Skeletal Camel!",
                            ["furnitureId"] = 4243,
                            ["icon"] = "/esoui/art/icons/mounticon_skeletalcamel_a.dds",
                            ["category"] = "Camelids",
                        },
                        [267] = 
                        {
                            ["name"] = "Tythis Andromo, the Banker",
                            ["hint"] = "",
                            ["id"] = 267,
                            ["description"] = "This aristocratic banker is on hand whenever he's needed, available for all personal banking services—except in Cyrodiil or Battlegrounds, which are far too dangerous for this fellow.\n\nWhen summoned, his services can be used by you and your groupmates.",
                            ["furnitureId"] = 4244,
                            ["icon"] = "/esoui/art/icons/assistant_banker_01.dds",
                            ["category"] = "Assistants",
                        },
                        [269] = 
                        {
                            ["name"] = "Turquoise Nixad",
                            ["hint"] = "",
                            ["id"] = 269,
                            ["description"] = "Scholars think the iridescent blue Turquoise Nixad must have inherent magical properties, because those wings certainly aren't big enough to enable it to fly. Yet fly it does, flitting about like a beautiful human-shaped hummingbird moth.",
                            ["furnitureId"] = 4246,
                            ["icon"] = "/esoui/art/icons/pet_058.dds",
                            ["category"] = "Flying Pets",
                        },
                        [270] = 
                        {
                            ["name"] = "Orchid Nixad",
                            ["hint"] = "",
                            ["id"] = 270,
                            ["description"] = "The rarest of these fay creatures is the Orchid Nixad, said to be sacred to the goddess Dibella, and found only in wild places hallowed to her worship. It's known that the Empress Tavia had an Orchid Nixad as a friend and companion.",
                            ["furnitureId"] = 4247,
                            ["icon"] = "/esoui/art/icons/pet_057.dds",
                            ["category"] = "Flying Pets",
                        },
                        [1157] = 
                        {
                            ["name"] = "Snow Leopard Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 1157,
                            ["description"] = "The shamans of the Skaal tribe domesticated the Snow Leopard Sabres as mounts, but to keep them exclusive their breeding was restricted, and they are down to a dwindling few.\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["furnitureId"] = 4377,
                            ["icon"] = "/esoui/art/icons/mount_senche_m.dds",
                            ["category"] = "Felines",
                        },
                        [290] = 
                        {
                            ["name"] = "Highland Wolf",
                            ["hint"] = "",
                            ["id"] = 290,
                            ["description"] = "The brown Highland Wolf is common in the Colovian hills and in Cyrodiil's Great Forest, where wild packs are feared by farmers and shepherds. But foresters have domesticated the beasts and, bred for size, use them as mounts.",
                            ["furnitureId"] = 4248,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_a.dds",
                            ["category"] = "Canines",
                        },
                        [291] = 
                        {
                            ["name"] = "Doom Wolf",
                            ["hint"] = "",
                            ["id"] = 291,
                            ["description"] = "Bred for size and savagery from the fierce timber wolves of the southern Jerall Mountains, the Doom Wolf has been adopted as the mount of choice by the secretive and deadly Dark Brotherhood.",
                            ["furnitureId"] = 4249,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_d.dds",
                            ["category"] = "Canines",
                        },
                        [292] = 
                        {
                            ["name"] = "Ice Wolf",
                            ["hint"] = "",
                            ["id"] = 292,
                            ["description"] = "The Ice Wolf of the far north can grow to tremendous size—which is probably why the Nords of Hjaalmarch decided to ride them. Domesticating giant Ice Wolves wasn't an easy task, but it's just the kind of challenge a Nord loves.",
                            ["furnitureId"] = 4250,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_b.dds",
                            ["category"] = "Canines",
                        },
                        [6013] = 
                        {
                            ["name"] = "Bust: Drakeeh the Unchained",
                            ["hint"] = "Awarded for completing Veteran Blackrose Prison.",
                            ["id"] = 6013,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Blackrose Prison.",
                            ["furnitureId"] = 5832,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterandrakeeh001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [6014] = 
                        {
                            ["name"] = "Trophy: Drakeeh the Unchained",
                            ["hint"] = "Awarded for completing Blackrose Prison.",
                            ["id"] = 6014,
                            ["description"] = "Trophy taken from Drakeeh the Unchained in honor of an Undaunted victory in Blackrose Prison.",
                            ["furnitureId"] = 5833,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophydrakeeh001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [293] = 
                        {
                            ["name"] = "Wild Hunt Horse",
                            ["hint"] = "",
                            ["id"] = 293,
                            ["description"] = "When the Wood Elves invoke the Wild Hunt, creatures forget their Y'ffre-taught shapes and shift into unnatural forms. Such are the Wild Hunt Horses, mounts that occupy a space between flora and fauna.",
                            ["furnitureId"] = 4251,
                            ["icon"] = "/esoui/art/icons/mounticon_wildhunthorse_a.dds",
                            ["category"] = "Equines",
                        },
                        [295] = 
                        {
                            ["name"] = "Wild Hunt Senche",
                            ["hint"] = "",
                            ["id"] = 295,
                            ["description"] = "The Wild Hunt unravels the shapes Y'ffre established for creatures in the Dawn Era, transforming them into monstrous but vigorous hybrid beasts. Among these, both beautiful and abhorrent, is the Wild Hunt Senche-Mount.",
                            ["furnitureId"] = 4253,
                            ["icon"] = "/esoui/art/icons/mounticon_wildhuntsenche_a.dds",
                            ["category"] = "Felines",
                        },
                        [296] = 
                        {
                            ["name"] = "Wild Hunt Bear",
                            ["hint"] = "",
                            ["id"] = 296,
                            ["description"] = "The Wild Hunt Bear is a forest beast that has lost its Y'ffre-given ability to choose between being plant or animal, reverting to the primal chaos of the Dawn Era.",
                            ["furnitureId"] = 4254,
                            ["icon"] = "/esoui/art/icons/mountiocn_wildhuntbear_a.dds",
                            ["category"] = "Ursines",
                        },
                        [6018] = 
                        {
                            ["name"] = "Rihad Coffee Scorpion",
                            ["hint"] = "",
                            ["id"] = 6018,
                            ["description"] = "The Coffee Scorpion gets its name from the way they like their kaveh in Rihad: strong, dark, and sweet. (Well, I guess two out of three isn't bad.)",
                            ["furnitureId"] = 5863,
                            ["icon"] = "/esoui/art/icons/pet_243_coffeescorpion.dds",
                            ["category"] = "Exotic",
                        },
                        [297] = 
                        {
                            ["name"] = "Wild Hunt Camel",
                            ["hint"] = "",
                            ["id"] = 297,
                            ["description"] = "Y'ffre's Naming gave all the creatures of Nirn their shapes, even in the arid deserts of Tamriel. When its name comes magically unraveled, then a creature begins to forget its shape and devolve to a state between flora and fauna. Thus the Wild Hunt Camel.",
                            ["furnitureId"] = 4255,
                            ["icon"] = "/esoui/art/icons/mounticon_wildhuntcamel_a.dds",
                            ["category"] = "Camelids",
                        },
                        [298] = 
                        {
                            ["name"] = "Wild Hunt Wolf",
                            ["hint"] = "",
                            ["id"] = 298,
                            ["description"] = "Some say that Hircine meddled with the nature of wolves in a way that made them susceptible to shape-shifting, and from this Daedric interference came both the Werewolf—and the Wild Hunt Wolf. What is the truth of this? Y'ffre knows!",
                            ["furnitureId"] = 4256,
                            ["icon"] = "/esoui/art/icons/mounticon_wildhuntwolf_a.dds",
                            ["category"] = "Canines",
                        },
                        [299] = 
                        {
                            ["name"] = "Skeletal Wolf",
                            ["hint"] = "",
                            ["id"] = 299,
                            ["description"] = "It's said that when King Styriche, the Vampire of Verkarth, led his Gray Host west to Bangkorai, his terrible Zombie Hussars were mounted on a great pack of Skeletal Wolves. Some escaped the massacre of the Gray Host, and survived to haunt the wastes.",
                            ["furnitureId"] = 4257,
                            ["icon"] = "/esoui/art/icons/mounticon_skeletalwolf_a.dds",
                            ["category"] = "Canines",
                        },
                        [300] = 
                        {
                            ["name"] = "Pirharri the Smuggler",
                            ["hint"] = "Acquired by completing the Thieves Guild questline.",
                            ["id"] = 300,
                            ["description"] = "This Baandari Pedlar is on hand whenever she's needed (except in Cyrodiil and Battlegrounds), and will fence any of your goods for you—but she'll take a cut of the profits.\n\nWhen summoned, her services can only be used by you.",
                            ["furnitureId"] = 4258,
                            ["icon"] = "/esoui/art/icons/assistant_fence_01.dds",
                            ["category"] = "Assistants",
                        },
                        [301] = 
                        {
                            ["name"] = "Nuzhimeh the Merchant",
                            ["hint"] = "",
                            ["id"] = 301,
                            ["description"] = "This alert merchant is on hand whenever she's needed, and will buy any non-stolen goods you or your group offer her. She won't come to Cyrodiil or Battlegrounds, though—too dangerous.\n\nWhen summoned, her services can be used by you and your groupmates.",
                            ["furnitureId"] = 4259,
                            ["icon"] = "/esoui/art/icons/assistant_vendor_01.dds",
                            ["category"] = "Assistants",
                        },
                        [303] = 
                        {
                            ["name"] = "Sabre Leopard Cub",
                            ["hint"] = "",
                            ["id"] = 303,
                            ["description"] = "\"For the Mages Guild, I devised an enchanted 'appealometer' that measures creatures' adorableness,\" says Researcher Neotenus. \"After tests on other pets, I tried to take a reading on a Sabre Snow Leopard Cub, but the device overloaded and shattered.\"",
                            ["furnitureId"] = 4261,
                            ["icon"] = "/esoui/art/icons/pet_135.dds",
                            ["category"] = "Exotic",
                        },
                        [304] = 
                        {
                            ["name"] = "Alliance War Dog",
                            ["hint"] = "",
                            ["id"] = 304,
                            ["description"] = "War Dogs can be found in the armies of all three Alliances, mainly in the capacity of aides to the military police. They are as loyal to their masters as they are savage to their enemies.\n\n|cFFFFFF(Appearance is specific to your character's alliance.)",
                            ["furnitureId"] = 4262,
                            ["icon"] = "/esoui/art/icons/pet_086.dds",
                            ["category"] = "Domestic",
                        },
                        [305] = 
                        {
                            ["name"] = "Black Mane Lion",
                            ["hint"] = "",
                            ["id"] = 305,
                            ["description"] = "At the Palace of the Mane near Torval, by tradition the Bi-Lunar Guard are all mounted on matching Black Mane Lions, which are reserved for them alone. So be wary if you ride your Black Mane near Torval, lest you anger the Bi-Lunars!",
                            ["furnitureId"] = 4263,
                            ["icon"] = "/esoui/art/icons/mount_senche_i.dds",
                            ["category"] = "Felines",
                        },
                        [8075] = 
                        {
                            ["name"] = "Statuette: Nocturnal, Gloamqueen",
                            ["hint"] = "",
                            ["id"] = 8075,
                            ["description"] = "A miniature statue of the Daedric Prince Nocturnal, the Night Mistress.",
                            ["furnitureId"] = 6819,
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_nocturnalstatuesmall001.dds",
                            ["category"] = "General",
                        },
                        [8076] = 
                        {
                            ["name"] = "Statuette: Trinimac, Paragon",
                            ["hint"] = "",
                            ["id"] = 8076,
                            ["description"] = "A miniature statue of the divine warrior Trinimac, holding aloft a sword.",
                            ["furnitureId"] = 6820,
                            ["icon"] = "/esoui/art/icons/housing_dae_exc_trinimacstatuesmall001.dds",
                            ["category"] = "General",
                        },
                        [8077] = 
                        {
                            ["name"] = "Statuette: Revered Night Mother",
                            ["hint"] = "",
                            ["id"] = 8077,
                            ["description"] = "A miniature statue of the Night Mother, worshiped by the Dark Brotherhood.",
                            ["furnitureId"] = 6821,
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_dbhnightmotherstatuesmall001.dds",
                            ["category"] = "General",
                        },
                        [314] = 
                        {
                            ["name"] = "Hearthfire Kagouti",
                            ["hint"] = "",
                            ["id"] = 314,
                            ["description"] = "The Hearthfire Kagouti appears to be a sort of magical hybrid, a wizard's experimental melding of a carnivorous reptile and a flame atronach. The fact that they were first sighted in the Telvanni Grazelands lends this theory some credence.",
                            ["furnitureId"] = 4265,
                            ["icon"] = "/esoui/art/icons/mounticon_kagouti_b.dds",
                            ["category"] = "Bipedals",
                        },
                        [6459] = 
                        {
                            ["name"] = "Oak-Ember Forge Wolf",
                            ["hint"] = "",
                            ["id"] = 6459,
                            ["description"] = "A young blacksmith raised a foundling wolf decades ago, thus training the first of the Oak-Ember Forge Wolves as a steed. With its unusual fur pattern, you're sure to make an impression on those around you.",
                            ["furnitureId"] = 6006,
                            ["icon"] = "/esoui/art/icons/pet_oakemberforgewolf.dds",
                            ["category"] = "Canines",
                        },
                        [6032] = 
                        {
                            ["name"] = "Gloam Wolf",
                            ["hint"] = "",
                            ["id"] = 6032,
                            ["description"] = "The uncanny Gloam Wolf hails from the Oblivion plane of the Daedric Prince Nocturnal. Sometimes, the Night Mistress will reward a loyal Tamrielic worshiper with a Gloam Wolf Mount sent permanently to Nirn.",
                            ["furnitureId"] = 5872,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_nocturnal.dds",
                            ["category"] = "Canines",
                        },
                        [6033] = 
                        {
                            ["name"] = "Egg Hunter's Horse",
                            ["hint"] = "",
                            ["id"] = 6033,
                            ["description"] = "The many multicolored eggs of Tamriel are valuable for their differing alchemical properties, and this makes the Egg Hunter's job a profitable one, especially in the spring.",
                            ["furnitureId"] = 5953,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_easter.dds",
                            ["category"] = "Equines",
                        },
                        [6034] = 
                        {
                            ["name"] = "Gloam Wolf Cub",
                            ["hint"] = "",
                            ["id"] = 6034,
                            ["description"] = "Hailing from Nocturnal's Oblivion realm of Evergloam, the Gloam Wolf Cub seems to oscillate like an optical illusion between adorable and sinister.",
                            ["furnitureId"] = 5865,
                            ["icon"] = "/esoui/art/icons/pet_246_nocturnalpup.dds",
                            ["category"] = "Exotic",
                        },
                        [6035] = 
                        {
                            ["name"] = "Ghostly Housecat",
                            ["hint"] = "",
                            ["id"] = 6035,
                            ["description"] = "According to Nibenese legend, a house where its owner was murdered will be haunted by the shade of their cat, sent from beyond by Lord Hollowjack to torment the killer with eternal shame and guilt.",
                            ["furnitureId"] = 5864,
                            ["icon"] = "/esoui/art/icons/pet_241_ghostcat.dds",
                            ["category"] = "Exotic",
                        },
                        [6036] = 
                        {
                            ["name"] = "Eerie Elk of Dread",
                            ["hint"] = "",
                            ["id"] = 6036,
                            ["description"] = "Is this ghostly Elk an antlered mount from the spirit world, or is it a sending from Lord Hircine's Oblivion plane of the Hunting Grounds? It seems solid enough, and doesn't disappear in broad daylight, so it must be more than just a haunt!",
                            ["furnitureId"] = 5873,
                            ["icon"] = "/esoui/art/icons/mounticon_elk_ghost.dds",
                            ["category"] = "Cervines",
                        },
                        [6037] = 
                        {
                            ["name"] = "Fledgling Vulture Gryphon",
                            ["hint"] = "",
                            ["id"] = 6037,
                            ["description"] = "Unlike most Gryphons, which catch live prey, the Vulture Gryphons subsist primarily on carrion. But they're still majestic, and their young Fledglings still make adorable pets!",
                            ["furnitureId"] = 5871,
                            ["icon"] = "/esoui/art/icons/pet_249_vulturegryphon.dds",
                            ["category"] = "Exotic",
                        },
                        [6460] = 
                        {
                            ["name"] = "Graysmoke Forge Bear",
                            ["hint"] = "",
                            ["id"] = 6460,
                            ["description"] = "In honor of a fallen Warden, a Wayrest blacksmith continues to breed and sell these bears as mounts today. If you happen to notice a Warden watching you as you ride this steed, consider thanking her. She may be the fallen Warden's shade!",
                            ["furnitureId"] = 6007,
                            ["icon"] = "/esoui/art/icons/mount_greysmokeforgebear.dds",
                            ["category"] = "Ursines",
                        },
                        [6461] = 
                        {
                            ["name"] = "Coalsmoke Forge Horse",
                            ["hint"] = "",
                            ["id"] = 6461,
                            ["description"] = "Originally bred by a family of Breton blacksmiths, the Coalsmoke Forge Horse's strength allows them to work for long hours. Just make sure you provide them with a salt lick—they love them.",
                            ["furnitureId"] = 6008,
                            ["icon"] = "/esoui/art/icons/mount_coalsmokeforgehorse-.dds",
                            ["category"] = "Equines",
                        },
                        [8088] = 
                        {
                            ["name"] = "Akaviri Potentate Wolf",
                            ["hint"] = "",
                            ["id"] = 8088,
                            ["description"] = "\"Placing the Potentate wolves in High Rock in 2E 4 seems off to me, but I find no texts disputing Mirannah of Gwylim's notes. 'Caused a panic in Shornhelm'—well, these wolves with their horned barding look menacing. Perhaps.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 6822,
                            ["icon"] = "/esoui/art/icons/mount_potentatewolf.dds",
                            ["category"] = "Canines",
                        },
                        [8089] = 
                        {
                            ["name"] = "Akaviri Potentate Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 8089,
                            ["description"] = "\"Mirannah of Gwylim writes 'the Potentate sabre cat mounted regiment combed Skyrim for Reman loyalists in 2E 7'—potentially accurate. But I think she meant 'killed Solitude's wolves using magical roars' to be local myth.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 6823,
                            ["icon"] = "/esoui/art/icons/mount_potentatesabercat.dds",
                            ["category"] = "Felines",
                        },
                        [8090] = 
                        {
                            ["name"] = "Akaviri Potentate Charger",
                            ["hint"] = "",
                            ["id"] = 8090,
                            ["description"] = "\"Label your fact from fiction, Mirannah! 'The barding on Potentate horses shimmers due to a geas of loyalty Versidue-Shaie instilled in the materials.' No. It's simply magic. But 2E 5 for their first use? Feasible.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 6824,
                            ["icon"] = "/esoui/art/icons/mount_potentatehorse.dds",
                            ["category"] = "Equines",
                        },
                        [8091] = 
                        {
                            ["name"] = "Akaviri Potentate Guar",
                            ["hint"] = "",
                            ["id"] = 8091,
                            ["description"] = "\"While I find the idea of 'Dark Elf assassins chasing Reman's loyalists in Morrowind on luminous Potentate guar steeds' to be laughably absurd, Mirannah's date of 2E 27 seems accurate for the first use of these ferocious mounts.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 6825,
                            ["icon"] = "/esoui/art/icons/mount_potentateguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [8092] = 
                        {
                            ["name"] = "Akaviri Potentate Camel",
                            ["hint"] = "",
                            ["id"] = 8092,
                            ["description"] = "\"The Potentate bought several herds of camels in 2E 25 for delivery to Versidue-Shaie, Mirannah of Gwylim states. 'Reman desert pursuit' and 'enchanted barding like bear' are also true. Chased by glowing camels—what a sight!\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 6826,
                            ["icon"] = "/esoui/art/icons/mount_otentatecamel.dds",
                            ["category"] = "Camelids",
                        },
                        [8093] = 
                        {
                            ["name"] = "Keldora",
                            ["hint"] = "",
                            ["id"] = 8093,
                            ["description"] = "Keldora left her adventuring life behind to fulfill her dream of overseeing and organizing a connoisseur's mead collection, though she possesses expertise in all forms of alcohol. After adding Keldora to your home, you can set her on a path.",
                            ["furnitureId"] = 6827,
                            ["icon"] = "/esoui/art/icons/assistant_keldora.dds",
                            ["category"] = "Houseguests",
                        },
                        [6462] = 
                        {
                            ["name"] = "Mind-Shriven Wolf",
                            ["hint"] = "",
                            ["id"] = 6462,
                            ["description"] = "\"You might think Mind-Shriven Wolves are fragile beasts, but their environment has instilled within them a hidden strength. \"—Warlock Aldaale",
                            ["furnitureId"] = 6009,
                            ["icon"] = "/esoui/art/icons/mount_mindshrivenwolf.dds",
                            ["category"] = "Canines",
                        },
                        [6464] = 
                        {
                            ["name"] = "Kynbound Senche-Panther",
                            ["hint"] = "",
                            ["id"] = 6464,
                            ["description"] = "Known as steeds of the Dremora, Kynbound Senche-Panthers have found their way into service as mounts for those who have some ties to the Dremora. Perhaps that's you?",
                            ["furnitureId"] = 6011,
                            ["icon"] = "/esoui/art/icons/mount_sanguivorianhowler.dds",
                            ["category"] = "Felines",
                        },
                        [8096] = 
                        {
                            ["name"] = "Sister Gellenna",
                            ["hint"] = "",
                            ["id"] = 8096,
                            ["description"] = "Gellena left the Icereach Coven to see firsthand what they loathed about other cultures—and to consider what scores she needs to settle. After adding Gellena to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 6830,
                            ["icon"] = "/esoui/art/icons/assistant_gellenna.dds",
                            ["category"] = "Houseguests",
                        },
                        [8097] = 
                        {
                            ["name"] = "Acolyte Deras Arelas",
                            ["hint"] = "",
                            ["id"] = 8097,
                            ["description"] = "Told to go \"find yourself\" by a Tribunal superior, Deras traveled enough to find all but himself. Now he seeks a quiet meditation spot. After adding Deras to your home, you can set him on a path.",
                            ["furnitureId"] = 6831,
                            ["icon"] = "/esoui/art/icons/assistant_derasarelas.dds",
