                            ["category"] = "Ursines",
                        },
                        [6466] = 
                        {
                            ["name"] = "Sunspire Champion Senche-Lion",
                            ["hint"] = "Acquired by completing the \"Sunspire Dragonbreak\" Achievement.",
                            ["id"] = 6466,
                            ["description"] = "Those skilled enough to overcome Sunspire can earn a special variant of the Sunspire Ice-Fire Senche-Lion. With golden armor and gear, this mount shines, reflecting your own adventuring glory.",
                            ["furnitureId"] = 6013,
                            ["icon"] = "/esoui/art/icons/mount_sunspiresenchelion.dds",
                            ["category"] = "Felines",
                        },
                        [324] = 
                        {
                            ["name"] = "Northern Lynx",
                            ["hint"] = "",
                            ["id"] = 324,
                            ["description"] = "Native to Tamriel's northern forests, in the wild the Lynx lives on a diet of rabbits, hares, and skeevers. Domesticated, the Lynx makes a dignified and stylish animal companion, popular with the Nord aristocracy.",
                            ["furnitureId"] = 4266,
                            ["icon"] = "/esoui/art/icons/pet_061.dds",
