                            ["category"] = "Undaunted Busts",
                        },
                        [6064] = 
                        {
                            ["name"] = "Elinhir Arena Lion",
                            ["hint"] = "Acquired by combining 40 Arena Gladiator's Proofs, available by completing Conquest Missions in Cyrodiil, with an Arena Gladiator's Roar, available for purchase from War Researchers in Cyrodiil.",
                            ["id"] = 6064,
                            ["description"] = "Arena Lions are trained to absolute obedience, whether as sturdy and savage Craglorn companions or as pit-fighting beasts taught to drag out a kill for the entertainment of an audience.",
                            ["furnitureId"] = 5869,
                            ["icon"] = "/esoui/art/icons/pet_256_gladiatorlion.dds",
                            ["category"] = "Exotic",
                        },
                        [325] = 
                        {
                            ["name"] = "Colovian Badger",
                            ["hint"] = "",
                            ["id"] = 325,
                            ["description"] = "Though Badgers mainly eat burrowing rodents, farmers hate them because they'll take chickens, kwama scribs, and bantam guar if they get the chance. Cranky and irritable, they make terrible pets—which makes them a favorite among the Undaunted.",
                            ["furnitureId"] = 4267,
                            ["icon"] = "/esoui/art/icons/pet_062.dds",
                            ["category"] = "Exotic",
                        },
                        [326] = 
                        {
                            ["name"] = "Red Pit Wolf",
                            ["hint"] = "",
                            ["id"] = 326,
                            ["description"] = "Pit Wolves are so called because they were bred by the Reachmen as fierce pit fighters, often matched against bears or bristlebacks. In order to make his guards more impressive, the Tyrant of Markarth was the first to have Red Pits trained as mounts.",
                            ["furnitureId"] = 4268,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_c.dds",
                            ["category"] = "Canines",
                        },
                        [1359] = 
                        {
                            ["name"] = "Witch Knight Charger",
                            ["hint"] = "",
                            ["id"] = 1359,
                            ["description"] = "During their invasion of High Rock, the Reachmen were profoundly impressed by the power and splendor of the Breton mounted knights, and decided to breed their own hardy northern steeds to the same size. They succeeded!",
                            ["furnitureId"] = 4458,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_m-witchkn.dds",
                            ["category"] = "Equines",
                        },
                        [1360] = 
                        {
                            ["name"] = "Frost Draugr Charger",
                            ["hint"] = "",
                            ["id"] = 1360,
                            ["description"] = "Now seen well outside Skyrim, these skeletal horses once served among Ysgramor's soldiers and were honored after their deaths—or so says one of the epic ballads found in Solitude's Bards College. Dare you ride a steed of such provenance? Of course!",
                            ["furnitureId"] = 4459,
                            ["icon"] = "/esoui/art/icons/mount_frostdrauger.dds",
                            ["category"] = "Equines",
                        },
                        [1361] = 
                        {
                            ["name"] = "Nix-Ox War-Steed",
                            ["hint"] = "",
                            ["id"] = 1361,
                            ["description"] = "It was the warlike Erabenimsun tribe of Ashlanders who first broke the wild Nix-Oxen of Vvardenfell to domestic use, and an ashkhan, the legendary Ashu-Ammu, who first rode one into battle.",
                            ["furnitureId"] = 4460,
                            ["icon"] = "/esoui/art/icons/mounticon_nixox_a.dds",
                            ["category"] = "Arthropods",
                        },
                        [1362] = 
                        {
                            ["name"] = "Plague Husk Senche",
                            ["hint"] = "",
                            ["id"] = 1362,
                            ["description"] = "\"Some argue that nothing good came from the Llodos Plague, but I disagree. Ride this noxious necromantic senche, and you'll quickly find all the Peryite followers in a crowd. Perfect if you're hunting one down.\"—Sondryn Fyr, Assassin",
                            ["furnitureId"] = 4461,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["category"] = "Felines",
                        },
                        [6489] = 
                        {
                            ["name"] = "Whispering-Claw Senche-Raht",
                            ["hint"] = "",
                            ["id"] = 6489,
                            ["description"] = "Feanirr witnessed the demise of her proud adeptorium, not to war, but to a sickness faster and stealthier than all but her. Since then, she lives only in the moment, knowing that at any moment something deadlier than her could catch her by the tail.",
                            ["furnitureId"] = 6733,
                            ["icon"] = "/esoui/art/icons/mount_sencherahtc.dds",
                            ["category"] = "Heavyweights",
                        },
                        [6490] = 
                        {
                            ["name"] = "Queen's Claw Senche-Raht",
                            ["hint"] = "",
                            ["id"] = 6490,
                            ["description"] = "A scholar studying Mnemoli the Blue Star as well as a Whispering Claw warrior, this Senche-raht serves Queen Khamira with both brain and brawn. He volunteered to travel with you, lending you speed and steady companionship.",
                            ["furnitureId"] = 6663,
                            ["icon"] = "/esoui/art/icons/mount_queenclawsencheraht.dds",
                            ["category"] = "Heavyweights",
                        },
                        [1371] = 
                        {
                            ["name"] = "Dire Pony",
                            ["hint"] = "",
                            ["id"] = 1371,
                            ["description"] = "When you always wanted a pony as a child and your parents wouldn't let you have one so you grew up bitter and tormented and became a dark cultist but now you can finally afford a pony.",
                            ["furnitureId"] = 4462,
                            ["icon"] = "/esoui/art/icons/pet_144.dds",
                            ["category"] = "Exotic",
                        },
                        [1372] = 
                        {
                            ["name"] = "Plague Husk Horse",
                            ["hint"] = "",
                            ["id"] = 1372,
                            ["description"] = "A zombie horse is fearsome enough—but a Plague Husk Horse, wreathed in a glowing miasma of toxic infection, is a truly terrifying mount!",
                            ["furnitureId"] = 4463,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_plague-husk.dds",
                            ["category"] = "Equines",
                        },
                        [1373] = 
                        {
                            ["name"] = "Shadowghost Senche",
                            ["hint"] = "",
                            ["id"] = 1373,
                            ["description"] = "An oversized breed of black senche-panthers, the Shadowghost Senche is said by the Khajiit to be sacred—or rather unholy—to Namiira the Great Darkness, who sends them as mounts to bear away those who are doomed to die.",
                            ["furnitureId"] = 4464,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_shadow-ghost.dds",
                            ["category"] = "Felines",
                        },
                        [8124] = 
                        {
                            ["name"] = "Unstable Morpholith",
                            ["hint"] = "",
                            ["id"] = 8124,
                            ["description"] = "\"The instability inherent in the structure of some morpholiths makes them unsuitable for use as sigil stones, yet that doesn't stop certain Daedric Princes from trying. Imagine the surprise when said portals don't work.\"—Warlock Aldaale",
                            ["furnitureId"] = 7264,
                            ["icon"] = "/esoui/art/icons/pet_sigilstone.dds",
                            ["category"] = "Flying Pets",
                        },
                        [1374] = 
                        {
                            ["name"] = "Shadowghost Pony",
                            ["hint"] = "",
                            ["id"] = 1374,
                            ["description"] = "It's said that to catch a Shadowghost Pony, one should seek out a cemetery on a dark night during Witches Festival and wait quietly near the grave of a child. Bring a carrot or sweet apple.",
                            ["furnitureId"] = 4465,
                            ["icon"] = "/esoui/art/icons/pet_149.dds",
                            ["category"] = "Domestic",
                        },
                        [5471] = 
                        {
                            ["name"] = "Auroran Twilight Warhorse",
                            ["hint"] = "",
                            ["id"] = 5471,
                            ["description"] = "Like their mistress, the Daedric Prince Meridia, Aurorans have magical control over color and hue, so when they need a mount in Tamriel after dark it's no surprise that they conjure Warhorses that are as dark as night itself.",
                            ["furnitureId"] = 5411,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_twilightauroran.dds",
                            ["category"] = "Equines",
                        },
                        [1376] = 
                        {
                            ["name"] = "Frost Draugr Senche",
                            ["hint"] = "",
                            ["id"] = 1376,
                            ["description"] = "What were senche-tiger mounts doing in ancient Skyrim, and why were their half-frozen bodies mummified beside the Draugr in certain dark Nord catacombs? And why are they rising now, imbued with animating frost magic? The answers are as yet unknown.",
                            ["furnitureId"] = 4467,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_frost-draugr.dds",
                            ["category"] = "Felines",
                        },
                        [1377] = 
                        {
                            ["name"] = "Cinder Skeletal Senche",
                            ["hint"] = "",
                            ["id"] = 1377,
                            ["description"] = "\"Long-held grudges and rage simmer within this skeletal senche—fitting given its supposed origin as a battle steed for Orcs fighting within the Ashen Forge! This mount's riders gain the utmost respect from Malacath's adherents.\"—Erisa Moorcroft",
                            ["furnitureId"] = 4468,
                            ["icon"] = "/esoui/art/icons/mount_skeletalcsenche.dds",
                            ["category"] = "Felines",
                        },
                        [1378] = 
                        {
                            ["name"] = "Skeletal Cat",
                            ["hint"] = "",
                            ["id"] = 1378,
                            ["description"] = "Even dark necromancers have feelings—some of them, anyway—and love their companion pets. Some love them so much they reanimate them after they pass away.",
                            ["furnitureId"] = 4797,
                            ["icon"] = "/esoui/art/icons/pet_1378.dds",
                            ["category"] = "Exotic",
                        },
                        [355] = 
                        {
                            ["name"] = "Dominion Lizard-Locks",
                            ["hint"] = "",
                            ["id"] = 355,
                            ["description"] = "Going to war may mean donning a helm, but beneath it an Argonian Dominion warrior is entitled to wear these official Alliance Lizard-Locks, which keep beaded bristles under control while still looking superb.",
                            ["furnitureId"] = 4269,
                            ["icon"] = "/esoui/art/icons/hair_unisex_argonian_aldmeriflavor_01.dds",
                            ["category"] = "Hair Styles",
                        },
                        [8131] = 
                        {
                            ["name"] = "Solitude Guard Jorn",
                            ["hint"] = "",
                            ["id"] = 8131,
                            ["description"] = "A man of few words, Jorn stood guard over Solitude's bank until a recent illness laid him low. Now, his position filled by another, he needs work—perhaps a guard position in your home! After adding Jorn to your home, you can set him on a path.",
                            ["furnitureId"] = 7255,
                            ["icon"] = "/esoui/art/icons/assistant_guardjorn.dds",
                            ["category"] = "Houseguests",
                        },
                        [8132] = 
                        {
                            ["name"] = "Historian Phedre",
                            ["hint"] = "",
                            ["id"] = 8132,
                            ["description"] = "Phedre loves history. A lot. Give her a place to study, and her gratitude nears \"eternal\"—as does her wish to share what she learns. After adding Phedre to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 7256,
                            ["icon"] = "/esoui/art/icons/assistant_phedre.dds",
                            ["category"] = "Houseguests",
                        },
                        [8133] = 
                        {
                            ["name"] = "Whiterun Windsteed",
                            ["hint"] = "",
                            ["id"] = 8133,
                            ["description"] = "Ride like the wind on this fleet and sure-footed horse! A favorite of stablemasters, Whiterun Windsteeds possess steady temperaments and gentle gaits, making them the perfect first mount for any rider.",
                            ["furnitureId"] = 7183,
                            ["icon"] = "/esoui/art/icons/mount_whiterunwindsteed.dds",
                            ["category"] = "Equines",
                        },
                        [8134] = 
                        {
                            ["name"] = "Mara's Blush Butterfly",
                            ["hint"] = "",
                            ["id"] = 8134,
                            ["description"] = "Delicate in both form and color, this pink-hued butterfly flits around Elsweyr, Skyrim, Rivenspire—and around you! Tailor Medresi Grulathil looked to her own butterfly companion for inspiration while crafting ceremonial garb honoring Mara in Solitude.",
                            ["furnitureId"] = 7204,
                            ["icon"] = "/esoui/art/icons/pet_pinkbutterfly.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10183] = 
                        {
                            ["name"] = "Painting: Dagon's Mercy",
                            ["hint"] = "",
                            ["id"] = 10183,
                            ["description"] = "A painting of Mehrunes Dagon, towering over his cultists in the Deadlands.",
                            ["furnitureId"] = 8198,
                            ["icon"] = "/esoui/art/icons/housing_bad_inc_housingwoodframedagonpainting001.dds",
                            ["category"] = "General",
                        },
                        [10184] = 
                        {
                            ["name"] = "Giladil the Ragpicker",
                            ["hint"] = "",
                            ["id"] = 10184,
                            ["description"] = "Giladil happily trades items you don't need for useful crafting materials! She doesn't ply her trade in Cyrodiil or Battlegrounds because those areas aren't lucrative enough.\n\nAfter she's summoned, you and your groupmates can use her services.",
                            ["furnitureId"] = 8220,
                            ["icon"] = "/esoui/art/icons/assistant_giladiltheragpicker.dds",
                            ["category"] = "Assistants",
                        },
                        [364] = 
                        {
                            ["name"] = "Clockwork Shalk",
                            ["hint"] = "",
                            ["id"] = 364,
                            ["description"] = "The Clockwork Shalk is a fabricant from the hidden laboratories of Sotha Sil. It seems programmed to obey the master it imprints upon, but who knows what secret orders it will follow if events occur to trigger them?",
                            ["furnitureId"] = 4272,
                            ["icon"] = "/esoui/art/icons/pet_124.dds",
                            ["category"] = "Exotic",
                        },
                        [10186] = 
                        {
                            ["name"] = "Stoneglow Imp",
                            ["hint"] = "",
                            ["id"] = 10186,
                            ["description"] = "\"Don't let those icy blue eyes fool you. It's their claws you need to keep an eye on—they can shatter stone, leaving behind nothing but glowing rubble. Thankfully, they're actually quite good-natured creatures once they imprint on you.\"—Divayth Fyr",
                            ["furnitureId"] = 8246,
                            ["icon"] = "/esoui/art/icons/pet_stoneglowimp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [12235] = 
                        {
                            ["name"] = "Tanlorin",
                            ["hint"] = "Obtained by completing quest \"Of Crown and Flowers.\"",
                            ["id"] = 12235,
                            ["description"] = "Some may call Tanlorin a rabble-rouser or rapscallion. They much prefer being called a friend. After adding Tanlorin to your home, you can set them on a path to wander. You can also speak with them. But be warned, they're a bit of a talker.",
                            ["furnitureId"] = 10478,
                            ["icon"] = "/esoui/art/icons/u44_companion_tanlorin_houseguest.dds",
                            ["category"] = "Houseguests",
                        },
                        [12236] = 
                        {
                            ["name"] = "Zerith-var",
                            ["hint"] = "Obtained by completing quest \"The Dark Behind the World.\"",
                            ["id"] = 12236,
                            ["description"] = "Though far from his own time, Zerith-var is sure to brighten any living space with his thoughtful observations and warm company. After adding Zerith to your home, you and guests can speak to him. You can also let him wander by setting him on a path.",
                            ["furnitureId"] = 10479,
                            ["icon"] = "/esoui/art/icons/u44_companion_zerith_houseguest.dds",
                            ["category"] = "Houseguests",
                        },
                        [12237] = 
                        {
                            ["name"] = "Crystaljack",
                            ["hint"] = "Obtained by completing quest \"In Memory Of.\"",
                            ["id"] = 12237,
                            ["description"] = "These mesmerizing creatures hail from the Daedric realm of Mirrormoor. Unlike some of the other denizens of that realm, Crystaljacks appear to be organic in nature, with shimmering skin that simply mimics the appearance of mirrored surfaces.",
                            ["furnitureId"] = 9776,
                            ["icon"] = "/esoui/art/icons/pet_prismwasp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [8845] = 
                        {
                            ["name"] = "Lyranth",
                            ["hint"] = "",
                            ["id"] = 8845,
                            ["description"] = "What do you really know about the mysterious Dremora Lyranth aside from her affiliation with Coldharbour's Foolkiller clan? Listen and maybe learn. After adding Lyranth to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["furnitureId"] = 7399,
                            ["icon"] = "/esoui/art/icons/assistant_lyranth.dds",
                            ["category"] = "Houseguests",
                        },
                        [8835] = 
                        {
                            ["name"] = "Nighthaunt Gloomspore Senche",
                            ["hint"] = "",
                            ["id"] = 8835,
                            ["description"] = "\"I named these senches Nighthaunts because, I suspect, the cult of Vaermina curiosities I was studying during their creation affected their appearance and intensified their glow. Not their nature. Grim-looking they are, yes, but not evil.\"—Mage Naleldil",
                            ["furnitureId"] = 7398,
                            ["icon"] = "/esoui/art/icons/mount_nighthauntgloomsenche.dds",
                            ["category"] = "Felines",
                        },
                        [8823] = 
                        {
                            ["name"] = "Fledgling Terror Bird",
                            ["hint"] = "",
                            ["id"] = 8823,
                            ["description"] = "Taming even a young terror bird requires patience, full-coverage armor, and even more patience. The result, however, can put pause to any seeking to cast you in the role of victim. Plus these fledglings cuddle so nicely while making cute sleeping noises!",
                            ["furnitureId"] = 7397,
                            ["icon"] = "/esoui/art/icons/pet_terrorbird.dds",
                            ["category"] = "Exotic",
                        },
                        [431] = 
                        {
                            ["name"] = "Lizard Rhinoceros",
                            ["hint"] = "",
                            ["id"] = 431,
                            ["description"] = "Even more legendary than the unicorn is that imaginary two-horned beast called the rhinoceros. Live the legend with Lizard Rhinoceros horns!",
                            ["furnitureId"] = 4288,
                            ["icon"] = "/esoui/art/icons/hair_unisex_argonian_lizardrhinoceros.dds",
                            ["category"] = "Hair Styles",
                        },
                        [1456] = 
                        {
                            ["name"] = "Frostbane Guar",
                            ["hint"] = "",
                            ["id"] = 1456,
                            ["description"] = "Since the Guar is native to warmer climates, the existence of the Frostbane Guar in Skyrim, theoretically protected from the cold by its dangling talismans, may be the strongest argument of those who say the Frostbane wards actually work.",
                            ["furnitureId"] = 4798,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_scalecaller.dds",
                            ["category"] = "Bipedals",
                        },
                        [1457] = 
                        {
                            ["name"] = "Frostbane Wolf",
                            ["hint"] = "",
                            ["id"] = 1457,
                            ["description"] = "The Sacred Wolf was one of the most revered Atmoran animal totems, associated by later Nords with the goddess Mara. The great Frostbane Wolf is therefore one of the most iconic mounts of the ancient Nords.",
                            ["furnitureId"] = 4799,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_scalecaller.dds",
                            ["category"] = "Canines",
                        },
                        [12244] = 
                        {
                            ["name"] = "Riverhold Chestnut Horse",
                            ["hint"] = "",
                            ["id"] = 12244,
                            ["description"] = "The people of Riverhold have bred these horses for generations. The result is a line of bright-eyed and faithful steeds, eager to please with their rich chestnut coat. On the road, few horses are steadier or more reliable.",
                            ["furnitureId"] = 9781,
                            ["icon"] = "/esoui/art/icons/mount_riverholdchestnuthorse.dds",
                            ["category"] = "Equines",
                        },
                        [12245] = 
                        {
                            ["name"] = "Dragonclaw Imperial Warbear",
                            ["hint"] = "Acquired by completing the \"Imperial Warbear Seeker\" Achievement.",
                            ["id"] = 12245,
                            ["description"] = "Very few mounts take to battle as readily as a warbear. This one answers only to the strength of its rider. Between its fierce disposition and ursine defenses, it has little to fear from any foes on the battlefield.",
                            ["furnitureId"] = 9782,
                            ["icon"] = "/esoui/art/icons/mount_dragonclawimperialwarbear.dds",
                            ["category"] = "Ursines",
                        },
                        [476] = 
                        {
                            ["name"] = "Haj Mota Hatchling",
                            ["hint"] = "",
                            ["id"] = 476,
                            ["description"] = "Though it may some day grow into a horrific face-eating behemoth, when it's young the Haj Mota Hatchling is undeniably cute. For a while, they are trainable, come when called, and happily waddle after their masters wherever they may go.",
                            ["furnitureId"] = 4291,
                            ["icon"] = "/esoui/art/icons/pet_076.dds",
                            ["category"] = "Exotic",
                        },
                        [8151] = 
                        {
                            ["name"] = "Trophy: Lord Falgravn",
                            ["hint"] = "Awarded for completing Kyne's Aegis.",
                            ["id"] = 8151,
                            ["description"] = "Trophy taken from Lord Falgravn in honor of an Undaunted victory in Kyne's Aegis.",
                            ["furnitureId"] = 7210,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyfalgravn001.dds",
                            ["category"] = "Undaunted Trophies",
                        },
                        [8152] = 
                        {
                            ["name"] = "Bust: Lord Falgravn",
                            ["hint"] = "Awarded for completing Veteran Kyne's Aegis.",
                            ["id"] = 8152,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Kyne's Aegis.",
                            ["furnitureId"] = 7211,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialfalgravn001.dds",
                            ["category"] = "Undaunted Busts",
                        },
                        [8153] = 
                        {
                            ["name"] = "Barnacle-Back Coral Crab",
                            ["hint"] = "",
                            ["id"] = 8153,
                            ["description"] = "While many crustaceans struggle to remove clinging barnacles, the Barnacle-Back Coral Crabs appreciate the company. Some naturalists believe the crabs welcome their guests' sharpened shells as an added protective layer. But maybe they're just gregarious!",
                            ["furnitureId"] = 7543,
                            ["icon"] = "/esoui/art/icons/pet_coralmudcrabb.dds",
                            ["category"] = "Exotic",
                        },
                        [8154] = 
                        {
                            ["name"] = "Ambergill Guar",
                            ["hint"] = "",
                            ["id"] = 8154,
                            ["description"] = "\"The amber glow of this Gill Guar marks its origin as Gideon. Gideon Glowgill Guar is a mouthful, yeah? That's why it's an Ambergill instead. Watching a herd of these race out from Gideon? Impressive, just like their riders!\"—Ukaspa of Lilmoth",
                            ["furnitureId"] = 7213,
                            ["icon"] = "/esoui/art/icons/mount_amergillguar.dds",
                            ["category"] = "Bipedals",
                        },
                        [8155] = 
                        {
                            ["name"] = "Black Fredas Ashen Sabre Cat",
                            ["hint"] = "",
                            ["id"] = 8155,
                            ["description"] = "With the chaos and mischance of Black Fredas on your side, you're sure to cause quite a stir when you pass through town—none wish to catch the eye of your Ashen Sabre Cat lest they fall under its curse!",
                            ["furnitureId"] = 7214,
                            ["icon"] = "/esoui/art/icons/mount_blackfredassabercat.dds",
                            ["category"] = "Felines",
                        },
                        [8156] = 
                        {
                            ["name"] = "Blazeborn Wolf",
                            ["hint"] = "",
                            ["id"] = 8156,
                            ["description"] = "None can say the Blazeborn Wolf lacks a bold appearance, formed from flames as it is. Even bolder, though, is its temperament, making it a perfect companion for racing through icy wastes to confront foes you deem worthy of your courage!",
                            ["furnitureId"] = 7215,
                            ["icon"] = "/esoui/art/icons/mount_blazebornwolf.dds",
                            ["category"] = "Canines",
                        },
                        [8157] = 
                        {
                            ["name"] = "Riften Coalhorn Ram",
                            ["hint"] = "",
                            ["id"] = 8157,
                            ["description"] = "None dare stare Riften's native ram in the eyes—it sees threats in many things, and only its owner can meet its gaze without needing to brace for an immediate headbutt. In short, would-be Riften Coalhorn Ram thieves are frequently airborne.",
                            ["furnitureId"] = 7216,
                            ["icon"] = "/esoui/art/icons/mount_blackram.dds",
                            ["category"] = "Cervines",
                        },
                        [8158] = 
                        {
                            ["name"] = "Chaurus Egg Chaser's Horse",
                            ["hint"] = "",
                            ["id"] = 8158,
                            ["description"] = "Trained with special care, a chaurus egg hunter's horse requires an even temper, a smooth gait, and the ability to navigate through dark passages with equanimity. This steadfast mount will break few—if any—of your prized eggs!",
                            ["furnitureId"] = 7217,
                            ["icon"] = "/esoui/art/icons/mount_chaurusegggatherer.dds",
                            ["category"] = "Equines",
                        },
                        [8159] = 
                        {
                            ["name"] = "Nagahide Welwa Ravager",
                            ["hint"] = "",
                            ["id"] = 8159,
                            ["description"] = "As stablehands across Tamriel can attest, the ravager comes by its name honestly, destroying anything that moves between it and its master. Scholars speculate that the blue Hist of Dead-Water Village brought forth this green-hided breed.",
                            ["furnitureId"] = 7218,
                            ["icon"] = "/esoui/art/icons/mount_welwa.dds",
                            ["category"] = "Heavyweights",
                        },
                        [8160] = 
                        {
                            ["name"] = "Potentate Cloudracer Courser",
                            ["hint"] = "",
                            ["id"] = 8160,
                            ["description"] = "\"Yes, 2E 30 seems right for the first Cloudracer steed, but Mirannah of Gwylim's notes about them being spectral fall into fiction. While their creation is a mystery, I suspect magic is involved.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 7219,
                            ["icon"] = "/esoui/art/icons/mount_radpotentatehorse.dds",
                            ["category"] = "Equines",
                        },
                        [8161] = 
                        {
                            ["name"] = "Potentate Halcyon Senche",
                            ["hint"] = "",
                            ["id"] = 8161,
                            ["description"] = "\"Having ridden this ephemeral senche, I see why Mirannah insists they are spirits. Her origin date of 2E 29 doesn't match another's 2E 35—either could be true. Regardless, its roar calls forth magic, making it a memorable ride!\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 7220,
                            ["icon"] = "/esoui/art/icons/mount_potentateradsenche.dds",
                            ["category"] = "Felines",
                        },
                        [10210] = 
                        {
                            ["name"] = "Nibenay Bay Ram",
                            ["hint"] = "",
                            ["id"] = 10210,
                            ["description"] = "\"Sturdy rams graze the lush meadowlands all around Nibenay Bay. An amusing tale claims they first became steeds because the local herbalist wearied of them eating all the nirnroot. They were trained to saddle and now, here we are.\"—Sadia Vonius, Student",
                            ["furnitureId"] = 8260,
                            ["icon"] = "/esoui/art/icons/mount_mottledram.dds",
                            ["category"] = "Cervines",
                        },
                        [10211] = 
                        {
                            ["name"] = "Su-Zahleel Horse-Lizard",
                            ["hint"] = "",
                            ["id"] = 10211,
                            ["description"] = "\"Lizard-steeds are a gift from the Hist. They have dependable backs and dry scales. You know, we only realized how entwined our roots were when we trekked back from Mazzatun. These beasts kept us off our aching feet.\"—Skeexalttul, Su-Zahleel Ambassador",
                            ["furnitureId"] = 8261,
                            ["icon"] = "/esoui/art/icons/mount_xoleelhorse.dds",
                            ["category"] = "Equines",
                        },
                        [10212] = 
                        {
                            ["name"] = "Amberdust Wamasu Hatchling",
                            ["hint"] = "",
                            ["id"] = 10212,
                            ["description"] = "\"I found the wamasu that … resisted my care. It bit my hand. It's blue! Well, more of a tealish color. Did the druid's magic affect the creature? Or was it some other factor? I think I'll release more of them!\"—Valerine Cadiou, Master Beast Tamer",
                            ["furnitureId"] = 8262,
                            ["icon"] = "/esoui/art/icons/pet_amberdustwamasu.dds",
                            ["category"] = "Exotic",
                        },
                        [12261] = 
                        {
                            ["name"] = "Bloodmoon Wolf",
                            ["hint"] = "",
                            ["id"] = 12261,
                            ["description"] = "It is said that when the bloodlust of Hircine's Huntsmen goes unsated for too long, the collective prey drive forms a will and a shape of its own. Once its quarry is scented, the wolf will pursue at all costs, never stopping until it tastes blood.",
                            ["furnitureId"] = 9817,
                            ["icon"] = "/esoui/art/icons/mount_bloodmoonwolf_fix.dds",
                            ["category"] = "Canines",
                        },
                        [12262] = 
                        {
                            ["name"] = "Russet Brekka",
                            ["hint"] = "",
                            ["id"] = 12262,
                            ["description"] = "Animal husbandry experts from Hammerfell and Wrothgar came together in a unique Covenant collaboration to create a good-natured pack animal with a hearty constitution and a pleasing aesthetic. The soft-coated, lovable brekka is the result.",
                            ["furnitureId"] = 9818,
                            ["icon"] = "/esoui/art/icons/mount_russetbrekka.dds",
                            ["category"] = "Camelids",
                        },
                        [10215] = 
                        {
                            ["name"] = "Jakarn",
                            ["hint"] = "",
                            ["id"] = 10215,
                            ["description"] = "Thief though he is, Jakarn promises not to steal from your house if you allow him to stay. But as to your heart? Well, that's a different matter. After adding Jakarn to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["furnitureId"] = 8263,
                            ["icon"] = "/esoui/art/icons/houseguest_jakarn.dds",
                            ["category"] = "Houseguests",
                        },
                        [12264] = 
                        {
                            ["name"] = "Coldharbour Ocular Observer",
                            ["hint"] = "",
                            ["id"] = 12264,
                            ["description"] = "Not all of Molag Bal's eyes are as vigilant as the Prince would like, it would seem. This one exhibits open curiosity about the world! The blinking certainly is creepy, though.",
                            ["furnitureId"] = 9820,
                            ["icon"] = "/esoui/art/icons/pet_molagbalseye.dds",
                            ["category"] = "Daedric",
                        },
                        [10217] = 
                        {
                            ["name"] = "Jester Anglidor",
                            ["hint"] = "",
                            ["id"] = 10217,
                            ["description"] = "This Jester's Fest performer brings all the joy and frivolity of that holiday to your home—perfect for when you wish to host a friendly gathering! After adding Jester Anglidor to your home, you can set him on a path and interact with him.",
                            ["furnitureId"] = 8265,
                            ["icon"] = "/esoui/art/icons/houseguest_jesteranglidor.dds",
                            ["category"] = "Houseguests",
                        },
                        [12266] = 
                        {
                            ["name"] = "Senchal Horned Owl",
                            ["hint"] = "",
                            ["id"] = 12266,
                            ["description"] = "\"This one has always admired the owls around here. Very wise creatures. Most do not get too close, even when offered treats. Most, but not all. This is Hooty. A very clever name, yes? What else does one call a pet owl?\"—Traveling Merchant J'margo",
                            ["furnitureId"] = 9821,
                            ["icon"] = "/esoui/art/icons/pet_senchalhornedowl.dds",
                            ["category"] = "Flying Pets",
                        },
                        [10219] = 
                        {
                            ["name"] = "Statuette: Steadfast Stendarr",
                            ["hint"] = "",
                            ["id"] = 10219,
                            ["description"] = "A miniature statue of the Divine Stendarr, God of Mercy, Justice, and Charity.",
                            ["furnitureId"] = 8266,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_stendarrstatuette001.dds",
                            ["category"] = "General",
                        },
                        [10220] = 
                        {
                            ["name"] = "Statuette: Prince Hew",
                            ["hint"] = "",
                            ["id"] = 10220,
                            ["description"] = "A miniature statue of the Yokudan Prince Hew, who is also known as Prince Hubalajad.",
                            ["furnitureId"] = 8267,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housinghewstatuette001.dds",
                            ["category"] = "General",
                        },
                        [10221] = 
                        {
                            ["name"] = "Painting: The Gates of Brass",
                            ["hint"] = "",
                            ["id"] = 10221,
                            ["description"] = "A painting of the Brass Fortress, seat of power for the Clockwork God, Sotha Sil.",
                            ["furnitureId"] = 8268,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingcarouselclockworkcity001.dds",
                            ["category"] = "General",
                        },
                        [10222] = 
                        {
                            ["name"] = "Frostmoss Imp",
                            ["hint"] = "",
                            ["id"] = 10222,
                            ["description"] = "\"Why do people insist on having imps about? And why especially these kind? They twist whatever you tell them to do into something that serves them best, not you. Only those with an extraordinarily firm hand should even bother with them.\"—Divayth Fyr",
                            ["furnitureId"] = 8269,
                            ["icon"] = "/esoui/art/icons/pet_frostmossimp.dds",
                            ["category"] = "Flying Pets",
                        },
                        [7518] = 
                        {
                            ["name"] = "Cursebound Kagouti",
                            ["hint"] = "",
                            ["id"] = 7518,
                            ["description"] = "This fell monstrosity inspired Maestro Efnort of the Bards College to write the poem \"The Red-Eyed Terror of Zthenganaz.\" In truth, this steed most often chooses intimidation and flight tactics over direct confrontation.",
                            ["furnitureId"] = 6642,
                            ["icon"] = "/esoui/art/icons/mount_cursebondkagouti.dds",
                            ["category"] = "Bipedals",
                        },
                        [10224] = 
                        {
                            ["name"] = "Sterling Cavy",
                            ["hint"] = "",
                            ["id"] = 10224,
                            ["description"] = "\"The cavy's placid essence makes them nature's mediators, dear. I adopted this one years ago. There's an undeniable sophistication in silver hair, you see. It gives one the impression of wisdom, whether earned or not.\"—Lady Arabelle Davaux",
                            ["furnitureId"] = 8270,
                            ["icon"] = "/esoui/art/icons/pet_silverstarcavymara.dds",
                            ["category"] = "Exotic",
                        },
                        [10225] = 
                        {
                            ["name"] = "Bleakrock Snowdog",
                            ["hint"] = "",
                            ["id"] = 10225,
                            ["description"] = "Originally hailing from Bleakrock Isle, these blue-eyed canines love playing in the frosty air and snow of that distant spit of land. In fact, the locals often bring them inside at night just so that they aren't awoken by their antics in the morning.",
                            ["furnitureId"] = 8271,
                            ["icon"] = "/esoui/art/icons/mount_bleakrocksnowdog.dds",
                            ["category"] = "Canines",
                        },
                        [7271] = 
                        {
                            ["name"] = "Hallin's Jackal",
                            ["hint"] = "",
                            ["id"] = 7271,
                            ["description"] = "After news of the Seventh Legion's presence near Hallin's Stand spread, several Evermore citizens moved quickly to protect some at-risk fauna, among them a breed of easily domesticated jackals. Now one of these fierce companions can roam at your side.",
                            ["furnitureId"] = 6551,
                            ["icon"] = "/esoui/art/icons/pet_hallinsjackal.dds",
                            ["category"] = "Exotic",
                        },
                        [7270] = 
                        {
                            ["name"] = "Sovereign Sow",
                            ["hint"] = "Acquired by finding and combining all seven Sovereign Sow collectible fragments found in Stupendous Jester's Festival Boxes during the Jester's Festival.",
                            ["id"] = 7270,
                            ["description"] = "Freed at last from her terrible captivity, and rightfully wedded to Jester King Jorunn, the Sovereign Sow can trundle along at your side to share in your adventures. Who would not want a companion of such royal blood and stately countenance?",
                            ["furnitureId"] = 6550,
                            ["icon"] = "/esoui/art/icons/pet_princesspig.dds",
                            ["category"] = "Domestic",
                        },
                        [785] = 
                        {
                            ["name"] = "Ancestor Moth Swarm",
                            ["hint"] = "",
                            ["id"] = 785,
                            ["description"] = "\"The Ancestor Moths that accompany some mystically-attuned mortals are more than mere insects—they are animated by the loving spirits of the dearly departed, and may grant wisdom and awareness to those they visit.\" —Sister Terran Arminus",
                            ["furnitureId"] = 4326,
                            ["icon"] = "/esoui/art/icons/pet_093.dds",
                            ["category"] = "Flying Pets",
                        },
                        [786] = 
                        {
                            ["name"] = "Devoted Torchbug",
                            ["hint"] = "",
                            ["id"] = 786,
                            ["description"] = "The Wood Elves say that to be followed by a friendly Torchbug is an infallible sign of good fortune. Of course, they also catch them, dry them out, and smoke them in pipes.",
                            ["furnitureId"] = 4327,
                            ["icon"] = "/esoui/art/icons/pet_104.dds",
                            ["category"] = "Flying Pets",
                        },
                        [7111] = 
                        {
                            ["name"] = "Cursebound Wolf",
                            ["hint"] = "",
                            ["id"] = 7111,
                            ["description"] = "Teeth. Lots of sharp teeth. Jutting from gums pulled back in a mirthless, rictus grin. Eager to devour anyone in its path. Yet if you're brave enough to ride it, those frightful teeth will eagerly snap at your foes.",
                            ["furnitureId"] = 6542,
                            ["icon"] = "/esoui/art/icons/mount_curseboundwolf.dds",
                            ["category"] = "Canines",
                        },
                        [10231] = 
                        {
                            ["name"] = "Ashgray Senche-Serval",
                            ["hint"] = "",
                            ["id"] = 10231,
                            ["description"] = "\"House Mornard won't say where it tamed these gorgeous beasts. My guess is Summerset. For a time, only the elder nobles of that house rode their own. Now, after a downturn in Mornard fortunes, you'll find them all over Tamriel.\"—Sadia Vonius, Student",
                            ["furnitureId"] = 8272,
                            ["icon"] = "/esoui/art/icons/mount_argentsencheserval.dds",
                            ["category"] = "Felines",
                        },
                        [7105] = 
                        {
                            ["name"] = "Sacrificial Pocket Mammoth",
                            ["hint"] = "",
                            ["id"] = 7105,
                            ["description"] = "Though the arcane markings on this gray pocket mammoth indicate its status as a sacrificial offering, these creatures often end up trundling along after soft-hearted souls like yourself.",
                            ["furnitureId"] = 6540,
                            ["icon"] = "/esoui/art/icons/pet_pocketmammoth.dds",
                            ["category"] = "Exotic",
                        },
                        [8185] = 
                        {
                            ["name"] = "Potentate Aphotic Wolf",
                            ["hint"] = "",
                            ["id"] = 8185,
                            ["description"] = "\"The inky black form of this steed, first seen in 2E 42 according to Mirannah of Gwylim, reminds me of a Potentate stealth rite used to track down Reman loyalists. I feel a frisson of dread when I ponder my recent ride on one.\"—Honorata Ancrus, Eyevea",
                            ["furnitureId"] = 7221,
                            ["icon"] = "/esoui/art/icons/mount_potentateradwolf.dds",
                            ["category"] = "Canines",
                        },
                        [8186] = 
                        {
                            ["name"] = "Microtized Verminous Fabricant",
                            ["hint"] = "",
                            ["id"] = 8186,
                            ["description"] = "With its sharp teeth, scary spines, and enormous horn, this fabricant follower not only shows that you mean business as you go about your day, but also indicates an appreciation for the complex and refined machines of Sotha Sil.",
                            ["furnitureId"] = 7222,
                            ["icon"] = "/esoui/art/icons/pet_verminousfabricant.dds",
                            ["category"] = "Exotic",
                        },
                        [8187] = 
                        {
                            ["name"] = "Tawny Lambent Guar",
                            ["hint"] = "",
                            ["id"] = 8187,
                            ["description"] = "Frequently seen sniffing items and creatures alike, these Murkmire guar glow a soft amber. Those with close ties to the swamp claim they feel it feeding the guar's light, but some scholars believe the luminescence is simply an alchemical reaction.",
                            ["furnitureId"] = 7223,
                            ["icon"] = "/esoui/art/icons/pet_glowgillguar.dds",
                            ["category"] = "Exotic",
                        },
                        [8188] = 
                        {
                            ["name"] = "Akaviri Potentate Wolf Cub",
                            ["hint"] = "",
                            ["id"] = 8188,
                            ["description"] = "\"Talking with the trainers of the wolf riders that Versidue-Shaie established in 2E 4 allowed me to see the armored pups at play. I adored how they bonelessly stretched on the ground. Hard to believe they grow to be so fierce!\"—Mirannah of Gwylim",
                            ["furnitureId"] = 7224,
                            ["icon"] = "/esoui/art/icons/pet_potentatewolfcub.dds",
                            ["category"] = "Exotic",
                        },
                        [8189] = 
                        {
                            ["name"] = "Akaviri Potentate Sabre Cat Cub",
                            ["hint"] = "",
                            ["id"] = 8189,
                            ["description"] = "\"Before heading to Skyrim in 2E 7, the Potentate had to train sabre cat cubs to the saddle. Watching these cubs pounce while wearing their training barding all these many years later almost made me lose my composure and squeal.\"—Mirannah of Gwylim",
                            ["furnitureId"] = 7225,
                            ["icon"] = "/esoui/art/icons/pet_potentatesabrecub.dds",
                            ["category"] = "Exotic",
                        },
                        [8190] = 
                        {
                            ["name"] = "Akaviri Potentate Pony",
                            ["hint"] = "",
                            ["id"] = 8190,
                            ["description"] = "\"In 2E 5, companies using the new enchanted barding designed by Versidue-Shaie's battlemages received their orders: hunt and kill Reman loyalists. Though initially only horses, ponies and more earned the special barding and training.\"—Mirannah of Gwylim",
                            ["furnitureId"] = 7226,
                            ["icon"] = "/esoui/art/icons/pet_potentatepony.dds",
                            ["category"] = "Exotic",
                        },
                        [8191] = 
                        {
                            ["name"] = "Akaviri Potentate Guar Calf",
                            ["hint"] = "",
                            ["id"] = 8191,
                            ["description"] = "\"The Potentate first mounted up on guar steeds in 2E 27 under the Red Mountain's shadow, but they trained guar calves to the saddle just outside Mournhold. One barded calf demanded nose-pats from me when I visited—I couldn't resist.\"—Mirannah of Gwylim",
                            ["furnitureId"] = 7227,
                            ["icon"] = "/esoui/art/icons/pet_potentateguarcalf.dds",
                            ["category"] = "Exotic",
                        },
                    },
                },
